/** Catálogo de talentos da V3, transcrito das páginas do Notion em 27/09/2026. */
export interface RPGTrainerTalentDefinition {
	id: string;
	name: string;
	kind: 'general' | 'class' | 'apex';
	classId: string | null;
	prerequisite: string;
	text: string;
	source: string;
}
export const RPG_TRAINER_TALENTS: readonly RPGTrainerTalentDefinition[] = [
	{ "id": "arqueologo:acervo-compartilhado", "name": "Acervo Compartilhado", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nDurante um descanso, o Arqueólogo poderá preparar referências sobre uma quantidade de temas igual ao seu bônus de proficiência. Cada tema deverá pertencer a uma área de Conhecimento na qual ele seja treinado.\nUma criatura capaz de compreender as anotações poderá consultá-las por pelo menos um minuto antes de realizar um teste relacionado ao tema. Ela recebe **+2 no teste de Conhecimento**.\nCada referência poderá beneficiar uma criatura por vez, mas continuará disponível enquanto o Arqueólogo não substituir o tema preparado. O bônus não se acumula com outra utilização de Acervo Compartilhado e não fornece informações que o Arqueólogo não possua.", "source": "https://app.notion.com/p/3e3508f8aa6c81b9aed7e9167ffd0880" },
	{ "id": "arqueologo:achado-excepcional", "name": "Achado Excepcional", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 7º nível, Especialista em Fósseis e Leitura Estratigráfica.", "text": "**Pré-requisitos:** Arqueólogo de 7º nível, Especialista em Fósseis e Leitura Estratigráfica.\nQuando o Arqueólogo participa diretamente da localização de um fóssil e conclui sua extração com sucesso, a qualidade final do achado avança um grau na escala:\n```plain text\nFragmentado → Preservado → Excepcional\n```\nA qualidade é determinada normalmente e somente depois recebe esse aumento. Um fóssil Excepcional já está no grau máximo e não poderá avançar além dele.\nO benefício também se aplica quando o Mestre entrega diretamente ao Arqueólogo um fóssil com qualidade aleatória: cada amostra é sorteada e depois avança um grau. Se o Mestre escolher expressamente a qualidade, ela permanece como definida, sem aumento.\nO aumento ocorre uma única vez por fóssil. Fósseis já adquiridos, negociados ou recebidos de outros personagens não mudam de qualidade retroativamente.\nAchado Excepcional não garante que a extração seja bem-sucedida, não restaura o fóssil e não modifica diretamente atributos, IVs, habilidades ou qualquer característica de combate do Pokémon restaurado. Os efeitos do grau de qualidade continuam sendo somente aqueles definidos pelas regras de fósseis.", "source": "https://app.notion.com/p/3e3508f8aa6c810bad03dabe8c283dca" },
	{ "id": "arqueologo:avaliacao-paleontologica-de-campo", "name": "Avaliação Paleontológica de Campo", "kind": "class", "classId": "arqueologo", "prerequisite": "Especialista em Fósseis e domínio do Kit de Arqueologia.", "text": "**Pré-requisitos:** Especialista em Fósseis e domínio do Kit de Arqueologia.\nCom uma breve avaliação, o Arqueólogo reconhece se cada fóssil que possui está fragmentado, preservado ou excepcional. Ao entregar ou descartar uma amostra, pode escolher exatamente qual delas utilizar.\nEle também pode examinar os fósseis de um aliado e revelar a qualidade de cada amostra, sem que o aliado adquira essa capacidade.\nAo estudar um fóssil encontrado em campo com seu Kit de Arqueologia, o Arqueólogo leva dez minutos para identificar sua qualidade e os cuidados necessários para transportá-lo. Se o material estiver contaminado ou muito danificado, o Mestre pode exigir um teste de Conhecimento: Arqueologia e Fósseis.\nA avaliação não melhora nem restaura o fóssil, não substitui o trabalho de um laboratório e não revela características do Pokémon que poderá ser restaurado.", "source": "https://app.notion.com/p/3e3508f8aa6c818bb2b6d69861a7d811" },
	{ "id": "arqueologo:cartografo-de-ruinas", "name": "Cartógrafo de Ruínas", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nDepois de percorrer e examinar uma construção, o Arqueólogo poderá registrar as áreas exploradas em um mapa confiável. O tempo necessário será de aproximadamente um minuto para cada área relevante.\nEnquanto puder consultar o mapa, o Arqueólogo e seus aliados recebem **+2 em testes** para retornar por um caminho já explorado, orientar-se dentro da estrutura, perceber incoerências entre o espaço observado e a planta ou localizar uma passagem cuja existência possa ser deduzida pela geometria.\nO mapa não revela áreas que ainda não foram observadas, passagens sem indícios espaciais nem alterações ocorridas depois do levantamento.", "source": "https://app.notion.com/p/3e3508f8aa6c813a9fadc0583acb1d9c" },
	{ "id": "arqueologo:conservador-de-campo", "name": "Conservador de Campo", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 5º nível.", "text": "**Pré-requisito:** Arqueólogo de 5º nível.\nUtilizando um Kit de Arqueologia, o Arqueólogo poderá estabilizar um artefato, fóssil, documento ou objeto histórico danificado após dez minutos de trabalho.\nUm objeto estabilizado:\n- Não continua se deteriorando em condições normais.\n- Pode ser transportado sem sofrer dano apenas pelo movimento comum.\n- Fica protegido contra umidade, poeira e contato incidental compatíveis com os materiais utilizados.\n- Poderá ser examinado sem agravar danos já existentes.\nA estabilização não restaura partes ausentes, não recupera textos apagados e não torna o objeto resistente a impacto, fogo, imersão ou destruição deliberada. Um novo teste poderá ser exigido se o objeto estiver em estado extremo ou exigir técnica especializada.", "source": "https://app.notion.com/p/3e3508f8aa6c81708ac8c541a7ae2d8e" },
	{ "id": "arqueologo:desarmador-arcaico", "name": "Desarmador Arcaico", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nO Arqueólogo poderá utilizar **Conhecimento — Arqueologia e Fósseis** no lugar de Ladinagem para compreender e manipular mecanismos históricos.\nIsso inclui:\n- Armadilhas mecânicas antigas.\n- Portas acionadas por contrapesos.\n- Fechaduras cerimoniais.\n- Placas de pressão.\n- Mecanismos hidráulicos.\n- Sistemas de roldanas.\n- Dispositivos construídos por civilizações antigas.\nEle ainda precisa das ferramentas apropriadas e de acesso ao mecanismo. O talento não funciona contra sistemas digitais, eletrônicos modernos ou mecanismos cuja lógica não possua relação histórica reconhecível.", "source": "https://app.notion.com/p/3e3508f8aa6c81649288cb4044eca0fa" },
	{ "id": "arqueologo:epigrafista", "name": "Epigrafista", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nDepois de estudar por pelo menos dez minutos uma inscrição histórica, o Arqueólogo poderá realizar um teste de Conhecimento apropriado para interpretar sua estrutura.\nEm caso de sucesso, ele identifica a família linguística ou tradição de escrita, época aproximada, função provável, sentido geral e símbolos, títulos, nomes ou advertências reconhecíveis.\nSe superar a CD por 10 ou mais, poderá traduzir o conteúdo principal, desde que existam referências suficientes.\nO talento não concede fluência no idioma, não decifra códigos sem referência e não recupera partes inexistentes do texto.", "source": "https://app.notion.com/p/3e3508f8aa6c816db867dc8692473ede" },
	{ "id": "arqueologo:especialista-em-fosseis", "name": "Especialista em Fósseis", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nO Arqueólogo recebe **+2 em testes para identificar, localizar, extrair ou preservar fósseis**.\nAo examinar um fóssil por pelo menos um minuto e obter sucesso no teste apropriado, também identifica:\n- A espécie ou família provável.\n- A parte preservada.\n- O estado de conservação.\n- Sinais de montagem ou falsificação.\n- Se o material parece adequado para restauração.\n- Cuidados necessários para transporte.\nO talento não aumenta a qualidade do fóssil encontrado nem garante que ele possa ser restaurado.\n<empty-block/>", "source": "https://app.notion.com/p/3e3508f8aa6c810087c5f18318340e05" },
	{ "id": "arqueologo:expedicionario-de-catacumbas", "name": "Expedicionário de Catacumbas", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nO Arqueólogo recebe **+2 em testes e resistências para reconhecer ou evitar perigos estruturais em ruínas**.\nO benefício poderá ser aplicado contra desabamentos anunciados por sinais físicos, pisos frágeis, túneis instáveis, estruturas prestes a ceder, poeira, escombros, espaços confinados e perigos produzidos pela deterioração da construção.\nO bônus não se aplica a ataques, golpes Pokémon, armadilhas sem relação estrutural ou perigos que não possam ser percebidos fisicamente.", "source": "https://app.notion.com/p/3e3508f8aa6c8134a94de14e1082507d" },
	{ "id": "arqueologo:historia-viva", "name": "História Viva", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 5º nível.", "text": "**Pré-requisito:** Arqueólogo de 5º nível.\nQuando interagir com uma pessoa, comunidade ou instituição cuja tradição histórica conheça, o Arqueólogo poderá utilizar Conhecimento no lugar de Persuasão para demonstrar respeito por costumes locais, solicitar acesso acadêmico, defender a preservação de um local, negociar consulta a um acervo, explicar o valor cultural de uma descoberta ou evitar uma ofensa causada por protocolo histórico.\nO argumento precisa utilizar informação histórica verdadeira e relevante. História Viva não funciona para mentir, ameaçar, seduzir ou negociar assuntos sem relação com o conhecimento apresentado.", "source": "https://app.notion.com/p/3e3508f8aa6c81b9a641ebe63b3cb048" },
	{ "id": "arqueologo:leitura-estratigrafica", "name": "Leitura Estratigráfica", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nDepois de examinar uma área de escavação por dez minutos, o Arqueólogo poderá identificar a camada ou o ponto mais promissor entre as evidências visíveis.\nA próxima busca ou escavação realizada no ponto indicado recebe **+2 no teste** e tem o tempo necessário reduzido pela metade.\nO benefício vale para uma tentativa e poderá ser compartilhado com quem seguir as instruções do Arqueólogo. Uma nova utilização exige outra área, novas evidências ou mudança relevante nas condições.", "source": "https://app.notion.com/p/3e3508f8aa6c81e282bddc80654e51de" },
	{ "id": "arqueologo:memoria-academica", "name": "Memória Acadêmica", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 5º nível.", "text": "**Pré-requisito:** Arqueólogo de 5º nível.\nA Inteligência do Arqueólogo aumenta em **+1**, até o limite definido para atributos da campanha.\nAlém disso, quando realizar um teste de **Conhecimento — Arqueologia e Fósseis**, um resultado natural inferior a **8** no d20 será tratado como **8**.\nIsso não transforma o resultado em sucesso automático, não evita uma falha causada por CD elevada e não altera os efeitos de um resultado natural máximo ou mínimo quando uma regra específica os utilizar.", "source": "https://app.notion.com/p/3e3508f8aa6c81efa367c213cc9de8fb" },
	{ "id": "arqueologo:olho-para-falsificacoes", "name": "Olho para Falsificações", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nO Arqueólogo recebe **+2 em testes para reconhecer falsificações, restaurações ocultas ou alterações recentes em objetos históricos**.\nEm caso de sucesso, poderá identificar material incompatível com a época, técnica anacrônica, envelhecimento artificial, partes substituídas, inscrições posteriores, fragmentos diferentes ou documentos e selos imitados.\nO talento revela a natureza da inconsistência, mas não identifica automaticamente o falsificador nem sua intenção.\n<empty-block/>", "source": "https://app.notion.com/p/3e3508f8aa6c8103bbafdcec54e92455" },
	{ "id": "arqueologo:pesquisa-acelerada", "name": "Pesquisa Acelerada", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 7º nível.", "text": "**Pré-requisito:** Arqueólogo de 7º nível.\nO tempo necessário para utilizar **Leitura do Passado** é reduzido de dez minutos para um minuto quando o Arqueólogo puder examinar diretamente o objeto, inscrição ou local.\nA quantidade de perguntas e as informações disponíveis continuam seguindo Leitura do Passado. Ambientes perigosos, objetos inacessíveis ou evidências muito extensas ainda poderão exigir mais tempo a critério do Mestre.", "source": "https://app.notion.com/p/3e3508f8aa6c8151993fd1611d96ab58" },
	{ "id": "arqueologo:preservacao-paleontologica", "name": "Preservação Paleontológica", "kind": "class", "classId": "arqueologo", "prerequisite": "Arqueólogo de 5º nível, Especialista em Fósseis e Conservador de Campo.", "text": "**Pré-requisitos:** Arqueólogo de 5º nível, Especialista em Fósseis e Conservador de Campo.\nQuando um fóssil sob os cuidados diretos do Arqueólogo estiver prestes a perder um grau de qualidade por causa de extração, preparação, acondicionamento ou transporte inadequado, ele poderá utilizar um Kit de Arqueologia e realizar um teste apropriado definido pelo Mestre.\nEm caso de sucesso, a perda de um grau é evitada. Cada acontecimento que ameace o fóssil exige um novo teste.\nPreservação Paleontológica não aumenta a qualidade original, não recupera graus já perdidos e não protege contra destruição deliberada, ausência completa de materiais adequados, condições extremas inevitáveis ou uma falha grave. O talento conserva um achado; não transforma um fóssil inferior em um superior.", "source": "https://app.notion.com/p/3e3508f8aa6c81548c68ee864dfed67a" },
	{ "id": "arqueologo:resgate-de-reliquia", "name": "Resgate de Relíquia", "kind": "class", "classId": "arqueologo", "prerequisite": "Nenhum.", "text": "**Pré-requisito:** Nenhum.\nA Destreza do Arqueólogo aumenta em **+1**, até o limite definido para atributos da campanha.\nQuando realiza um teste para proteger ou resgatar um objeto histórico, documento, fóssil ou artefato ameaçado por dano, perda ou roubo, o Arqueólogo recebe **+2 no teste**. O bônus também se aplica para perceber uma tentativa de furto ou recuperar o objeto roubado.\nO teste deve contribuir diretamente para a proteção ou recuperação do objeto. Conforme a situação, o Mestre poderá pedir Destreza, Acrobacia, Atletismo, Percepção, Investigação ou outra opção coerente.\nO talento não concede ações ou alcance adicionais, não torna possível salvar um objeto inacessível e não se aplica a ataques nem a batalhas Pokémon.", "source": "https://app.notion.com/p/3e3508f8aa6c811792afcf07dc6f22b2" },
	{ "id": "arqueologo:grande-descobridor", "name": "Ápice — Grande Descobridor", "kind": "apex", "classId": "arqueologo", "prerequisite": "Arqueólogo de 10º nível.", "text": "**Pré-requisito:** Arqueólogo de 10º nível.\nEste ápice não exige outros talentos específicos.\nDepois de examinar pelo menos três fontes distintas de evidência dentro do mesmo sítio histórico, o Arqueólogo poderá realizar uma síntese completa. As fontes poderão incluir inscrições, arquitetura, artefatos, fósseis, documentos ou vestígios físicos.\nUma vez por sítio histórico, ele poderá obter do Mestre três conclusões sustentadas pelas evidências existentes, escolhidas entre:\n- A sequência principal dos acontecimentos.\n- A função original do local.\n- A descoberta mais importante ainda não compreendida.\n- A região explorada com maior chance de esconder algo relevante.\n- O perigo histórico ou estrutural mais importante.\n- A relação do local com outra civilização, pessoa ou acontecimento conhecido.\n- A evidência ausente para confirmar a principal hipótese.\nAs respostas são verdadeiras, mas não revelam informações impossíveis de deduzir nem substituem a exploração da área indicada.", "source": "https://app.notion.com/p/3e3508f8aa6c81a29505c7a55f96e451" },
	{ "id": "arqueologo:mestre-da-escavacao", "name": "Ápice — Mestre da Escavação", "kind": "apex", "classId": "arqueologo", "prerequisite": "Arqueólogo de 10º nível, Especialista em Fósseis e Leitura Estratigráfica.", "text": "**Pré-requisitos:** Arqueólogo de 10º nível, Especialista em Fósseis e Leitura Estratigráfica.\nAo coordenar uma escavação e permanecer presente durante o trabalho:\n- Todos os participantes podem seguir sua Leitura Estratigráfica.\n- O bônus concedido por ela aumenta para **+4**.\n- Falhas por até quatro pontos não destroem nem perdem o achado, seja o teste realizado pelo próprio Arqueólogo ou por um aliado.\n- O tempo total da escavação é reduzido pela metade.\n- Achados extraídos com sucesso já ficam estabilizados para transporte comum.\nFalhas graves, riscos ignorados e perigos externos continuam produzindo consequências normais. O ápice melhora o trabalho da equipe, mas não cria fósseis ou artefatos onde eles não existem.", "source": "https://app.notion.com/p/3e3508f8aa6c8117a07cc231bade4ce8" },
	{ "id": "arqueologo:voz-das-eras", "name": "Ápice — Voz das Eras", "kind": "apex", "classId": "arqueologo", "prerequisite": "Arqueólogo de 10º nível, Epigrafista e Memória Acadêmica.", "text": "**Pré-requisitos:** Arqueólogo de 10º nível, Epigrafista e Memória Acadêmica.\nDepois de estudar por dez minutos uma inscrição histórica que possua conteúdo suficiente, o Arqueólogo compreende automaticamente seu sentido geral, sua função e sua estrutura, mesmo sem conhecer o idioma.\nUm teste de Conhecimento ainda poderá ser exigido para traduzir detalhes exatos, interpretar metáforas culturais, resolver códigos, reconstruir partes danificadas, distinguir duplo sentido ou relacionar o texto a uma tradição extremamente obscura.\nQuando o teste for realizado, um resultado natural inferior a **10** será tratado como **10**.\nVoz das Eras não concede fluência para falar o idioma e não produz conteúdo que tenha sido apagado ou que nunca tenha existido.", "source": "https://app.notion.com/p/3e3508f8aa6c813eb154d4f2d7c3233c" },
	{ "id": "artista:tecnica-assinatura", "name": "Técnica Assinatura", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nEscolha uma modalidade artística específica, como canto, dança, interpretação, música instrumental, comédia, poesia ou outra aprovada pelo Mestre.\nQuando essa modalidade for o elemento principal da apresentação, você recebe:\n```plain text\n+2 em Atuação\n```\nTécnica Assinatura pode ser escolhida novamente para outra modalidade. Não é permitido escolher uma modalidade já selecionada em Técnica Assinatura ou Artista Versátil.", "source": "https://app.notion.com/p/3e4508f8aa6c818090e6c735a5636692" },
	{ "id": "artista:artista-versatil", "name": "Artista Versátil", "kind": "class", "classId": "artista", "prerequisite": "- 5º nível de Artista.", "text": "## Pré-requisitos\n- 5º nível de Artista.\n## Efeito\nEscolha duas modalidades artísticas diferentes e registre ambas ao adquirir este talento. Você recebe os benefícios de Técnica Assinatura com as duas, mesmo que nunca tenha escolhido esse talento.\nNão é permitido repetir uma modalidade já selecionada em Técnica Assinatura ou Artista Versátil. Se já possuir Técnica Assinatura, as duas novas modalidades são adicionais.\nAlém disso, aumente em 1 seu Carisma ou sua Destreza, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81f9bc7dd2e64a3e92d0" },
	{ "id": "artista:presenca-magnetica", "name": "Presença Magnética", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando passa pelo menos um minuto conversando, contando uma história ou demonstrando sua arte para uma criatura, você pode fazer com que sua presença se torne especialmente memorável.\nAté o fim da cena, recebe:\n```plain text\n+2 no primeiro teste de Persuasão, Enganação ou Intimidação realizado contra essa criatura\n```\nEscolha apenas um desses testes. A criatura precisa conseguir perceber você e não pode estar em combate.\nDepois da cena, ela recorda claramente sua aparência e comportamento. Isso pode ser vantajoso para criar reputação, mas também torna mais fácil identificá-lo posteriormente.\nSeu Carisma aumenta automaticamente em 1, respeitando o limite de atributos do sistema. Não há escolha de atributo para esse aumento.", "source": "https://app.notion.com/p/3e4508f8aa6c81bb9f28d947e2155001" },
	{ "id": "artista:voz-projetada", "name": "Voz Projetada", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nSua voz, música ou ritmo pode alcançar claramente uma plateia atenta em até 60 metros sem equipamento de amplificação.\nRuídos comuns, vento moderado e conversas deixam de impor penalidades às suas apresentações e à Expressão Universal.\nBarreiras fechadas, tempestades, máquinas ensurdecedoras e efeitos que impeçam sons continuam funcionando normalmente. Voz Projetada não causa dano nem produz efeitos de combate.", "source": "https://app.notion.com/p/3e4508f8aa6c81f8b81ce0772b62c502" },
	{ "id": "artista:persona-cenica", "name": "Persona Cênica", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nApós observar uma pessoa por pelo menos dez minutos, você pode reproduzir sua aparência com um Kit de Disfarce.\nPreparar o disfarce exige dez minutos e uma carga do kit. Ele pode copiar:\n- Traços físicos visíveis.\n- Cabelo e maquiagem.\n- Roupas que você consiga reproduzir.\n- Postura e gestos observados.\n- Características gerais de voz, sem copiar perfeitamente seu timbre.\nQuando alguém tentar reconhecer a falsificação, realiza Investigação contra seu teste de Enganação ou Atuação.\nO disfarce não concede memórias, conhecimentos, documentos, poderes, relações pessoais nem acesso automático. Diferenças impossíveis de ocultar, como tamanho corporal incompatível, precisam ser resolvidas antes que a imitação seja viável.", "source": "https://app.notion.com/p/3e4508f8aa6c81aa9eb5c230c3f2d170" },
	{ "id": "artista:mimica-precisa", "name": "Mímica Precisa", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nDepois de ouvir uma pessoa ou um som não mecânico por pelo menos um minuto, você consegue reproduzir seu timbre, ritmo e maneirismos sonoros.\nUma criatura que conheça bem a fonte ou tenha motivo para desconfiar realiza Investigação contra seu teste de Atuação para perceber a imitação.\nMímica Precisa pode completar a voz de um disfarce criado por Persona Cênica. Ela não copia senhas desconhecidas, poderes, golpes, frequências eletrônicas ou propriedades especiais do som original.", "source": "https://app.notion.com/p/3e4508f8aa6c810b801edf642e6daeba" },
	{ "id": "artista:corpo-de-cena", "name": "Corpo de Cena", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando sua apresentação depender principalmente de dança, equilíbrio, acrobacia ou expressão corporal, você pode utilizar Destreza no lugar de Carisma no teste de Atuação.\nAlém disso, movimentos cênicos comuns não exigem testes separados de Acrobacia. O Mestre ainda poderá exigir Acrobacia para manobras realmente perigosas ou que produzam efeitos além da apresentação.\nO talento não concede deslocamento, defesa ou benefício em combate.\nAumente também em 1 sua Destreza, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c813784b6e21d50175230" },
	{ "id": "artista:criatividade-sob-pressao", "name": "Criatividade Sob Pressão", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando falhar em um teste fora de combate envolvendo comunicação, criação, distração ou solução improvisada, você poderá tentar contornar o problema com uma abordagem realmente diferente.\nFaça um novo teste com outra perícia ou outro atributo coerente contra:\n```plain text\nCD original +2\n```\nO segundo resultado é definitivo. O talento pode ser utilizado uma vez por cena e não desfaz consequências que já tenham ocorrido, como materiais consumidos, alarmes acionados ou pessoas ofendidas.\nA nova tentativa precisa representar criatividade, não apenas repetir a mesma ação com outra descrição.", "source": "https://app.notion.com/p/3e4508f8aa6c81b09879c6b6e7a9d3c6" },
	{ "id": "artista:inspiracao-artistica", "name": "Inspiração Artística", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nDepois de dedicar um minuto a encorajar um aliado por meio de música, humor, história, poesia, desenho, dança ou outra expressão artística, escolha uma perícia relacionada ao desafio que ele está prestes a enfrentar.\nAté o fim da cena, o aliado recebe:\n```plain text\n+2 no primeiro teste realizado com a perícia escolhida\n```\nA inspiração precisa ser compreendida e relacionada à situação. Uma criatura só pode manter uma Inspiração Artística por vez.\nO bônus não pode ser aplicado a ataques, dano, Precisão, captura, atributos de Pokémon ou testes próprios de combate Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c81d79c9ee55992f30684" },
	{ "id": "artista:artista-itinerante", "name": "Artista Itinerante", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nAo realizar uma apresentação de pelo menos dez minutos em uma comunidade, faça Atuação contra CD 15.\nEm caso de sucesso, você consegue para si e seus companheiros, conforme os recursos do local:\n- Uma refeição comum.\n- Um lugar simples e seguro para dormir por uma noite.\n- Informações públicas sobre a região.\n- Indicação de trabalho, evento ou estabelecimento local.\nEsse benefício não gera Pokécoin, hospedagem luxuosa, itens raros ou favores perigosos.", "source": "https://app.notion.com/p/3e4508f8aa6c81d4b591edd1317c3b6f" },
	{ "id": "artista:rede-de-admiradores", "name": "Rede de Admiradores", "kind": "class", "classId": "artista", "prerequisite": "- 5º nível de Artista.", "text": "## Pré-requisitos\n- 5º nível de Artista.\n## Efeito\nDepois de procurar por uma hora em uma comunidade com atividade cultural, você encontra um admirador, colega de profissão, comerciante de espetáculos ou organizador disposto a conversar.\nEscolha uma ajuda:\n- Apresentar uma pessoa acessível.\n- Compartilhar um rumor local.\n- Reservar um espaço pequeno para apresentação.\n- Entregar uma mensagem comum.\n- Indicar uma oportunidade artística.\n- Informar onde conseguir um equipamento artístico disponível na região.\nUma mesma comunidade oferece apenas um contato relevante por arco, até que as circunstâncias mudem. O contato não assume riscos graves, crimes ou grandes despesas.", "source": "https://app.notion.com/p/3e4508f8aa6c817e80d4f57f9c5d0ca9" },
	{ "id": "artista:composicao-marcante", "name": "Composição Marcante", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nCom uma hora de preparação, você cria uma composição para uma apresentação específica, definindo abertura, momento principal e encerramento.\nAo executar essa composição, recebe:\n```plain text\n+2 em um teste de Atuação da apresentação\n```\nO bônus pode ser aplicado depois da rolagem, mas antes de o Mestre declarar o resultado.\nEm concursos, o benefício pertence à atuação do treinador. Ele não altera a pontuação, o Poder, a Precisão, o PP ou os efeitos dos golpes do Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c8179bbfaf4ceb5a6432c" },
	{ "id": "artista:distracao-cativante", "name": "Distração Cativante", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nFora de combate, você pode manter a atenção de um grupo por meio de conversa, música, humor, dança, encenação ou outra expressão artística.\nFaça Atuação contra a maior Percepção Passiva entre os observadores. Em caso de sucesso, escolha até dois aliados que os observadores consigam perceber.\nEnquanto você sustentar a distração, esses aliados recebem:\n```plain text\n+2 em Furtividade ou Ladinagem contra os observadores distraídos\n```\nUma ação claramente hostil, um alarme ou uma ameaça imediata encerra o efeito. O talento não impede ninguém de reagir ao perigo.", "source": "https://app.notion.com/p/3e4508f8aa6c81f394e0c5449c49f076" },
	{ "id": "artista:bastidores-abertos", "name": "Bastidores Abertos", "kind": "class", "classId": "artista", "prerequisite": "- 5º nível de Artista.", "text": "## Pré-requisitos\n- 5º nível de Artista.\n## Efeito\nEm locais que possuam atividade cultural, você reconhece os caminhos sociais e profissionais usados por artistas, técnicos, comerciantes e organizadores.\nApós dez minutos procurando ou conversando, você descobre uma destas informações:\n- Como entrar legalmente nos bastidores.\n- Quem organiza ou financia o evento.\n- Onde profissionais locais se encontram.\n- Onde conseguir figurinos, instrumentos ou materiais comuns.\n- Qual artista, atração ou conflito domina as conversas.\n- Quem pode apresentar você a um responsável acessível.\nO talento fornece acesso social plausível, não credenciais falsas, invasão automática ou autoridade sobre trabalhadores.", "source": "https://app.notion.com/p/3e4508f8aa6c817cb31cd8f4d9e86587" },
	{ "id": "artista:arte-reconfortante", "name": "Arte Reconfortante", "kind": "class", "classId": "artista", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê pode conduzir uma atividade artística tranquila para até um número de criaturas igual ao seu bônus de proficiência.\nPara cada participante que acompanhar toda a atividade, o Artista escolhe um dos benefícios:\n- Receber +2 no próximo teste de Vontade contra medo realizado antes do próximo descanso longo.\n- Reduzir em 1 o nível de Exaustão.\nVocê poderá voltar a conceder esses benefícios após cada descanso curto. Arte Reconfortante não remove condições sobrenaturais, não recupera PV e não substitui tratamento médico ou psicológico especializado.", "source": "https://app.notion.com/p/3e4508f8aa6c81c08703cbdc2b5e6792" },
	{ "id": "artista:lenda-dos-palcos", "name": "Ápice — Lenda dos Palcos", "kind": "apex", "classId": "artista", "prerequisite": "10º nível de Artista.", "text": "## Pré-requisitos\n10º nível de Artista.\n## Efeito\nSempre que realizar um teste de Atuação, um resultado natural inferior a 10 no d20 é tratado como 10.\nAlém disso, um sucesso em Cativar a Plateia melhora a disposição do público em dois estágios, em vez de um.\nLenda dos Palcos é o ápice disponível para qualquer construção de Artista. Ele não controla a plateia, não obriga pedidos e não afeta criaturas incapazes de acompanhar a apresentação.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c8116bc68c9acd5a6a7ff" },
	{ "id": "artista:mil-faces", "name": "Ápice — Mil Faces", "kind": "apex", "classId": "artista", "prerequisite": "- 10º nível de Artista.\n- Persona Cênica.\n- Mímica Precisa.", "text": "## Pré-requisitos\n- 10º nível de Artista.\n- Persona Cênica.\n- Mímica Precisa.\n## Efeito\nVocê pode manter até seis disfarces completos de pessoas observadas e assumir um deles em um minuto.\nQuando utiliza aparência e voz juntas, recebe:\n```plain text\n+2 no teste para sustentar a imitação\n```\nObservadores sem motivo para suspeitar não realizam teste automaticamente. Quem conhecer intimamente a pessoa, possuir evidências, encontrar contradições ou investigar ativamente ainda poderá contestar o disfarce.\nMil Faces não concede memórias, credenciais, conhecimentos ou capacidades da pessoa imitada.", "source": "https://app.notion.com/p/3e4508f8aa6c8157af9ffed44ca8c0c6" },
	{ "id": "artista:voz-de-uma-geracao", "name": "Ápice — Voz de uma Geração", "kind": "apex", "classId": "artista", "prerequisite": "- 10º nível de Artista.\n- Composição Marcante.\n- Voz Projetada.", "text": "## Pré-requisitos\n- 10º nível de Artista.\n- Composição Marcante.\n- Voz Projetada.\n## Efeito\nCativar a Plateia pode afetar qualquer quantidade de criaturas capazes de acompanhar claramente a mesma apresentação.\nAo incluir uma mensagem simples em sua Composição Marcante, o público consegue recordar sua ideia central por 30 dias. Quando você reapresenta fielmente essa composição em outra comunidade, a mesma mensagem poderá continuar se espalhando.\nO talento amplia alcance e memória cultural, mas não obriga concordância, não altera convicções automaticamente e não transforma informações falsas em fatos.", "source": "https://app.notion.com/p/3e4508f8aa6c8180b099fb62ab1339d5" },
	{ "id": "artista-marcial:golpe-aprimorado", "name": "Golpe Aprimorado", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nO dano dos seus ataques desarmados passa de 1d6 para:\n```plain text\n1d8 + modificador de Força ou Destreza\n```\nVocê continua escolhendo Força ou Destreza a cada ataque e pode causar dano letal ou não letal sem penalidade.\nEste talento melhora somente os ataques realizados pelo treinador.", "source": "https://app.notion.com/p/3e4508f8aa6c8132bbc9e9988bd24d1f" },
	{ "id": "artista-marcial:sequencia-veloz", "name": "Sequência Veloz", "kind": "class", "classId": "artista-marcial", "prerequisite": "- 5º nível de Artista Marcial.", "text": "## Pré-requisitos\n- 5º nível de Artista Marcial.\n## Efeito\nDepois de realizar um ataque desarmado com sua ação, você pode realizar um segundo ataque desarmado usando sua ação bônus.\nO segundo ataque causa o dano normal de Corpo como Arma, incluindo melhorias aplicáveis.\nSequência Veloz não concede ataques, ações ou qualquer benefício aos Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c8119aea6c3b9b61d9c27" },
	{ "id": "artista-marcial:chave-de-contencao", "name": "Chave de Contenção", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê recebe:\n```plain text\n+2 em Atletismo para agarrar ou manter agarrada uma criatura\n```\nAo iniciar um agarrão, pode declarar que está utilizando uma contenção segura. Enquanto mantiver a técnica, seus testes não causam dano acidental e você pode soltar o alvo imediatamente quando desejar.\nO bônus não se aplica contra criaturas cuja anatomia ou tamanho torne o agarrão impossível.", "source": "https://app.notion.com/p/3e4508f8aa6c81d58298cac061cbe718" },
	{ "id": "artista-marcial:imobilizacao-tecnica", "name": "Imobilização Técnica", "kind": "class", "classId": "artista-marcial", "prerequisite": "Chave de Contenção e 5º nível de Artista Marcial.", "text": "- Chave de Contenção.\n\t## Pré-requisitos\n- 5º nível de Artista Marcial.\n## Efeito\nQuando começar seu turno agarrando uma criatura, você pode realizar um novo teste oposto de Atletismo.\nEm caso de sucesso, o alvo também fica imobilizado enquanto o agarrão for mantido. Você também fica com o deslocamento reduzido a 0 durante a imobilização.\nO alvo pode tentar escapar normalmente em seus turnos. A técnica não funciona em criaturas que não possam ser contidas fisicamente por você.", "source": "https://app.notion.com/p/3e4508f8aa6c817e98e8d0acc37781eb" },
	{ "id": "artista-marcial:desarme-fluido", "name": "Desarme Fluido", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando uma criatura adjacente errar um ataque corpo a corpo contra você utilizando uma arma ou objeto empunhado, você pode usar sua reação para tentar desarmá-la.\nRealize Acrobacia ou Atletismo contra Atletismo ou Acrobacia do alvo.\nEm caso de sucesso, o objeto cai em um espaço adjacente à escolha do Mestre. Objetos presos ao corpo, armas naturais e equipamentos grandes demais não podem ser removidos dessa forma.", "source": "https://app.notion.com/p/3e4508f8aa6c81a4afb7ee3af7ade3e2" },
	{ "id": "artista-marcial:passos-leves", "name": "Passos Leves", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nEnquanto não estiver utilizando armadura nem carregando peso acima da própria capacidade, seu deslocamento aumenta em:\n```plain text\n+3 metros\n```\nVocê também ignora terreno difícil causado apenas por multidões, móveis comuns ou obstáculos baixos.\nO talento não permite atravessar paredes, criaturas hostis ou terreno que exija equipamento específico.", "source": "https://app.notion.com/p/3e4508f8aa6c810f98d6d32119462de9" },
	{ "id": "artista-marcial:queda-controlada", "name": "Queda Controlada", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando sofrer uma queda e puder reagir, reduza o dano recebido em:\n```plain text\n5 × seu nível de Artista Marcial\n```\nUsar Queda Controlada exige sua reação. Se reduzir o dano a 0, você termina a queda de pé quando houver espaço seguro.\nO talento não funciona se estiver inconsciente, imobilizado ou incapaz de movimentar o corpo.", "source": "https://app.notion.com/p/3e4508f8aa6c81bda996e151c923de46" },
	{ "id": "artista-marcial:equilibrio-perfeito", "name": "Equilíbrio Perfeito", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nResultados naturais inferiores a 10 em testes de Acrobacia para manter equilíbrio são tratados como 10.\nVocê também pode se mover com metade do deslocamento sobre superfícies estreitas, instáveis ou inclinadas sem realizar teste, desde que elas suportem seu peso e não estejam sofrendo interferência externa intensa.\nO talento não impede empurrões, quedas provocadas nem o colapso da superfície.", "source": "https://app.notion.com/p/3e4508f8aa6c81148e64ecb938d88d69" },
	{ "id": "artista-marcial:reflexos-treinados", "name": "Reflexos Treinados", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê se torna treinado na resistência de Reflexos.\nSe já for treinado em Reflexos por outra fonte, recebe em vez disso:\n```plain text\n+2 em Reflexos\n```\nEsse bônus alternativo não se acumula com outra aplicação de Reflexos Treinados.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c81f585b0e3d661e988cb" },
	{ "id": "artista-marcial:respiracao-controlada", "name": "Respiração Controlada", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê consegue prender a respiração pelo dobro do tempo normal e recebe:\n```plain text\n+2 em Fortitude contra fumaça, gases, sufocamento e esforço prolongado\n```\nTambém pode recuperar o controle da respiração depois de correr, nadar ou escalar sem precisar interromper completamente o deslocamento.\nO talento não concede imunidade à falta de oxigênio nem permite respirar em ambientes incompatíveis.", "source": "https://app.notion.com/p/3e4508f8aa6c8123b1a9e245c89d7bf5" },
	{ "id": "artista-marcial:meditacao-centrada", "name": "Meditação Centrada", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nAo permanecer dez minutos em meditação sem interrupção, você pode realizar imediatamente uma nova resistência de Vontade contra uma condição emocional ou mental que normalmente permita resistência.\nEssa tentativa pode ser feita uma vez para cada aplicação da condição.\nMeditação Centrada não encerra efeitos sem possibilidade de resistência, não remove controle sobrenatural automaticamente e não substitui tratamento especializado.\nAumente também em 1 sua Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81d8bfd0f3eb7d88c004" },
	{ "id": "artista-marcial:disciplina-de-ferro", "name": "Disciplina de Ferro", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê recebe:\n```plain text\n+2 em Vontade contra medo, coerção, provocação e tentativas de fazê-lo abandonar uma decisão consciente\n```\nAlém disso, dor física comum não obriga você a revelar informações ou interromper uma tarefa que ainda seja capaz de executar.\nO talento não concede imunidade a condições, manipulação psíquica ou incapacitação.", "source": "https://app.notion.com/p/3e4508f8aa6c812f9757d9d75be3ff86" },
	{ "id": "artista-marcial:quebra-precisa", "name": "Quebra Precisa", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê recebe:\n```plain text\n+2 em Atletismo para quebrar, arrombar ou deslocar objetos\n```\nSe atacar desarmado um objeto imóvel e puder observar sua estrutura, causa o dobro do dano após aplicar a redução de dano do material.\nQuebra Precisa não funciona contra criaturas, itens carregados por outra pessoa, artefatos indestrutíveis ou mecanismos cuja abertura dependa de conhecimento técnico.", "source": "https://app.notion.com/p/3e4508f8aa6c819a89b4ca2208ea96c7" },
	{ "id": "artista-marcial:vigilancia-corporal", "name": "Vigilância Corporal", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê recebe:\n```plain text\n+2 em Iniciativa\n```\nTambém recebe +2 em Percepção Passiva para notar aproximações, movimentos repentinos e sinais físicos de uma emboscada.\nO benefício não revela criaturas invisíveis, pensamentos ou ameaças sem manifestação perceptível.", "source": "https://app.notion.com/p/3e4508f8aa6c8119b2a3ea4ac90a6da2" },
	{ "id": "artista-marcial:instrutor-marcial", "name": "Instrutor Marcial", "kind": "class", "classId": "artista-marcial", "prerequisite": "- 5º nível de Artista Marcial.", "text": "## Pré-requisitos\n- 5º nível de Artista Marcial.\n## Efeito\nApós treinar um aliado disposto durante uma hora, escolha Acrobacia, Atletismo ou Fortitude.\nAté o próximo descanso longo, esse aliado recebe:\n```plain text\n+2 no primeiro teste ou resistência realizado com a opção escolhida\n```\nUma criatura só pode manter uma instrução marcial por vez. O treinamento não concede domínio, novos ataques nem qualquer benefício aos golpes ou atributos de Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c81048206ee8e1042a59a" },
	{ "id": "artista-marcial:postura-protetora", "name": "Postura Protetora", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando uma criatura adjacente for alvo de um ataque físico que você consiga perceber, pode usar sua reação para se colocar no caminho.\nVocê se torna o alvo do ataque. Se ele acertar, poderá aplicar Amortecer Impacto ao dano recebido como parte da mesma reação.\nVocê precisa alcançar o espaço protegido e não pode utilizar Postura Protetora se estiver imobilizado ou incapaz de reagir.", "source": "https://app.notion.com/p/3e4508f8aa6c81b68b4af4cf651cac29" },
	{ "id": "artista-marcial:tolerancia-a-dor", "name": "Tolerância à Dor", "kind": "class", "classId": "artista-marcial", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nEstar com metade dos PV ou menos não impõe penalidades adicionais às suas ações por dor ou ferimentos, salvo quando uma condição ou ferimento grave declarar expressamente o contrário.\nVocê recebe ainda:\n```plain text\n+2 em Constituição ou Fortitude para permanecer consciente\n```\nTolerância à Dor não reduz dano, recupera PV nem permite agir com 0 PV.\nAumente também em 1 sua Constituição, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81289d6cee9caf5f5efd" },
	{ "id": "artista-marcial:treinamento-de-especializacao-fisica", "name": "Treinamento de Especialização Física", "kind": "class", "classId": "artista-marcial", "prerequisite": "- 5º nível de Artista Marcial.", "text": "## Pré-requisitos\n- 5º nível de Artista Marcial.\n## Efeito\nUma vez a cada sete dias do relógio da campanha, você pode conduzir o treinamento físico de um Pokémon disposto e disponível.\nO treinamento permite redistribuir até 24 pontos de EV:\n1. Retire um total de 24 pontos de Ataque Especial, Defesa Especial ou de uma combinação dos dois.\n2. Distribua os mesmos 24 pontos entre Ataque, Defesa ou uma combinação dos dois.\n## Limites\n- Nenhum atributo pode ultrapassar 252 EVs.\n- O total do Pokémon não pode ultrapassar 508 EVs.\n- A soma total dos EVs do Pokémon não muda.\n- HP e Velocidade não podem ser alterados.\n- Os 24 pontos precisam ser retirados e distribuídos integralmente.\n- O período semanal pertence ao treinador; ele não pode aplicar o talento em vários Pokémon durante os mesmos sete dias.\n- O mesmo Pokémon pode receber outro treinamento somente em uma semana posterior.\n- Eggs e Pokémon envolvidos em outra atividade indisponível não podem participar.\nA redistribuição é permanente e representa especialização física por treinamento. Ela não concede bônus temporário durante batalhas e não altera IVs.", "source": "https://app.notion.com/p/3e4508f8aa6c818d8aebc9e2109c70f5" },
	{ "id": "artista-marcial:corpo-aperfeicoado", "name": "Ápice — Corpo Aperfeiçoado", "kind": "apex", "classId": "artista-marcial", "prerequisite": "Golpe Aprimorado e do 10º nível de Artista Marcial.", "text": "## Pré-requisitos\nGolpe Aprimorado e do 10º nível de Artista Marcial.\n## Efeito\nSeu treinamento alcança equilíbrio excepcional. Enquanto estiver consciente e sem armadura ou escudo:\n- Seu dano desarmado passa a 1d10.\n- Seu deslocamento aumenta em mais 3 metros.\n- A redução de Amortecer Impacto recebe +2.\n- Você pode escolher Força ou Destreza para testes de Atletismo relacionados a saltar, escalar ou agarrar.\nCorpo Aperfeiçoado é o ápice disponível para qualquer construção da classe e afeta somente o treinador.", "source": "https://app.notion.com/p/3e4508f8aa6c81e28c80dbac7ee94198" },
	{ "id": "artista-marcial:punho-demolidor", "name": "Ápice — Punho Demolidor", "kind": "apex", "classId": "artista-marcial", "prerequisite": "- 10º nível de Artista Marcial.\n- Golpe Aprimorado.\n- Quebra Precisa.", "text": "## Pré-requisitos\n- 10º nível de Artista Marcial.\n- Golpe Aprimorado.\n- Quebra Precisa.\n## Efeito\nSeus ataques desarmados ignoram 2 pontos de redução de dano de criaturas e objetos.\nContra objetos imóveis, seu dano desarmado passa a 1d12 antes de aplicar o benefício de Quebra Precisa.\nAo causar dano não letal a uma criatura, você não sofre penalidade e nunca a mata acidentalmente por excesso de dano.\nO talento melhora somente as ações físicas do treinador.", "source": "https://app.notion.com/p/3e4508f8aa6c81568fafce0d69fb2faa" },
	{ "id": "artista-marcial:guardiao-inabalavel", "name": "Ápice — Guardião Inabalável", "kind": "apex", "classId": "artista-marcial", "prerequisite": "- 10º nível de Artista Marcial.\n- Postura Protetora.\n- Reflexos Treinados.", "text": "## Pré-requisitos\n- 10º nível de Artista Marcial.\n- Postura Protetora.\n- Reflexos Treinados.\n## Efeito\nPostura Protetora passa a alcançar uma criatura a até 3 metros, desde que você consiga chegar até ela.\nAo usar essa técnica, recebe:\n```plain text\n+2 de Defesa contra o ataque interceptado\n```\nSe o ataque ainda acertar, pode utilizar Amortecer Impacto normalmente como parte da mesma reação. Caso reduza o dano a 0, permanece no espaço alcançado sem sofrer deslocamento forçado causado pelo impacto.\nO talento protege criaturas, mas não modifica atributos, Defesa ou resistência dos Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c8106967bde43f159a59d" },
	{ "id": "atleta:especialidade-esportiva", "name": "Especialidade Esportiva", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nEscolha uma modalidade esportiva específica, como corrida, natação, ginástica, levantamento de peso, escalada, arremesso, ciclismo ou outra aprovada pelo Mestre.\nVocê recebe:\n```plain text\n+2 nos testes de Atletismo ou Acrobacia diretamente ligados à modalidade\n```\nEspecialidade Esportiva pode ser escolhida novamente para outra modalidade.", "source": "https://app.notion.com/p/3e4508f8aa6c8135a553e2eb4e4bc7fc" },
	{ "id": "atleta:atleta-polivalente", "name": "Atleta Polivalente", "kind": "class", "classId": "atleta", "prerequisite": "- 5º nível de Atleta.", "text": "## Pré-requisitos\n- 5º nível de Atleta.\n## Efeito\nEscolha três modalidades esportivas. Você recebe os benefícios de Especialidade Esportiva com todas elas, mesmo que nunca tenha escolhido esse talento.\nSe já possuir Especialidade Esportiva, as três modalidades são adicionais.\nAumente também em 1 sua Força, Destreza ou Constituição, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81d5b6a0c3f12ff6e617" },
	{ "id": "atleta:arranque-explosivo", "name": "Arranque Explosivo", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando começar uma corrida, perseguição ou outra sequência de movimento após estar parado ou em ritmo normal, seu deslocamento aumenta em 3 metros até o fim do segundo turno ou intervalo equivalente.\nDepois disso, você retorna ao deslocamento normal.\nArranque Explosivo pode ser utilizado novamente depois de passar ao menos um turno sem correr. O talento não concede ações adicionais.", "source": "https://app.notion.com/p/3e4508f8aa6c812d8f79ed190fc4d122" },
	{ "id": "atleta:salto-excepcional", "name": "Salto Excepcional", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nAs distâncias que você alcança em saltos horizontais e verticais aumentam em 50%.\nVocê também realiza saltos com distância total depois de apenas 1,5 metro de corrida preparatória. Sem preparação, alcança a distância que normalmente exigiria corrida.\nO talento não permite saltar além dos limites físicos do espaço nem aterrissar com segurança automaticamente.", "source": "https://app.notion.com/p/3e4508f8aa6c8170a5bbc3ba400df483" },
	{ "id": "atleta:nadador-de-travessia", "name": "Nadador de Travessia", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nNadar não reduz seu deslocamento em águas calmas ou moderadas.\nEm águas turbulentas, você utiliza metade do deslocamento em vez da redução normal e recebe:\n```plain text\n+2 em Atletismo para nadar, rebocar alguém ou permanecer na superfície\n```\nO talento não permite respirar debaixo d’água nem ignora frio, correntes extremas ou equipamentos inadequados.", "source": "https://app.notion.com/p/3e4508f8aa6c819881f8fad14dd42291" },
	{ "id": "atleta:escalador-tecnico", "name": "Escalador Técnico", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nEm uma superfície com apoios adequados, você escala usando metade do deslocamento sem precisar realizar testes para trechos comuns.\nQuando a escalada realmente exigir teste, recebe:\n```plain text\n+2 em Atletismo\n```\nVocê também consegue preparar uma ancoragem comum na metade do tempo quando possui corda e equipamento apropriado.", "source": "https://app.notion.com/p/3e4508f8aa6c81c489b5f69e08927909" },
	{ "id": "atleta:segunda-respiracao", "name": "Segunda Respiração", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando falhar em Fortitude por causa exclusiva de esforço físico, corrida, natação, escalada ou competição, você pode repetir o teste.\nA nova tentativa recebe:\n```plain text\n+2 na CD\n```\nO segundo resultado é definitivo. Segunda Respiração pode ser utilizada uma vez por cena de esforço e não funciona contra veneno, doença, clima, falta de sono ou ferimentos.", "source": "https://app.notion.com/p/3e4508f8aa6c810faa06f1d15cc7649c" },
	{ "id": "atleta:recuperacao-atletica", "name": "Recuperação Atlética", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nAo recuperar PV naturalmente durante um descanso longo, role duas vezes o dado de recuperação da sua classe e recupere a soma dos resultados.\nSe receber tratamento médico apropriado, esse benefício se aplica antes dos bônus concedidos pelo tratamento.\nRecuperação Atlética não reduz o tempo necessário para o descanso e não remove ferimentos graves ou condições que exijam tratamento específico.", "source": "https://app.notion.com/p/3e4508f8aa6c81238ca1f5615c77d8a3" },
	{ "id": "atleta:carregador-experiente", "name": "Carregador Experiente", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nSua capacidade de peso aumenta em 50%, sem criar espaços adicionais na Bag.\nPara empurrar, puxar ou arrastar carga, trate sua capacidade física como o dobro do valor normal.\nO talento não reduz o peso dos itens, não altera o limite de espaços e não permite carregar objetos cuja forma impossibilite o transporte.", "source": "https://app.notion.com/p/3e4508f8aa6c815da6f2e7cd53144af1" },
	{ "id": "atleta:trabalho-em-equipe", "name": "Trabalho em Equipe", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nQuando você ajuda um aliado em um teste físico de Atletismo ou Acrobacia, sua ajuda concede no mínimo +2, desde que sua contribuição seja válida.\nEm um desafio que exija vários participantes, você também pode coordenar até um número de aliados igual ao seu bônus de proficiência. Uma falha individual por até quatro pontos não desfaz automaticamente o progresso de todo o grupo.\nO Mestre ainda aplica consequências individuais e exige que todos consigam participar fisicamente.", "source": "https://app.notion.com/p/3e4508f8aa6c81f38281f0146530d2f9" },
	{ "id": "atleta:capitao-de-time", "name": "Capitão de Time", "kind": "class", "classId": "atleta", "prerequisite": "- 5º nível de Atleta.", "text": "## Pré-requisitos\n- 5º nível de Atleta.\n## Efeito\nDepois de dez minutos planejando uma atividade física, travessia ou competição em grupo, escolha até um número de participantes igual ao seu bônus de proficiência. Você pode incluir a si mesmo.\nCada escolhido recebe:\n```plain text\n+2 em testes de Atletismo ou Acrobacia diretamente ligados ao plano\n```\nO plano permanece ativo até que você prepare outro. Quem não for incluído no novo plano deixa de receber o bônus. Não se aplica a ataques nem a ações de Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c815d837ce938f20b5f5b" },
	{ "id": "atleta:arremesso-de-precisao", "name": "Arremesso de Precisão", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê recebe:\n```plain text\n+2 em Captura para acertar o Pokémon com uma Poké Bola\n```\nO bônus afeta somente a etapa de arremesso. Ele não modifica a porcentagem de captura calculada depois do acerto, a qualidade da Poké Bola, os PV, as condições ou qualquer atributo do Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c813a92b3da7041bb978a" },
	{ "id": "atleta:montaria-esportiva", "name": "Montaria Esportiva", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nVocê se torna treinado em Montaria Pokémon. Se já possuir esse treinamento, ele não é concedido novamente.\nDurante corridas, saltos, provas de obstáculo e viagens prolongadas com sua montaria, você recebe:\n```plain text\n+2 nos testes de Montaria Pokémon\n```\nUma vez por prova, quando sua montaria falhar por até quatro pontos em uma manobra coordenada, você pode impedir que a falha derrube você; o restante das consequências permanece.\nO talento não concede bônus à montaria em batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c818e8b6fccefd09194df" },
	{ "id": "atleta:olho-para-as-regras", "name": "Olho para as Regras", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nDepois de observar uma etapa completa de uma competição, você identifica:\n- Uma infração visível às regras.\n- Uma vantagem obtida por equipamento irregular.\n- Uma inconsistência evidente na medição ou pontuação.\n- A regra que mais influencia a estratégia daquela prova.\nSe houver tentativa deliberada de ocultação, realize Percepção ou Intuição contra a perícia usada para enganar os fiscais. Você também pode usar Atletismo no lugar dessas perícias para reconhecer infrações técnicas, uso irregular de equipamentos, inconsistências de pontuação ou a estratégia de uma prova que tenha observado. Nesse caso, o teste usa seu bônus normal de Atletismo; o talento não concede bônus numérico adicional.\nO talento não revela trapaças impossíveis de observar nem substitui uma investigação formal.", "source": "https://app.notion.com/p/3e4508f8aa6c816993cadf005c3a3f1b" },
	{ "id": "atleta:ritmo-de-viagem", "name": "Ritmo de Viagem", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nAo liderar uma viagem a pé, você e até um número de companheiros igual ao seu bônus de proficiência percorrem 25% mais distância no mesmo período sem antecipar testes de Fortitude por duração.\nTodos precisam seguir seu ritmo e não podem estar sobrecarregados.\nO benefício não ignora terreno, clima, fome, sede, falta de sono ou a velocidade menor de veículos e montarias.", "source": "https://app.notion.com/p/3e4508f8aa6c81a7bf8bf18c5e21be17" },
	{ "id": "atleta:preparador-fisico-pokemon", "name": "Preparador Físico Pokémon", "kind": "class", "classId": "atleta", "prerequisite": "- 5º nível de Atleta.", "text": "## Pré-requisitos\n- 5º nível de Atleta.\n## Efeito\nAo iniciar a redistribuição de EVs de um Pokémon seu, você pode acompanhar esse treinamento. Se nenhum outro Pokémon seu estiver em treinamento de EV, o tempo necessário é reduzido em 25%.\n```plain text\nTempo necessário: 75% da duração normal\n```\nVocê só pode acompanhar um treinamento por vez. Se iniciar outro enquanto o primeiro ainda estiver em andamento, o segundo terá a duração normal; ele não recebe o benefício retroativamente quando o primeiro terminar. Após a conclusão do treinamento acompanhado, um novo treinamento poderá receber a redução.\nO talento não aumenta a quantidade de EV recebida, não ultrapassa os limites de 252 por atributo e 508 no total, não altera IVs e não concede bônus temporário em batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c81889cfec29168fdec72" },
	{ "id": "atleta:adaptacao-climatica", "name": "Adaptação Climática", "kind": "class", "classId": "atleta", "prerequisite": "Nenhum.", "text": "## Pré-requisitos\nNenhum.\n## Efeito\nDepois de passar uma hora se preparando para um clima conhecido e possuir roupas ou recursos minimamente adequados, você recebe:\n```plain text\n+2 em Fortitude contra calor, frio, chuva, vento e altitude\n```\nVocê também consegue orientar até um número de companheiros igual ao seu bônus de proficiência, concedendo +1 nos mesmos testes.\nO talento não substitui equipamento obrigatório nem protege contra ambientes instantaneamente letais.", "source": "https://app.notion.com/p/3e4508f8aa6c81df8f60f63241d5a794" },
	{ "id": "atleta:atleta-completo", "name": "Ápice — Atleta Completo", "kind": "apex", "classId": "atleta", "prerequisite": "Nenhum além do 10º nível de Atleta.", "text": "## Pré-requisitos\nNenhum além do 10º nível de Atleta.\n## Efeito\nResultados naturais inferiores a 10 em testes de Atletismo e Acrobacia fora de combate são tratados como 10.\nAlém disso:\n- Seu deslocamento básico aumenta em mais 1,5 metro.\n- Você conta como possuidor de Especialidade Esportiva em qualquer modalidade esportiva comum.\n- Uma vez por cena de esforço, pode ignorar a primeira penalidade causada exclusivamente por cansaço físico.\nAtleta Completo é o ápice disponível para qualquer construção da classe.", "source": "https://app.notion.com/p/3e4508f8aa6c8141a651dd2e101ab604" },
	{ "id": "atleta:recordista", "name": "Ápice — Recordista", "kind": "apex", "classId": "atleta", "prerequisite": "- 10º nível de Atleta.\n- Especialidade Esportiva ou Atleta Polivalente.", "text": "## Pré-requisitos\n- 10º nível de Atleta.\n- Especialidade Esportiva ou Atleta Polivalente.\n## Efeito\nEscolha uma modalidade beneficiada por Especialidade Esportiva.\nEm competições formais dessa modalidade, role duas vezes seu primeiro teste principal e utilize o melhor resultado.\nAlém disso, superar a CD ou o adversário por 10 ou mais produz um resultado excepcional reconhecível, como recorde local, execução perfeita ou vantagem narrativa equivalente definida pelo Mestre.\nRecordista não concede sucesso automático e não afeta combates.", "source": "https://app.notion.com/p/3e4508f8aa6c81359da6e1d3b96773c9" },
	{ "id": "atleta:lider-de-expedicao", "name": "Ápice — Líder de Expedição", "kind": "apex", "classId": "atleta", "prerequisite": "- 10º nível de Atleta.\n- Capitão de Time.\n- Ritmo de Viagem.", "text": "## Pré-requisitos\n- 10º nível de Atleta.\n- Capitão de Time.\n- Ritmo de Viagem.\n## Efeito\nAo liderar uma travessia, prova coletiva ou fuga prolongada, todos os participantes capazes de seguir suas instruções recebem:\n```plain text\n+2 em testes físicos ligados ao deslocamento do grupo\n```\nUma vez em cada etapa da atividade, você pode transformar a falha de um participante por até quatro pontos em sucesso com complicação, impedindo que o grupo inteiro seja interrompido.\nO talento não remove custos, perigos ambientais nem consequências individuais graves.", "source": "https://app.notion.com/p/3e4508f8aa6c8166a3a7cfdf9d5a9ea7" },
	{ "id": "cientista:especializacao-cientifica", "name": "Especialização Científica", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Ao escolher este talento, selecione uma área de Conhecimento na qual o Cientista seja treinado.\nO Cientista recebe:\n```plain text\n+2 nos testes da área escolhida\n```\nO bônus representa formação aprofundada e não se aplica a outras áreas de Conhecimento, mesmo quando elas tratam do mesmo objeto por perspectivas diferentes.\nEste talento poderá ser escolhido mais de uma vez, sempre para uma área diferente.", "source": "https://app.notion.com/p/3e4508f8aa6c8111805afdb6eaa52219" },
	{ "id": "cientista:analise-de-campo", "name": "Análise de Campo", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "O Cientista adapta procedimentos laboratoriais para ambientes improvisados.\nQuando utilizar Método Científico fora de uma instalação apropriada, poderá realizar análises simples com um Kit Científico e uma superfície minimamente estável, desde que possua amostra, iluminação e instrumentos compatíveis.\nA falta de um laboratório não impõe penalidade por si só. Análises detalhadas ainda exigem os equipamentos e as condições indicadas pelo Mestre.\nAnálise de Campo não permite executar procedimentos impossíveis com os instrumentos disponíveis.", "source": "https://app.notion.com/p/3e4508f8aa6c81968fe8c49e6d2e3fbf" },
	{ "id": "cientista:coleta-esteril", "name": "Coleta Estéril", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Quando o Cientista coleta, transporta ou separa uma amostra utilizando um Kit Científico e falha no teste por até quatro pontos:\n- A amostra não é contaminada.\n- A amostra não é destruída.\n- A coleta não é concluída.\n- Uma nova tentativa exige tempo, outra abordagem ou mudança nas condições.\nUma falha por cinco ou mais produz as consequências normais.\nA característica protege materiais biológicos, químicos, minerais e resíduos de evidências, mas não transforma a falha em sucesso.", "source": "https://app.notion.com/p/3e4508f8aa6c810b9152c97935139e02" },
	{ "id": "cientista:diagnostico-comparativo", "name": "Diagnóstico Comparativo", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Depois de analisar cientificamente duas ou mais amostras, objetos, organismos ou resultados relacionados, o Cientista recebe:\n```plain text\n+2 no teste de Conhecimento usado para identificar diferenças, origem comum, adulteração ou causa provável\n```\nAs amostras precisam ser relevantes para a comparação. O talento não substitui evidências ausentes nem revela informações que os materiais não possam sustentar.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c81e88683eb78fb57a161" },
	{ "id": "cientista:parecer-tecnico", "name": "Parecer Técnico", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Após concluir com sucesso uma análise por Método Científico, o Cientista poderá produzir uma orientação prática sobre o problema estudado.\nUm aliado que siga essa orientação recebe:\n```plain text\n+2 em um único teste diretamente relacionado à conclusão\n```\nExemplos incluem tratar a doença identificada, reparar a falha diagnosticada ou neutralizar a substância analisada.\nA orientação precisa ser possível, específica e seguida antes que as condições mudem. Ela não permite ao Cientista executar a atividade prática com Conhecimento e não afeta combates Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c8110a54feddd2635513b" },
	{ "id": "cientista:pesquisa-colaborativa", "name": "Pesquisa Colaborativa", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Quando o Cientista ajuda outra pessoa em um teste de Conhecimento, Investigação, Medicina, Medicina Pokémon, Natureza ou Tecnologia e apresenta dados, cálculos ou análise relevantes, o bônus de ajuda não poderá ser inferior a:\n```plain text\n+2\n```\nA ajuda continua exigindo participação real e a mesma perícia do teste principal, embora o atributo empregado possa ser diferente quando a abordagem justificar.", "source": "https://app.notion.com/p/3e4508f8aa6c8141b2d9c69099fb5af2" },
	{ "id": "cientista:arquivo-de-amostras", "name": "Arquivo de Amostras", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "O Cientista poderá organizar um arquivo portátil de amostras identificadas, desde que possua recipientes adequados e espaço para transportá-las.\nAo analisar novamente um fenômeno que possa ser comparado a uma amostra arquivada, ele poderá consultar o arquivo para receber:\n```plain text\n+2 no teste de Conhecimento correspondente\n```\nCada amostra precisa ter sido obtida legitimamente, catalogada durante um descanso e preservada de maneira compatível. Amostras deterioradas, irrelevantes ou de procedência duvidosa não concedem o bônus.", "source": "https://app.notion.com/p/3e4508f8aa6c81088c84e12c43cf8a56" },
	{ "id": "cientista:economia-de-reagentes", "name": "Economia de Reagentes", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Quando uma análise ou fabricação consumir cargas de um Kit Científico, o Cientista poderá reduzir o custo em uma carga, até o mínimo de uma.\nA redução somente se aplica quando:\n- O procedimento é conhecido pelo Cientista.\n- Ele possui tempo normal de preparação.\n- Está utilizando seu próprio Kit Científico.\n- Não está trabalhando sob pressão imediata.\nEconomia de Reagentes não se acumula com outra redução de cargas aplicada ao mesmo procedimento.", "source": "https://app.notion.com/p/3e4508f8aa6c81d1b9c0e5153261f7e2" },
	{ "id": "cientista:formula-adaptavel", "name": "Fórmula Adaptável", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Ao preparar um produto de um Registro Reprodutível inicial, o Cientista poderá alterar um aspecto secundário da fórmula sem desenvolver um registro novo.\nPoderá modificar um dos seguintes elementos quando a natureza do produto permitir:\n- Cor.\n- Odor.\n- Forma de ativação.\n- Formato do recipiente.\n- Intensidade visual não mecânica.\n- Duração em até 50%.\nA adaptação aumenta o custo da preparação em uma carga científica. Ela não poderá aumentar dano, cura, área, bônus, CD ou criar uma função diferente da fórmula original.", "source": "https://app.notion.com/p/3e4508f8aa6c81fd8a13f75421515415" },
	{ "id": "cientista:registros-paralelos", "name": "Registros Paralelos", "kind": "class", "classId": "cientista", "prerequisite": "5º nível de Cientista.", "text": "**Pré-requisito:** 5º nível de Cientista.\nO Cientista aumenta em um a quantidade de Registros Reprodutíveis que consegue manter ativos simultaneamente.\nCada registro continua sendo preparado e utilizado separadamente. Criar um registro além do novo limite faz o Cientista escolher qual registro anterior perde o benefício e se torna uma anotação comum.\nEste talento poderá ser escolhido duas vezes.", "source": "https://app.notion.com/p/3e4508f8aa6c81fe81afc3718ac4bda9" },
	{ "id": "cientista:registro-avancado", "name": "Registro Avançado", "kind": "class", "classId": "cientista", "prerequisite": "5º nível de Cientista.", "text": "**Registro Avançado**\n**Pré-requisito:** 5º nível de Cientista.\nAo escolher este talento, o Cientista aprende todos os Registros Avançados descritos nesta página. Eles ampliam a variedade de efeitos científicos disponíveis e contam normalmente no limite de Registros Reprodutíveis ativos.\nQualquer pessoa com um Registro Avançado ativo poderá seguir suas instruções sem dominar o Kit Científico, conforme as regras de Registro Reprodutível. Ainda precisará do kit indicado e consumirá todas as cargas da fórmula.\nOs produtos são consumíveis, possuem um espaço por pilha, limite de nove unidades e não possuem preço comercial fixo. Os componentes estão representados pelas cargas utilizadas.\nO Cientista também poderá propor um registro livre com nome e descrição; o Mestre aprova o efeito e define o nível do kit e as cargas antes de ele ficar ativo.", "source": "https://app.notion.com/p/3e4508f8aa6c81fdab3ef3f2d19142cd" },
	{ "id": "cientista:producao-farmaceutica-pokemon", "name": "Produção Farmacêutica Pokémon", "kind": "class", "classId": "cientista", "prerequisite": "5º nível de Cientista, Conhecimento compatível treinado e domínio de Kit Científico.", "text": "**Pré-requisito:** 5º nível de Cientista, Conhecimento compatível treinado e domínio de Kit Científico.\nO Cientista aprende a fabricar produtos básicos do catálogo de itens Pokémon utilizando um Kit Científico e instalações higiênicas.\nUm Refil Científico custa **1.500 Pokécoins** e fornece **5 cargas**, portanto cada carga possui custo de referência de **300 Pokécoins**.\n## Produção\nUma fabricação utiliza:\n```plain text\nTempo: 30 minutos\nCusto: 1 carga científica\nRendimento: 3 unidades iguais\n```\nO Cientista escolhe um dos seguintes produtos para o lote:\n<table header-row=\"true\">\n<tr>\n<td>Produto</td>\n<td>Preço individual na loja</td>\n<td>Quantidade produzida</td>\n<td>Custo de componentes por unidade</td>\n</tr>\n<tr>\n<td>Potion</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n<tr>\n<td>Antidote</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n<tr>\n<td>Awakening</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n<tr>\n<td>Burn Heal</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n<tr>\n<td>Ice Heal</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n<tr>\n<td>Paralyze Heal</td>\n<td>200 Pokécoins</td>\n<td>3</td>\n<td>100 Pokécoins</td>\n</tr>\n</table>\nCada produto possui exatamente o efeito, peso, limite de pilha e restrições do item oficial correspondente.\nO talento concede as seis fórmulas. Não será necessário adquiri-las separadamente.\nOs itens fabricados podem ser usados, presenteados ou vendidos, mas uma loja utiliza sua regra normal de compra e poderá recusar produtos sem procedência adequada. A fabricação não garante comprador nem o preço integral de varejo.\nEste talento não permite produzir Revive, Max Revive, Full Restore, Max Potion, itens de PP ou itens raros.\nComo cada lote já custa somente uma carga, Economia de Reagentes não poderá reduzir seu custo.", "source": "https://app.notion.com/p/3e4508f8aa6c81f5a0f6e456eca11833" },
	{ "id": "cientista:farmacologia-avancada", "name": "Farmacologia Avançada", "kind": "class", "classId": "cientista", "prerequisite": "7º nível de Cientista e Produção Farmacêutica Pokémon.", "text": "**Pré-requisito:** 7º nível de Cientista e Produção Farmacêutica Pokémon.\nO Cientista aprende as fórmulas de Super Potion, Hyper Potion e Full Heal. Todas exigem Kit Científico de nível 2 ou superior e instalações higiênicas.\nUm Refil Científico custa **1.500 Pokécoins** e fornece **5 cargas**, portanto cada carga possui custo de referência de **300 Pokécoins**.\n## Produção\n<table header-row=\"true\">\n<tr>\n<td>Produto</td>\n<td>Preço individual na loja</td>\n<td>Tempo por lote</td>\n<td>Cargas</td>\n<td>Rendimento</td>\n<td>Custo por unidade</td>\n</tr>\n<tr>\n<td>Super Potion</td>\n<td>700 Pokécoins</td>\n<td>1 hora</td>\n<td>2</td>\n<td>2 unidades</td>\n<td>300 Pokécoins</td>\n</tr>\n<tr>\n<td>Hyper Potion</td>\n<td>1.500 Pokécoins</td>\n<td>1 hora</td>\n<td>4</td>\n<td>2 unidades</td>\n<td>600 Pokécoins</td>\n</tr>\n<tr>\n<td>Full Heal</td>\n<td>400 Pokécoins</td>\n<td>1 hora</td>\n<td>2</td>\n<td>3 unidades</td>\n<td>200 Pokécoins</td>\n</tr>\n</table>\nOs produtos funcionam exatamente como os itens oficiais correspondentes. Eles não poderão ser modificados para ampliar cura, remover condições adicionais nem atuar de maneira diferente durante uma batalha.\nEconomia de Reagentes poderá reduzir o custo de cada lote em uma carga, respeitando o mínimo de uma. Ela não altera a quantidade produzida.\nOs itens podem ser usados, presenteados ou vendidos, mas lojas aplicam suas regras normais de compra e poderão exigir procedência. A fabricação não garante comprador nem preço integral de varejo.\nEste talento não libera Revive, Max Revive, Full Restore, Max Potion nem itens de recuperação de PP.", "source": "https://app.notion.com/p/3e4508f8aa6c8109b140c0456763780b" },
	{ "id": "cientista:pesquisa-acelerada", "name": "Pesquisa Acelerada", "kind": "class", "classId": "cientista", "prerequisite": "5º nível de Cientista.", "text": "**Pré-requisito:** 5º nível de Cientista.\nQuando possui todas as ferramentas, evidências e instalações necessárias, o Cientista reduz pela metade o tempo de:\n- Análises simples ou detalhadas de Método Científico.\n- Catalogação de amostras.\n- Desenvolvimento documental de uma fórmula já testada.\n- Preparação de relatórios técnicos.\nO talento não reduz o tempo de fabricação de itens, condução de experimentos inéditos nem pesquisas complexas cuja duração seja definida pelo Mestre.", "source": "https://app.notion.com/p/3e4508f8aa6c810bbcd5e97c13a2295c" },
	{ "id": "cientista:publicacao-de-referencia", "name": "Publicação de Referência", "kind": "class", "classId": "cientista", "prerequisite": "7º nível de Cientista e Foco em Perícia em uma área de Conhecimento.", "text": "**Pré-requisito:** 7º nível de Cientista e Foco em Perícia em uma área de Conhecimento.\nA área de Conhecimento escolhida recebe +2 em seus testes.\nDepois de uma semana de trabalho, o Cientista poderá produzir uma obra de referência sobre um assunto específico dessa área.\nUma pessoa treinada na área que consulte a obra durante pelo menos dez minutos recebe:\n```plain text\n+2 em um teste relacionado ao assunto publicado\n```\nA publicação não concede treinamento, não permite executar procedimentos práticos e não se aplica a assuntos ausentes do texto. Consultar várias obras não acumula bônus no mesmo teste.\n## Publicação e venda\nO manuscrito poderá ser vendido diretamente ou submetido a universidade, laboratório, editora, museu ou organização semelhante.\nO valor depende da relevância e originalidade reconhecidas pelo comprador:\n<table header-row=\"true\">\n<tr>\n<td>Categoria</td>\n<td>Exemplo</td>\n<td>Pagamento sugerido pelos direitos</td>\n</tr>\n<tr>\n<td>Referência prática</td>\n<td>Compilação útil de conhecimento conhecido</td>\n<td>2.000 Pokécoins</td>\n</tr>\n<tr>\n<td>Pesquisa relevante</td>\n<td>Resultados novos e bem demonstrados</td>\n<td>5.000 Pokécoins</td>\n</tr>\n<tr>\n<td>Descoberta excepcional</td>\n<td>Conhecimento raro com grande impacto científico</td>\n<td>10.000 Pokécoins ou recompensa definida pelo Mestre</td>\n</tr>\n</table>\nO pagamento representa a cessão ou publicação inicial, não uma renda infinita por cópias. O Mestre determina se existe instituição interessada, se o estudo possui evidências suficientes e se a descoberta pertence legalmente ao Cientista.\nUma obra não poderá ser vendida repetidamente como inédita. Contratos de reimpressão, royalties ou encomendas futuras serão negociados como parte da campanha.\n## Crescimento científico\nCada obra aceita por uma instituição reconhecida conta como uma publicação científica do personagem:\n- **1 publicação:** seu nome passa a ser reconhecido por profissionais de sua área.\n- **3 publicações:** poderá solicitar acesso a acervos, reuniões e contatos científicos normalmente indisponíveis ao público, sujeito às regras da instituição.\n- **5 publicações:** torna-se uma autoridade reconhecida na especialização e poderá receber convites, encomendas, bolsas ou participação em grandes pesquisas.\nEsse reconhecimento não obriga instituições a colaborar, não substitui licenças e não concede bônus automático em testes sociais. Publicações falsas, desacreditadas ou comprovadamente incorretas poderão deixar de contar.", "source": "https://app.notion.com/p/3e4508f8aa6c8113986ceac6bc6d28cf" },
	{ "id": "cientista:hipotese-persistente", "name": "Hipótese Persistente", "kind": "class", "classId": "cientista", "prerequisite": "", "text": "Quando falha em uma análise científica, o Cientista poderá registrar o resultado negativo e descartar uma hipótese incorreta.\nAo tentar novamente depois de obter uma nova amostra, evidência ou método de análise, recebe:\n```plain text\n+1 no novo teste\n```\nO bônus poderá crescer até +2 após outra falha acompanhada de evidência nova. Ele desaparece após um sucesso ou quando o problema estudado muda.\nRepetir exatamente o mesmo procedimento sem informação nova não ativa este talento.\nAumente também em 1 sua Inteligência, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81bb963afc33d11fb418" },
	{ "id": "cientista:biblioteca-de-procedimentos", "name": "Ápice — Biblioteca de Procedimentos", "kind": "apex", "classId": "cientista", "prerequisite": "10º nível de Cientista e Registros Paralelos escolhido duas vezes.", "text": "**Pré-requisito:** 10º nível de Cientista e Registros Paralelos escolhido duas vezes.\nO Cientista poderá manter:\n```plain text\n5 Registros Reprodutíveis ativos simultaneamente\n```\nAté dois deles poderão ser Registros Avançados, se o Cientista possuir esse talento.\nAlém disso, ao produzir um item de qualquer registro ativo, reduz seu custo em uma carga científica, até o mínimo de uma. Essa redução não se acumula com Economia de Reagentes.\nA Biblioteca de Procedimentos amplia a capacidade de preparação do Cientista, mas não remove tempo, ferramentas, instalações, fórmulas ou componentes exigidos.", "source": "https://app.notion.com/p/3e4508f8aa6c81e2bcaef5749b5844e3" },
	{ "id": "cientista:autoridade-cientifica", "name": "Ápice — Autoridade Científica", "kind": "apex", "classId": "cientista", "prerequisite": "10º nível de Cientista.", "text": "**Pré-requisito:** 10º nível de Cientista.\nEscolha três áreas de Conhecimento nas quais o Cientista seja treinado.\nAo realizar um teste dessas áreas, um resultado natural inferior a 10 no d20 será tratado como 10, desde que o Cientista possua tempo e meios adequados para examinar o problema.\nAlém disso, Método Científico poderá produzir uma pergunta adicional quando o resultado superar a CD por 10 ou mais.\nEste ápice não exige talentos anteriores e representa domínio científico amplo, sem substituir atividades práticas de outras perícias.", "source": "https://app.notion.com/p/3e4508f8aa6c81b9a9b0e0909769a424" },
	{ "id": "cientista:mestre-de-formulacao", "name": "Ápice — Mestre de Formulação", "kind": "apex", "classId": "cientista", "prerequisite": "10º nível de Cientista, Registro Avançado e Produção Farmacêutica Pokémon.", "text": "**Pré-requisito:** 10º nível de Cientista, Registro Avançado e Produção Farmacêutica Pokémon.\nAo adquirir este ápice, o Cientista domina fórmulas de alta complexidade e aprende a fabricar Max Potion e Full Restore.\nCada lote produz uma unidade e exige oito horas de trabalho, uma instalação higiênica e um Kit Científico III. Max Potion consome seis cargas científicas; Full Restore consome oito.\nO Cientista também sabe formular soluções avançadas de preservação, neutralizadores de contaminantes excepcionais e compostos de grande duração ou alcance. Para fabricar um desses produtos, seus efeitos e custos devem estar definidos como um item da campanha.\nEste talento não permite fabricar Revive, Max Revive, itens de recuperação de PP nem produtos que alterem EV, IV, natureza, habilidade, atributos ou golpes de Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c811eb5a7ca53c4e537b8" },
	{ "id": "cozinheiro:paladar-analitico", "name": "Paladar Analítico", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Depois de examinar, cheirar ou provar uma quantidade segura de alimento ou bebida, o Cozinheiro poderá realizar um teste de Ofício — Culinária para analisar sua composição.\nEm caso de sucesso, poderá identificar:\n- Os principais ingredientes.\n- O método de preparo utilizado.\n- Se o alimento está estragado.\n- Se houve conservação inadequada.\n- A presença de um ingrediente comum que não deveria estar ali.\n- Se a receita foi alterada ou adulterada.\n- A provável origem culinária da preparação.\n- Quais sabores ou texturas estão desequilibrados.\nQuando procurar uma substância perigosa, o resultado depende dos meios disponíveis:\n- Alterações perceptíveis pelo sabor, cheiro, cor ou textura poderão ser encontradas normalmente.\n- Substâncias inodoras, insípidas ou presentes em quantidades muito pequenas exigirão instrumentos ou reagentes apropriados.\n- Provar diretamente uma substância perigosa poderá causar suas consequências antes da identificação.\nSe superar a CD por 10 ou mais, o Cozinheiro também poderá estimar as quantidades aproximadas dos ingredientes principais ou sugerir como reproduzir a receita.\nAumente também em 1 sua Inteligência ou Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e1508f8aa6c80a2b19fd2fcf8669f50" },
	{ "id": "cozinheiro:preparo-acelerado", "name": "Preparo Acelerado", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "O Cozinheiro organiza ingredientes, utensílios e etapas de maneira eficiente.\nO tempo necessário para preparar uma receita conhecida é reduzido em 25%, até o mínimo de dez minutos.\nA redução não se aplica a fermentação, maturação, conservação prolongada ou períodos em que o alimento precisa repousar, assar ou cozinhar por um tempo indispensável.", "source": "https://app.notion.com/p/3e4508f8aa6c81c5a791ec1966901fe6" },
	{ "id": "cozinheiro:cozinha-de-expedicao", "name": "Cozinha de Expedição", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Ao preparar comida durante uma viagem, o Cozinheiro poderá produzir refeições fáceis de transportar e consumir.\nAs porções preparadas:\n- Permanecem adequadas até o próximo descanso longo, mesmo sem recipiente térmico.\n- Podem ser consumidas durante uma pausa de dez minutos.\n- Não exigem utensílios adicionais para serem servidas.\n- Não perdem qualidade por chuva, poeira ou movimentação normal quando embaladas corretamente.\nO talento não prolonga a conservação além desse período e não substitui Conservação Planejada.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c8177b982e62b76c58d15" },
	{ "id": "cozinheiro:forrageio-gastronomico", "name": "Forrageio Gastronômico", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Quando procura ingredientes comestíveis em ambiente selvagem, o Cozinheiro recebe:\n```plain text\n+2 em Sobrevivência para localizar, reconhecer e coletar alimentos\n```\nEm caso de sucesso, também identifica a melhor forma de limpeza e preparo dos ingredientes encontrados.\nO talento não torna comestível uma espécie venenosa, não cria alimento onde ele não existe e não substitui Natureza quando for necessário estudar propriedades não culinárias.", "source": "https://app.notion.com/p/3e4508f8aa6c81a5871ef4b9f5956a74" },
	{ "id": "cozinheiro:paladar-resistente", "name": "Paladar Resistente", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "O Cozinheiro está acostumado a pequenas provas, aromas fortes, calor de cozinha e ingredientes incomuns.\nRecebe:\n```plain text\n+2 em Fortitude contra alimentos estragados, bebidas adulteradas, odores nauseantes e substâncias ingeridas acidentalmente\n```\nEsse bônus não se aplica a ataques, golpes Pokémon, venenos introduzidos por ferimentos nem à ingestão deliberada de uma dose sabidamente letal.", "source": "https://app.notion.com/p/3e4508f8aa6c81c7913acda9d79f4da3" },
	{ "id": "cozinheiro:refeicao-reconfortante", "name": "Refeição Reconfortante", "kind": "class", "classId": "cozinheiro", "prerequisite": "5º nível de Cozinheiro.", "text": "**Pré-requisito:** 5º nível de Cozinheiro.\nRefeição Reconfortante é ativada juntamente com Refeição Revigorante durante um descanso longo. Não exige outra preparação, outra rolagem nem Alimento adicional.\nQuando o teste de Ofício — Culinária de Refeição Revigorante tiver sucesso, cada participante escolhido recebe a cura normal e reduz em 1 o próprio nível de Exaustão, se estiver exausto. Em caso de falha, não há cura adicional nem redução de Exaustão.\nCada pessoa pode receber os benefícios dessa refeição apenas uma vez por descanso longo. O talento afeta somente treinadores; não altera Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c8178bd7bfce798a1dda6" },
	{ "id": "cozinheiro:nutricao-de-recuperacao", "name": "Nutrição de Recuperação", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Quando um treinador consumir uma Refeição Revigorante durante um descanso longo, poderá rolar novamente o dado de recuperação natural de PV e escolher o melhor resultado.\nO benefício modifica somente a recuperação natural do treinador. Ele não aumenta curas recebidas, não afeta Pokémon e não se acumula com outra Nutrição de Recuperação no mesmo descanso.", "source": "https://app.notion.com/p/3e4508f8aa6c81fb8b1fce61ff344e68" },
	{ "id": "cozinheiro:petisco-de-amizade", "name": "Petisco de Amizade", "kind": "class", "classId": "cozinheiro", "prerequisite": "Treinamento em Conhecimento: Pokémon.", "text": "**Pré-requisito:** treinamento em Conhecimento: Pokémon.\nO Cozinheiro pode transformar uma unidade de Ração Pokémon comum ou artesanal em três Petiscos de Amizade, adaptando-os às preferências e restrições alimentares dos Pokémon que irá alimentar. Cada petisco serve como uma porção de Ração Pokémon.\nAo oferecer um petisco a um Pokémon disposto, sua amizade com o treinador aumenta em **5 pontos**, até o limite normal de amizade. O mesmo Pokémon só pode receber esse aumento uma vez a cada sete dias da campanha; nesse intervalo, ainda pode consumir o petisco como alimento, sem receber novos pontos.\nO Cozinheiro pode oferecer os três petiscos a Pokémon seus ou de outros treinadores. Também pode oferecê-los a Pokémon de NPCs ou selvagens, quando o Mestre considerar apropriado. A amizade desses Pokémon com seus treinadores ou com pessoas da cena fica a critério do Mestre.\nOs petiscos não concedem benefícios de combate.", "source": "https://app.notion.com/p/3e4508f8aa6c81749fc4c110df745256" },
	{ "id": "cozinheiro:racao-artesanal-pokemon", "name": "Ração Artesanal Pokémon", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "O Cozinheiro poderá transformar porções de Alimentos em uma ração preparada para Pokémon.\nOs preços de referência são:\n```plain text\nPorção de Alimentos: 75 Pokécoins\nRação Pokémon: 100 Pokécoins\n```\nCom uma hora de trabalho e um teste de Ofício — Culinária contra CD 12:\n```plain text\n3 porções de Alimentos → 4 porções de Ração Pokémon artesanal\n```\nA ração atende às necessidades alimentares normais e poderá ser adaptada a dietas específicas conhecidas pelo Cozinheiro.\nEla também pode ser usada para preparar Petiscos de Amizade. Por si só, não concede amizade adicional, recuperação, bônus de treinamento ou benefícios de combate.\nAproveitamento Integral e Aproveitamento Superior não se aplicam novamente a essa conversão. A ração poderá ser vendida, mas lojas seguem suas regras normais de compra, poderão exigir procedência e não garantem o preço integral de varejo.", "source": "https://app.notion.com/p/3e4508f8aa6c811fab96df2155de2543" },
	{ "id": "cozinheiro:recompensa-de-treinamento", "name": "Recompensa de Treinamento", "kind": "class", "classId": "cozinheiro", "prerequisite": "5º nível de Cozinheiro.", "text": "**Pré-requisito:** 5º nível de Cozinheiro.\nO Cozinheiro escolhe um Pokémon da equipe ativa de qualquer treinador da mesa e prepara uma recompensa com uma Ração Pokémon comum ou artesanal. A ração é consumida ao preparar a recompensa.\nO próximo treinamento iniciado por esse Pokémon dura **10% menos**. Um Pokémon não pode guardar mais de uma recompensa; se outro efeito também reduzir o tempo, aplica-se apenas a maior redução.\nSe o treinamento não começar antes do próximo descanso curto, a recompensa perde o efeito. Ela não aumenta EVs, altera IVs, concede experiência ou permite treinamentos adicionais.", "source": "https://app.notion.com/p/3e4508f8aa6c81e39c40e73cf4176816" },
	{ "id": "cozinheiro:banquete-de-boas-vindas", "name": "Banquete de Boas-vindas", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Depois de servir uma refeição completa a um grupo que permaneça à mesa por pelo menos trinta minutos, o Cozinheiro poderá realizar um teste de Ofício — Culinária.\nA CD depende da disposição do grupo:\n<table header-row=\"true\">\n<tr>\n<td>Disposição</td>\n<td>CD</td>\n</tr>\n<tr>\n<td>Receptiva</td>\n<td>10</td>\n</tr>\n<tr>\n<td>Indiferente</td>\n<td>15</td>\n</tr>\n<tr>\n<td>Desconfiada</td>\n<td>20</td>\n</tr>\n<tr>\n<td>Hostil</td>\n<td>25</td>\n</tr>\n</table>\nEm caso de sucesso, a disposição melhora em um estágio apenas para a conversa e hospitalidade relacionadas ao encontro.\nO banquete não controla ninguém, não apaga conflitos graves e não funciona durante combate, fuga ou perigo imediato. O mesmo grupo somente poderá ser afetado uma vez por encontro.", "source": "https://app.notion.com/p/3e4508f8aa6c81ebab61ce14596427d2" },
	{ "id": "cozinheiro:servico-profissional", "name": "Serviço Profissional", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "O Cozinheiro sabe organizar encomendas, calcular porções e apresentar um serviço culinário comercial.\nAo conseguir um cliente e dedicar o tempo combinado, poderá realizar trabalhos como:\n- Refeições para pequenos eventos.\n- Alimentação de expedições.\n- Cardápios para estabelecimentos.\n- Catering para concursos.\n- Preparação de lotes de viagem.\nO pagamento sugerido pelo serviço, além do custo dos ingredientes, é:\n<table header-row=\"true\">\n<tr>\n<td>Porte do serviço</td>\n<td>Tempo mínimo</td>\n<td>Pagamento sugerido</td>\n</tr>\n<tr>\n<td>Pequeno</td>\n<td>4 horas</td>\n<td>500 Pokécoins</td>\n</tr>\n<tr>\n<td>Médio</td>\n<td>1 dia</td>\n<td>1.500 Pokécoins</td>\n</tr>\n<tr>\n<td>Grande</td>\n<td>3 dias ou mais</td>\n<td>4.000 Pokécoins ou valor definido pelo Mestre</td>\n</tr>\n</table>\nO serviço exige cliente, instalações e ingredientes. Não gera renda automaticamente, e o Mestre define demanda, despesas e consequências da qualidade entregue.\nAumente também em 1 seu Carisma, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81e49bcac4c8c677379a" },
	{ "id": "cozinheiro:apresentacao-gastronomica", "name": "Apresentação Gastronômica", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "O Cozinheiro poderá transformar o preparo ou a apresentação de uma receita em parte de um espetáculo.\nQuando uma cena, concurso ou evento permitir uma apresentação culinária, poderá utilizar Ofício — Culinária no lugar de Atuação para avaliar exclusivamente:\n- Técnica de preparo.\n- Montagem do prato.\n- Serviço diante do público.\n- Criatividade culinária.\n- Coerência visual e temática.\nO talento não substitui Atuação em canto, dança, interpretação ou outras formas artísticas e não concede pontos automáticos em concursos.", "source": "https://app.notion.com/p/3e4508f8aa6c816d93defbaf38c14fcd" },
	{ "id": "cozinheiro:harmonizacao-de-sabores", "name": "Harmonização de Sabores", "kind": "class", "classId": "cozinheiro", "prerequisite": "", "text": "Antes de um concurso, o Cozinheiro poderá dedicar trinta minutos e consumir uma porção de Alimentos para preparar uma pequena refeição ligada à categoria e ao tema da apresentação de um Pokémon da equipe ativa de um treinador.\nNão existe teste para ativar o talento. O Pokémon deverá estar disposto a consumir a refeição. Se o relógio da campanha avançar uma hora ou mais antes de esse Pokémon entrar no concurso, o preparo perde o efeito.\nDepois que toda a pontuação normal do próximo concurso desse Pokémon for calculada, Harmonização de Sabores acrescenta **+3 pontos à pontuação final do participante**. Esse valor é somado uma única vez por concurso, independentemente da quantidade de rodadas, golpes ou Pokémon envolvidos na apresentação.\nO bônus representa preparação temática, aparência, aroma e coerência da refeição com a apresentação. Ele não altera notas individuais dos jurados, golpes, atributos, condição, PP, sincronia ou qualquer mecânica de batalha. Um participante somente poderá receber uma Harmonização de Sabores por concurso.", "source": "https://app.notion.com/p/3e4508f8aa6c81dabfded55d01e79cff" },
	{ "id": "cozinheiro:aproveitamento-superior", "name": "Aproveitamento Superior", "kind": "class", "classId": "cozinheiro", "prerequisite": "5º nível de Cozinheiro.", "text": "**Pré-requisito:** 5º nível de Cozinheiro.\nA eficiência de Aproveitamento Integral aumenta.\nAo preparar pelo menos quatro porções de uma mesma refeição, o Cozinheiro produz cinquenta por cento de porções adicionais, arredondando para baixo.\nExemplos:\n```plain text\n4 porções preparadas → 6 porções\n8 porções preparadas → 12 porções\n12 porções preparadas → 18 porções\n```\nAproveitamento Superior substitui o rendimento normal de Aproveitamento Integral; os dois não se acumulam.\nA regra continua não funcionando quando cada porção exige um componente individual e indivisível.", "source": "https://app.notion.com/p/3e4508f8aa6c818ab155defb3217738c" },
	{ "id": "cozinheiro:mestre-da-cozinha", "name": "Ápice — Mestre da Cozinha", "kind": "apex", "classId": "cozinheiro", "prerequisite": "10º nível de Cozinheiro.", "text": "**Pré-requisito:** 10º nível de Cozinheiro.\nQuando realizar um teste de Ofício — Culinária, um resultado natural inferior a 10 no d20 será tratado como 10, desde que possua ingredientes e tempo minimamente adequados.\nAlém disso:\n- Preparo Acelerado passa a reduzir o tempo em 50%, caso possua o talento.\n- A ausência de uma cozinha equipada nunca impõe penalidade em preparos possíveis com Cozinha de Campo.\n- Uma falha por até quatro pontos não destrói os ingredientes; o preparo falha e precisa ser corrigido ou refeito.\nEste ápice não exige talentos anteriores e não permite executar técnicas impossíveis sem o equipamento indispensável.", "source": "https://app.notion.com/p/3e4508f8aa6c818898fcd3708198e116" },
	{ "id": "cozinheiro:mesa-para-todos", "name": "Ápice — Mesa para Todos", "kind": "apex", "classId": "cozinheiro", "prerequisite": "10º nível de Cozinheiro, Aproveitamento Superior e Banquete de Boas-vindas.", "text": "**Pré-requisito:** 10º nível de Cozinheiro, Aproveitamento Superior e Banquete de Boas-vindas.\nAo preparar pelo menos dez porções de uma mesma refeição para uma comunidade, evento ou expedição, o Cozinheiro dobra a quantidade final de porções.\n```plain text\n10 porções preparadas → 20 porções\n20 porções preparadas → 40 porções\n```\nEsse rendimento substitui Aproveitamento Integral e Aproveitamento Superior.\nQuando servir esse preparo como Banquete de Boas-vindas, poderá afetar todos os participantes que realmente compartilhem da refeição, mesmo que pertençam a grupos distintos. Cada grupo mantém sua própria CD e suas razões para aceitar ou rejeitar a hospitalidade.", "source": "https://app.notion.com/p/3e4508f8aa6c81e295fac7f94b908570" },
	{ "id": "cozinheiro:chef-pokemon", "name": "Ápice — Chef Pokémon", "kind": "apex", "classId": "cozinheiro", "prerequisite": "10º nível de Cozinheiro, Petisco de Amizade e Harmonização de Sabores.", "text": "**Pré-requisito:** 10º nível de Cozinheiro, Petisco de Amizade e Harmonização de Sabores.\nOs Petiscos de Amizade preparados pelo Cozinheiro concedem:\n```plain text\n+10 de amizade\n```\nO intervalo de sete dias para o mesmo Pokémon permanece.\nAlém disso, ao utilizar Harmonização de Sabores, poderá preparar alimento para até três Pokémon da mesma apresentação. Cada Pokémon exige sua própria porção e todos precisam participar da apresentação beneficiada.\nA Harmonização continua acrescentando **+3 pontos uma única vez à pontuação final do participante**. Preparar para mais Pokémon não multiplica esse bônus.\nO talento não altera golpes, atributos, condição, PP, sincronia, notas individuais dos jurados ou qualquer mecânica de combate.", "source": "https://app.notion.com/p/3e4508f8aa6c81769807e20ba963ad5b" },
	{ "id": "coreografo:sinais-de-longo-alcance", "name": "Sinais de Longo Alcance", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Os sinais da Linguagem Coreográfica poderão ser compreendidos por um Pokémon ensaiado a até:\n```plain text\n30 metros\n```\nO Pokémon ainda precisa conseguir ver o gesto ou ouvir o sinal utilizado.\nO talento não atravessa isolamento acústico, obstáculos visuais completos ou efeitos que impeçam o Pokémon de perceber o Coreógrafo.", "source": "https://app.notion.com/p/3e4508f8aa6c81e6a769d3d5d8e48307" },
	{ "id": "coreografo:entrada-marcante", "name": "Entrada Marcante", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Este talento funciona apenas em apresentações de formato solo.\nQuando a apresentação começa com um golpe coerente com a categoria principal do concurso e esse golpe não foi utilizado como abertura pelo participante na rodada anterior, a entrada ensaiada acrescenta:\n```plain text\n+1 ponto à pontuação final\n```\nO bônus é calculado automaticamente depois da pontuação normal e se acumula com outros talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c81c6a31ac7a38a4cbe79" },
	{ "id": "coreografo:encerramento-memoravel", "name": "Encerramento Memorável", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Este talento funciona apenas em apresentações de formato solo.\nQuando o último golpe da apresentação é coerente com a categoria principal do concurso e não repete o golpe imediatamente anterior, o encerramento ensaiado acrescenta:\n```plain text\n+1 ponto à pontuação final\n```\nO bônus é calculado automaticamente depois da pontuação normal e se acumula com outros talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c81ea946aef83abee94bf" },
	{ "id": "coreografo:tema-unificado", "name": "Tema Unificado", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Antes do concurso, o Coreógrafo poderá declarar um tema para sua sequência ensaiada.\nSe todos os golpes apresentados possuírem coerência reconhecida pelo sistema com a categoria do concurso ou compartilharem uma relação temática válida entre suas tags, o participante recebe:\n```plain text\n+2 pontos à pontuação final\n```\nO tema não altera a categoria, as tags ou a pontuação natural dos golpes. O bônus se acumula com outros talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c815d898ff9bdd6811306" },
	{ "id": "coreografo:formacao-em-dupla", "name": "Formação em Dupla", "kind": "class", "classId": "coreografo", "prerequisite": "5º nível de Coreógrafo.", "text": "**Pré-requisito:** 5º nível de Coreógrafo.\nQuando participa de um concurso em dupla com dois Pokémon previamente ensaiados, o Coreógrafo poderá registrar uma formação conjunta.\nSe ambos participarem normalmente da apresentação e executarem ao menos uma parte da formação, o participante recebe:\n```plain text\n+2 pontos à pontuação final\n```\nA formação exige uma hora de ensaio com os dois Pokémon presentes. O bônus se acumula com outros talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c8189aa1cd0d96855b69c" },
	{ "id": "coreografo:formacao-em-trio", "name": "Formação em Trio", "kind": "class", "classId": "coreografo", "prerequisite": "7º nível de Coreógrafo e Formação em Dupla.", "text": "**Pré-requisito:** 7º nível de Coreógrafo e Formação em Dupla.\nQuando participa de um concurso em trio com três Pokémon previamente ensaiados, o Coreógrafo poderá registrar uma formação conjunta.\nSe os três participarem normalmente e executarem ao menos uma parte da formação, o participante recebe:\n```plain text\n+3 pontos à pontuação final\n```\nA formação exige duas horas de ensaio com os três Pokémon presentes. Formação em Trio substitui os dois pontos de Formação em Dupla; ela não recebe os dois bônus simultaneamente.\nO bônus se acumula com os demais talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c816b8af8ea3b5183163f" },
	{ "id": "coreografo:transicao-fluida", "name": "Transição Fluida", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Quando cada golpe da sequência é diferente do anterior e a ordem forma ao menos uma combinação reconhecida pelo sistema de concursos, as mudanças de posição ensaiadas acrescentam:\n```plain text\n+1 ponto à pontuação final\n```\nO talento não cria uma combinação inexistente nem remove penalidades próprias dos golpes utilizados.\nO bônus se acumula com outros talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.", "source": "https://app.notion.com/p/3e4508f8aa6c81f08b35eac2713a9a24" },
	{ "id": "coreografo:diretor-convidado", "name": "Diretor Convidado", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "O Coreógrafo poderá ensaiar durante uma hora com outro participante e seus Pokémon, mesmo sem participar do concurso.\nO participante dirigido recebe:\n```plain text\n+1 ponto à pontuação final de uma apresentação\n```\nO benefício precisa ser declarado antes do concurso e vale somente para a formação ensaiada.\nUma apresentação somente poderá receber o benefício de um Diretor Convidado. O ponto se acumula com talentos específicos possuídos pelo próprio participante.", "source": "https://app.notion.com/p/3e4508f8aa6c816ca218cc44c42c9a0a" },
	{ "id": "coreografo:movimento-espelhado", "name": "Movimento Espelhado", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Quando o Coreógrafo executa movimentos corporais junto de um Pokémon disposto, recebe:\n```plain text\n+2 em Atuação ou Acrobacia\n```\nO bônus se aplica a danças, demonstrações, travessias coreografadas e cenas em que treinador e Pokémon realmente reproduzam, acompanhem ou completem os movimentos um do outro.\nNão se aplica a ataques, esquivas, perseguições ou ações de batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c81459e42c2a80f28eaa7" },
	{ "id": "coreografo:palco-seguro", "name": "Palco Seguro", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Ao organizar posições, objetos cênicos, cabos, plataformas ou caminhos de entrada, o Coreógrafo poderá delimitar a área da apresentação.\nDentro dessa área, uma falha por até quatro pontos em testes de montagem ou movimentação:\n- Não fere participantes.\n- Não derruba estruturas sobre o público.\n- Não destrói o equipamento cênico.\n- Interrompe o preparo até que o problema seja corrigido.\nFalhas por cinco ou mais produzem as consequências normais. O talento não protege contra sabotagem, violência ou perigos que o Coreógrafo desconheça.", "source": "https://app.notion.com/p/3e4508f8aa6c811699a9def2b4cd3d03" },
	{ "id": "coreografo:producao-itinerante", "name": "Produção Itinerante", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "O Coreógrafo sabe organizar apresentações conjuntas como trabalho profissional.\nAo conseguir público ou contratante, poderá preparar:\n- Espetáculos de treinador e Pokémon.\n- Aberturas de eventos.\n- Números para festivais.\n- Direção de apresentações alheias.\n- Ensaios para concursos.\nO pagamento sugerido, além de despesas com local e materiais, é:\n<table header-row=\"true\">\n<tr>\n<td>Produção</td>\n<td>Tempo mínimo</td>\n<td>Pagamento sugerido</td>\n</tr>\n<tr>\n<td>Pequena</td>\n<td>4 horas</td>\n<td>500 Pokécoins</td>\n</tr>\n<tr>\n<td>Média</td>\n<td>1 dia</td>\n<td>1.500 Pokécoins</td>\n</tr>\n<tr>\n<td>Grande</td>\n<td>3 dias ou mais</td>\n<td>4.000 Pokécoins ou valor definido pelo Mestre</td>\n</tr>\n</table>\nO talento não gera renda automática. O Mestre determina oportunidades, custos, público e consequências da qualidade entregue.", "source": "https://app.notion.com/p/3e4508f8aa6c8138a38fdde88ed29e29" },
	{ "id": "coreografo:leitura-do-espaco", "name": "Leitura do Espaço", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Depois de observar por pelo menos um minuto um palco, arena, salão ou área de apresentação, o Coreógrafo recebe:\n```plain text\n+2 em Percepção para identificar problemas de circulação e posicionamento\n```\nPoderá reconhecer:\n- Pontos cegos do público.\n- Entradas e saídas inadequadas.\n- Obstáculos ao movimento.\n- Áreas com iluminação ruim.\n- Espaços insuficientes para Pokémon grandes.\n- Riscos evidentes para uma formação planejada.\nO talento não revela armadilhas ocultas sem evidências perceptíveis nem substitui Investigação.", "source": "https://app.notion.com/p/3e4508f8aa6c81e5b5b8e9c00f58a12e" },
	{ "id": "coreografo:mestre-de-cerimonias", "name": "Mestre de Cerimônias", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "O Coreógrafo sabe organizar a ordem e o ritmo de eventos coletivos.\nDepois de conhecer o espaço, os participantes e a programação, recebe:\n```plain text\n+2 em Atuação ou Persuasão para conduzir o evento\n```\nO benefício poderá ser utilizado para:\n- Apresentar participantes.\n- Manter a programação compreensível.\n- Conduzir transições entre atividades.\n- Recuperar a atenção do público após uma interrupção.\n- Organizar entradas e saídas.\n- Transmitir instruções gerais aos presentes.\nO talento não controla o público, não substitui negociação individual e não obriga participantes hostis a colaborar.", "source": "https://app.notion.com/p/3e4508f8aa6c81948e44e37233e1be89" },
	{ "id": "coreografo:leitura-cinetica", "name": "Leitura Cinética", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Depois de observar uma criatura se movimentar por pelo menos um minuto, o Coreógrafo poderá realizar um teste de Percepção.\nEm caso de sucesso, identifica informações perceptíveis pela postura e pelo movimento, como:\n- Cansaço físico evidente.\n- Desequilíbrio ou limitação de movimento.\n- Lado do corpo que a criatura protege.\n- Movimentos ensaiados ou repetidos.\n- Falta de coordenação entre integrantes de um grupo.\n- Se alguém está imitando deliberadamente os gestos de outra pessoa.\nLeitura Cinética não diagnostica doenças, não determina atributos, não prevê ataques e não revela pensamentos ou intenções ocultas. Informações médicas precisas continuam exigindo Medicina ou Medicina Pokémon.\nAumente também em 1 sua Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c8176a9d4c0860204a28d" },
	{ "id": "coreografo:conducao-de-evacuacao", "name": "Condução de Evacuação", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "Quando pessoas ou Pokémon dispostos precisam abandonar uma área perigosa, o Coreógrafo poderá dedicar uma ação ou intervalo equivalente para estabelecer posições, sinais e ordem de deslocamento.\nUma quantidade de criaturas igual ao dobro de seu bônus de proficiência poderá seguir a condução. Enquanto permanecerem juntas e conseguirem perceber seus sinais:\n- Não bloqueiam involuntariamente o caminho umas das outras.\n- Recebem +2 em testes realizados para atravessar passagens estreitas, terreno instável ou obstáculos durante a evacuação.\n- Conseguem manter uma ordem previamente definida.\n- Uma criatura caída ou atrasada é percebida imediatamente pelo grupo.\nO talento não aumenta deslocamento, não impede ataques, não remove condições e não obriga criaturas em pânico ou hostis a obedecer.", "source": "https://app.notion.com/p/3e4508f8aa6c814b9865fd5cfe545b43" },
	{ "id": "coreografo:preparacao-corporal-conjunta", "name": "Preparação Corporal Conjunta", "kind": "class", "classId": "coreografo", "prerequisite": "", "text": "O Coreógrafo poderá conduzir dez minutos de aquecimento, alongamento e marcação de movimentos com um grupo disposto.\nEscolha uma atividade física específica que será realizada logo depois, como:\n- Dança.\n- Travessia de equilíbrio.\n- Escalada simples.\n- Marcha prolongada.\n- Transporte coordenado de um objeto.\n- Montagem de palco.\n- Movimentação por um percurso conhecido.\nAté uma quantidade de participantes igual ao bônus de proficiência do Coreógrafo recebe:\n```plain text\n+1 no primeiro teste físico relacionado à atividade preparada\n```\nO benefício expira quando a atividade terminar ou quando as condições mudarem significativamente.\nPreparação Corporal Conjunta não se aplica a ataques, esquivas, perseguições, iniciativa ou qualquer ação de batalha.\nAumente também em 1 sua Destreza, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c8124830ecd67367ab364" },
	{ "id": "coreografo:diretor-de-espetaculo", "name": "Ápice — Diretor de Espetáculo", "kind": "apex", "classId": "coreografo", "prerequisite": "10º nível de Coreógrafo.", "text": "**Pré-requisito:** 10º nível de Coreógrafo.\nA Sincronia de um Pokémon com o qual o Coreógrafo possua Ensaio Conjunto não poderá ser inferior a:\n```plain text\n4\n```\nAlém disso, quando participar pessoalmente de um concurso com ao menos um Pokémon ensaiado, recebe:\n```plain text\n+3 pontos à pontuação final\n```\nEsse bônus se acumula com os talentos específicos do Coreógrafo cujos requisitos também forem cumpridos.\nDiretor de Espetáculo não exige talentos anteriores e não altera golpes, PP, atributos ou notas individuais dos jurados.", "source": "https://app.notion.com/p/3e4508f8aa6c811681a2d097ba7b9f45" },
	{ "id": "coreografo:geometria-em-movimento", "name": "Ápice — Geometria em Movimento", "kind": "apex", "classId": "coreografo", "prerequisite": "10º nível de Coreógrafo e Formação em Dupla ou Formação em Trio.", "text": "**Pré-requisito:** 10º nível de Coreógrafo e Formação em Dupla ou Formação em Trio.\nEm uma apresentação de dupla ou trio com uma formação válida, o participante recebe:\n```plain text\n+3 pontos à pontuação final\n```\nEsse valor se acumula com Formação em Dupla ou Formação em Trio e com os demais talentos específicos cujos requisitos forem cumpridos.\nAlém disso, diferenças de tamanho entre os Pokémon não impedem posições ensaiadas quando existir espaço físico e uma adaptação plausível. O Coreógrafo poderá redefinir alturas, distâncias e trajetórias da formação sem precisar substituir seus movimentos principais.\nO talento não permite movimentos anatomicamente impossíveis, não faz Pokémon voarem sem essa capacidade e não ignora limitações reais do palco.", "source": "https://app.notion.com/p/3e4508f8aa6c815fb9adc3758946fd77" },
	{ "id": "coreografo:entrosamento-instintivo", "name": "Ápice — Entrosamento Instintivo", "kind": "apex", "classId": "coreografo", "prerequisite": "10º nível de Coreógrafo.", "text": "**Pré-requisito:** 10º nível de Coreógrafo.\nAo trabalhar com um Pokémon que possua pelo menos 50 pontos de amizade, o Coreógrafo poderá realizar um aquecimento de dez minutos para estabelecer um entrosamento temporário.\nAté o fim da apresentação ou espetáculo atual, esse Pokémon será tratado como se possuísse um Ensaio Conjunto com o Coreógrafo para:\n- Receber o +2 em Atuação conjunta.\n- Ter Sincronia mínima 3.\n- Compreender a Linguagem Coreográfica.\n- Participar de formações de dupla ou trio que o Coreógrafo já conheça.\nO aquecimento não cria uma sequência permanente. Ele precisa ser repetido em uma apresentação futura e não permite utilizar posições ou movimentos que o Pokémon seja incapaz de executar.\nEste ápice não acrescenta pontos diretamente ao concurso e não altera golpes, PP, atributos ou qualquer mecânica de batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c81f9a138ffb54069faa1" },
	{ "id": "criador-pokemon:afinidade-aprimorada", "name": "Afinidade Aprimorada", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "A experiência do Criador torna o primeiro vínculo mais estável. Todo Pokémon capturado por ele passa a iniciar com **20 pontos adicionais de Amizade**, em vez dos 10 concedidos por Afinidade Natural.\nO bônus é aplicado somente no momento da captura e não se repete caso o Pokémon seja transferido, trocado ou devolvido ao treinador.", "source": "https://app.notion.com/p/3e4508f8aa6c81338427eed8892e0bbd" },
	{ "id": "criador-pokemon:aproximacao-de-resgate", "name": "Aproximação de Resgate", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "Quando o Criador presta cuidados reais a um Pokémon selvagem ferido, doente, preso ou em perigo, sem ter iniciado confronto contra ele, a disposição da criatura melhora em **um grau adicional** após o atendimento.\nEsse benefício exige meios adequados e uma ajuda relevante. Ele não domestica o Pokémon, não garante captura e não funciona quando o suposto resgate foi provocado pelo próprio Criador ou por seus aliados.", "source": "https://app.notion.com/p/3e4508f8aa6c815a8a10f12cdceb58ca" },
	{ "id": "criador-pokemon:incubacao-assistida", "name": "Incubação Assistida", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "Ao acompanhar diariamente um ovo mantido em incubadora adequada, o Criador reduz em **20%** o tempo total de incubação.\nA assistência exige acesso regular ao ovo e condições apropriadas durante o período. Apenas um benefício de Incubação Assistida poderá ser aplicado ao mesmo ovo, mesmo que existam vários Criadores Pokémon.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c81e8b203f4e9ed5cc82b" },
	{ "id": "criador-pokemon:nascimento-acolhido", "name": "Nascimento Acolhido", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "Quando acompanha o nascimento de um Pokémon desde pelo menos a metade do período de incubação, o Criador prepara ambiente, temperatura e contato inicial adequados.\nO Pokémon nasce com **60 de Amizade**, em vez dos 50 normais. Esse valor substitui a Amizade inicial do nascimento e não se acumula com outro uso deste talento.", "source": "https://app.notion.com/p/3e4508f8aa6c8149a784ec7272b373f4" },
	{ "id": "criador-pokemon:reproducao-assistida", "name": "Reprodução Assistida", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "Ao acompanhar pessoalmente um processo de reprodução desde o início, com instalações e recursos adequados, o Criador reduz em **20%** o tempo necessário para a produção do ovo.\nO talento não altera compatibilidade, espécie, forma, sexo, natureza, habilidade, IVs, Egg Moves ou chance de Pokémon shiny. Apenas um Criador poderá conceder essa redução a cada reprodução.", "source": "https://app.notion.com/p/3e4508f8aa6c81ca803ee3b11bfe3816" },
	{ "id": "criador-pokemon:incubacao-de-emergencia", "name": "Incubação de Emergência", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 5 e Incubação Assistida.", "text": "## Pré-requisito\nCriador Pokémon nível 5 e Incubação Assistida.\nQuando uma incubadora deixa de funcionar ou o ovo precisa ser removido dela inesperadamente, o Criador poderá improvisar condições seguras utilizando um Kit de Medicina Pokémon e uma carga.\nO ovo poderá permanecer protegido por até **24 horas de campanha** sem sofrer danos ou regressão. Durante esse período, a contagem da incubação fica pausada e volta a avançar quando o ovo retorna a uma incubadora adequada.\nCada ovo exige sua própria carga. O talento não acelera a incubação, não permite chocar o ovo sem incubadora e não protege contra dano deliberado ou condições extremas que impossibilitem qualquer cuidado.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c81588c49fc4b346d1c9f" },
	{ "id": "criador-pokemon:primeiros-cuidados-rapidos", "name": "Primeiros Cuidados Rápidos", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "O tempo necessário para utilizar Primeiros Cuidados é reduzido de **10 para 5 minutos**.\nAs demais exigências permanecem: o procedimento ocorre fora de combate, requer local seguro, Kit de Medicina Pokémon, uma carga e deixa o Pokémon com 1 PV. O intervalo de sete dias para o mesmo Pokémon não é alterado.", "source": "https://app.notion.com/p/3e4508f8aa6c816c9d01c6ebd647220e" },
	{ "id": "criador-pokemon:recuperacao-acompanhada", "name": "Recuperação Acompanhada", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 5 e Primeiros Cuidados Rápidos.", "text": "## Pré-requisito\nCriador Pokémon nível 5 e Primeiros Cuidados Rápidos.\nO intervalo para que um mesmo Pokémon possa receber novamente Primeiros Cuidados é reduzido de **sete para cinco dias de campanha**.\nO talento não aumenta os PV recuperados, não remove condições, não recupera PP e não permite o procedimento durante uma batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c81eab3eae0b170efaec5" },
	{ "id": "criador-pokemon:leitura-comportamental", "name": "Leitura Comportamental", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "Ao interpretar medo, confiança, desconforto, agressividade ou hesitação de um Pokémon, o Criador poderá utilizar **Empatia Pokémon no lugar de Intuição**.\nA substituição se aplica apenas quando o objeto do teste é o comportamento de um Pokémon. Ela não revela pensamentos, memórias, natureza mecânica, habilidade ou intenção perfeitamente oculta.\nAumente também em 1 sua Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c8102800df73e2c29ad5f" },
	{ "id": "criador-pokemon:manejo-sem-estresse", "name": "Manejo sem Estresse", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "O Criador recebe **+2 em testes realizados para conduzir, transportar, examinar ou conter sem violência um Pokémon assustado, ferido ou agitado**, desde que a situação não seja um combate.\nO bônus não se aplica a ataques, captura, fuga, comandos de batalha ou contenção agressiva.", "source": "https://app.notion.com/p/3e4508f8aa6c810199d3f8b906f62459" },
	{ "id": "criador-pokemon:rotina-de-enriquecimento", "name": "Rotina de Enriquecimento", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "O Criador poderá dedicar uma hora a exercícios, brincadeiras e estímulos apropriados para um Pokémon sob seus cuidados. Ao concluir a atividade, o Pokémon recebe **+5 de Amizade**.\nUm mesmo Pokémon poderá receber esse benefício somente uma vez a cada 2 dias de campanha. A atividade exige espaço e materiais coerentes com a espécie e não substitui alimentação, repouso ou tratamento.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c8135baefee344746c25d" },
	{ "id": "criador-pokemon:reabilitacao-comportamental", "name": "Reabilitação Comportamental", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 5 e Leitura Comportamental.", "text": "## Pré-requisito\nCriador Pokémon nível 5 e Leitura Comportamental.\nO Criador poderá conduzir um projeto de reabilitação para um Pokémon que apresente medo persistente, aversão, ansiedade, agressividade defensiva ou outro problema comportamental reconhecido pelo Mestre.\nO projeto exige pelo menos **sete dias de campanha**, cuidados diários e condições seguras. Ao final, um teste adequado de Empatia Pokémon ou Adestramento Pokémon determina o resultado:\n- **Sucesso:** o problema é removido ou reduzido em um estágio.\n- **Falha:** não há regressão, mas o projeto precisa de mais tempo ou de uma nova abordagem.\n- **Falha por 5 ou mais:** o Mestre poderá introduzir uma complicação coerente, sem apagar o progresso já conquistado.\nO talento não remove condições médicas, efeitos sobrenaturais nem obediência causada por controle externo.", "source": "https://app.notion.com/p/3e4508f8aa6c81749204cb6419a6938f" },
	{ "id": "criador-pokemon:ninho-intacto", "name": "Ninho Intacto", "kind": "class", "classId": "criador-pokemon", "prerequisite": "", "text": "O Criador recebe **+2 em Percepção ou Sobrevivência** para localizar ninhos, tocas, trilhas de filhotes, áreas de reprodução ou sinais de cuidado parental Pokémon.\nAlém disso, se falhar nesse teste por até quatro pontos, sua busca não perturba o ninho nem alerta os Pokémon responsáveis. Uma falha por cinco ou mais produz as consequências normais.", "source": "https://app.notion.com/p/3e4508f8aa6c81b39e7ac38f2b6c1196" },
	{ "id": "criador-pokemon:mediacao-de-especies", "name": "Mediação de Espécies", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 5 e Leitura Comportamental.", "text": "## Pré-requisito\nCriador Pokémon nível 5 e Leitura Comportamental.\nQuando tenta encerrar uma disputa entre Pokémon que ainda não entraram em combate, o Criador poderá utilizar **Empatia Pokémon no lugar de Persuasão**.\nEm caso de sucesso, os envolvidos interrompem a escalada pelo tempo suficiente para se afastarem, aceitarem separação ou ouvirem uma solução simples. O efeito não controla as criaturas, não resolve disputas territoriais automaticamente e termina se alguém voltar a ameaçá-las.", "source": "https://app.notion.com/p/3e4508f8aa6c81628e63dc201d5117bd" },
	{ "id": "criador-pokemon:acalmar-sem-conter", "name": "Acalmar sem Conter", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Manejo sem Estresse.", "text": "## Pré-requisito\nManejo sem Estresse.\nApós pelo menos um minuto de aproximação cuidadosa, o Criador poderá realizar um teste de Empatia Pokémon para acalmar um Pokémon assustado ou agitado fora de combate.\nEm caso de sucesso, a criatura deixa de reagir impulsivamente a estímulos menores durante a cena e poderá ser examinada, conduzida ou retirada do perigo. Uma ameaça real, agressão ou tentativa de captura encerra o efeito imediatamente.", "source": "https://app.notion.com/p/3e4508f8aa6c81288eacc869877c5f3c" },
	{ "id": "criador-pokemon:preparacao-impecavel", "name": "Preparação Impecável", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 5.", "text": "## Pré-requisito\nCriador Pokémon nível 5.\nAntes de um concurso, o Criador poderá dedicar trinta minutos à higiene, apresentação, conforto e preparação de um Pokémon participante. Ao fim da apresentação, esse Pokémon recebe **+2 pontos na pontuação final do concurso**.\nO Criador poderá preparar apenas um Pokémon por concurso. O bônus não altera golpes, Performance, Sincronia, ações, PP ou notas individuais dos jurados e não se acumula com outro uso de Preparação Impecável.", "source": "https://app.notion.com/p/3e4508f8aa6c81338b6dc649fd70a11b" },
	{ "id": "criador-pokemon:socorro-bem-administrado", "name": "Socorro Bem Administrado", "kind": "class", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 7 e Recuperação Acompanhada.", "text": "## Pré-requisito\nCriador Pokémon nível 7 e Recuperação Acompanhada.\nAo utilizar Primeiros Cuidados, o Criador aproveita melhor os suprimentos. Depois do procedimento, role `1d6`. Em resultado **5 ou 6**, a carga do Kit de Medicina Pokémon não é consumida.\nO Pokémon ainda fica com apenas 1 PV e todas as restrições de Primeiros Cuidados permanecem. O teste de economia é realizado somente depois de concluir o atendimento.", "source": "https://app.notion.com/p/3e4508f8aa6c819999f6fff6e5c66b46" },
	{ "id": "criador-pokemon:guardiao-de-geracoes", "name": "Ápice — Guardião de Gerações", "kind": "apex", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 10.", "text": "## Pré-requisito\nCriador Pokémon nível 10.\nO Criador torna-se uma referência completa em bem-estar e adaptação. Seus benefícios passam a ser:\n- Pokémon capturados por ele iniciam com **20 pontos adicionais de Amizade**.\n- Pokémon cujo nascimento ele acompanhou desde pelo menos a metade da incubação nascem com **60 de Amizade**.\n- Uma vez a cada sete dias de campanha, poderá concluir uma Rotina de Enriquecimento com até **seis Pokémon simultaneamente**, concedendo +5 de Amizade a cada um.\nOs valores substituem os benefícios menores da classe e não se acumulam com Afinidade Aprimorada ou Nascimento Acolhido.", "source": "https://app.notion.com/p/3e4508f8aa6c818da256d233a6ee982e" },
	{ "id": "criador-pokemon:mestre-do-bercario", "name": "Ápice — Mestre do Berçário", "kind": "apex", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 10, Incubação Assistida, Reprodução Assistida e Incubação de Emergência.", "text": "## Pré-requisito\nCriador Pokémon nível 10, Incubação Assistida, Reprodução Assistida e Incubação de Emergência.\nQuando o Criador acompanha integralmente um processo:\n- O tempo de reprodução é reduzido em **30%**.\n- O tempo de incubação é reduzido em **30%**.\n- Incubação de Emergência protege cada ovo por até **48 horas de campanha**, ainda consumindo uma carga do Kit de Medicina Pokémon por ovo.\nNenhuma redução se acumula com outro Criador ou com versões menores dos mesmos talentos. O ápice não altera espécie, forma, sexo, natureza, habilidade, IVs, Egg Moves ou chance de Pokémon shiny.", "source": "https://app.notion.com/p/3e4508f8aa6c81a5bdf7df9b0d7c9949" },
	{ "id": "criador-pokemon:restaurador-pokemon", "name": "Ápice — Restaurador Pokémon", "kind": "apex", "classId": "criador-pokemon", "prerequisite": "Criador Pokémon nível 10, Recuperação Acompanhada e Reabilitação Comportamental.", "text": "## Pré-requisito\nCriador Pokémon nível 10, Recuperação Acompanhada e Reabilitação Comportamental.\nOs Primeiros Cuidados realizados pelo Criador passam a restaurar **10% dos PV máximos do Pokémon, arredondados para cima**, em vez de deixá-lo com apenas 1 PV.\nO procedimento continua exigindo cinco minutos, local seguro, Kit de Medicina Pokémon e uma carga. O mesmo Pokémon somente poderá receber esse atendimento novamente após cinco dias de campanha. O efeito não remove condições, não recupera PP e nunca poderá ser utilizado durante uma batalha.", "source": "https://app.notion.com/p/3e4508f8aa6c81288f43fa74b5f2d61b" },
	{ "id": "detetive:busca-sistematica", "name": "Busca Sistemática", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "Ao procurar pistas em uma área delimitada, o Detetive organiza a busca por setores, padrões e pontos de interesse.\nO tempo necessário para realizar uma busca minuciosa é reduzido pela metade. Além disso, uma falha por até quatro pontos não encerra a busca nem faz o grupo concluir que não há evidências: apenas indica que será necessário mais tempo, outra ferramenta ou uma abordagem diferente.\nO talento não revela pistas inexistentes e não protege contra falhas graves.", "source": "https://app.notion.com/p/3e4508f8aa6c81efa83dc095ffe6b23a" },
	{ "id": "detetive:cadeia-de-custodia", "name": "Cadeia de Custódia", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "Ao recolher uma evidência, o Detetive poderá catalogá-la, acondicioná-la e registrar quem teve acesso a ela. O procedimento exige materiais apropriados e alguns minutos.\nEnquanto o registro permanecer íntegro, o Detetive consegue reconhecer se a evidência foi aberta, substituída, contaminada ou manipulada depois da coleta. Ele também poderá demonstrar a origem e o caminho percorrido pelo objeto, desde que seus registros sejam apresentados.\nO talento não identifica automaticamente o responsável pela adulteração.", "source": "https://app.notion.com/p/3e4508f8aa6c8100b4f9c229a9716e55" },
	{ "id": "detetive:arquivo-de-casos", "name": "Arquivo de Casos", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "O Detetive poderá manter dossiês ativos sobre pessoas, organizações, locais ou acontecimentos. Criar um dossiê exige pelo menos uma hora reunindo informações verificáveis.\nAo investigar diretamente o assunto de um dossiê, recebe **+2 em Investigação** para cruzar nomes, datas, relações, padrões e evidências já registradas.\nO número máximo de dossiês ativos é igual ao bônus de proficiência do Detetive. Substituir um dossiê exige organizar ou arquivar o anterior.", "source": "https://app.notion.com/p/3e4508f8aa6c81a7976ff2f25ec52d6b" },
	{ "id": "detetive:perfil-investigativo", "name": "Perfil Investigativo", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "Depois de reunir ao menos três evidências independentes sobre a atuação de uma pessoa ainda não identificada, o Detetive poderá passar dez minutos construindo um perfil.\nEle escolhe uma das perguntas abaixo, e o Mestre responde com a conclusão mais provável sustentada pelas pistas:\n- A ação parece planejada ou impulsiva?\n- O responsável conhecia o local ou a vítima?\n- Trabalhou sozinho ou recebeu ajuda?\n- Qual recurso ou conhecimento provavelmente possuía?\n- Qual risco parece disposto a assumir?\n- Que tipo de local ou alvo provavelmente procuraria em seguida?\nNovas perguntas exigem novas evidências relevantes. O perfil indica probabilidades, não identidade ou certeza absoluta.\nAumente também em 1 sua Inteligência ou Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c817aa2f0fc3a3633709c" },
	{ "id": "detetive:vigilancia-discreta", "name": "Vigilância Discreta", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "Durante uma vigilância, o Detetive sabe alternar pontos de observação, registrar horários e evitar padrões óbvios.\nRecebe **+2 em Percepção ou Furtividade** para acompanhar à distância uma pessoa, veículo ou local sem ser percebido. Se falhar por até quatro pontos, perde momentaneamente o alvo ou uma parte da informação, mas não revela automaticamente que estava observando.\nFalhas graves e situações sem cobertura produzem consequências normais.", "source": "https://app.notion.com/p/3e4508f8aa6c8152a93cc12cd3518cf8" },
	{ "id": "detetive:olho-para-ausencias", "name": "Olho para Ausências", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "O Detetive considera não apenas o que está presente, mas também o que deveria estar.\nAo concluir uma busca ou Reconstrução dos Fatos, poderá perguntar se há sinal de que um objeto, registro, pessoa ou parte da cena foi removido, limpo, substituído ou deliberadamente omitido. Se as evidências permitirem essa conclusão, o Mestre indica a categoria do elemento ausente e o indício que denuncia sua falta.\nO talento não informa automaticamente a identidade exata do que foi removido.", "source": "https://app.notion.com/p/3e4508f8aa6c815d9204ea33295d3712" },
	{ "id": "detetive:parceiro-investigativo", "name": "Parceiro Investigativo", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "O Detetive poderá treinar um Pokémon com pelo menos **50 de Amizade** para auxiliá-lo em buscas fora de combate. O treinamento exige sete dias de campanha e define sinais simples para procurar odores, objetos, pessoas, rotas ou alterações no ambiente.\nEnquanto o parceiro puder participar de maneira coerente, o Detetive recebe **+2 em um teste de Investigação ou Percepção por cena**. O Pokémon não realiza conclusões lógicas e o talento não concede qualquer benefício em batalha.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c81b4bbf1eb16e73550b2" },
	{ "id": "detetive:voz-do-parceiro", "name": "Voz do Parceiro", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 7 e Parceiro Investigativo.", "text": "## Pré-requisito\nDetetive nível 7 e Parceiro Investigativo.\nO Detetive escolhe definitivamente o Pokémon treinado como seu Parceiro Investigativo. Esse Pokémon adquire a capacidade de falar e compreender normalmente um idioma conhecido pelo Detetive.\nEle poderá relatar o que viu, formular opiniões, fazer perguntas, interpretar instruções e participar de conversas de acordo com sua Inteligência, experiências e personalidade. Falar não lhe concede conhecimentos que não possua, leitura perfeita de pessoas ou compreensão automática de conceitos técnicos.\nO Pokémon passa a ser interpretado e controlado pelo Mestre fora das decisões normais de batalha. Ele é um personagem próprio: poderá discordar, hesitar, esconder sentimentos ou agir conforme seus vínculos e convicções.\nEste talento possui **aquisição e uso únicos**. A escolha não poderá ser transferida para outro Pokémon e nenhum segundo Pokémon poderá receber essa capacidade por meio dele.\nA fala não altera atributos, golpes, habilidade, ações ou qualquer cálculo de combate.", "source": "https://app.notion.com/p/3e4508f8aa6c814abf7ecc8a04345f26" },
	{ "id": "detetive:passo-de-perseguicao", "name": "Passo de Perseguição", "kind": "class", "classId": "detetive", "prerequisite": "", "text": "O Detetive recebe **+2 em Atletismo, Acrobacia ou Pilotagem** quando o teste for realizado diretamente para perseguir um alvo, escapar de um perseguidor ou evitar perdê-lo durante uma perseguição.\nO bônus vale somente para manter ou romper a distância. Ele não se aplica a ataques, dano, iniciativa ou manobras de combate.", "source": "https://app.notion.com/p/3e4508f8aa6c81a0bdbac0d37de908d4" },
	{ "id": "detetive:contradicao-explorada", "name": "Contradição Explorada", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 5.", "text": "## Pré-requisito\nDetetive nível 5.\nDepois de identificar uma contradição real entre uma declaração e outra informação conhecida, o Detetive poderá apresentá-la de forma precisa. Ele recebe **+2 no próximo teste de Persuasão ou Intimidação** realizado contra o depoente durante a mesma conversa.\nSe o teste falhar por até quatro pontos, o depoente poderá encerrar o assunto ou se recusar a continuar, mas não perceberá automaticamente qual conclusão o Detetive pretendia alcançar. O bônus exige uma contradição verdadeira; fabricar uma invalida o talento.", "source": "https://app.notion.com/p/3e4508f8aa6c8120b211f09c96d40e67" },
	{ "id": "detetive:disfarce-de-campo", "name": "Disfarce de Campo", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 5 e domínio do Kit de Disfarce.", "text": "## Pré-requisito\nDetetive nível 5 e domínio do Kit de Disfarce.\nAo preparar uma identidade adequada ao local investigado, o Detetive estabelece aparência, ocupação, motivo de presença e informações básicas coerentes.\nEnquanto agir dentro dessa cobertura, uma falha por até quatro pontos em Enganação gera desconfiança ou uma pergunta adicional, mas não revela imediatamente sua identidade verdadeira. Alterações impossíveis de sustentar, testemunhas que o reconheçam ou falhas graves quebram a cobertura normalmente.", "source": "https://app.notion.com/p/3e4508f8aa6c811aa0bfe29884ecf283" },
	{ "id": "detetive:caso-reaberto", "name": "Caso Reaberto", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 5 e Olho para Ausências.", "text": "## Pré-requisito\nDetetive nível 5 e Olho para Ausências.\nQuando uma nova evidência relevante permite revisitar uma cena já analisada, o Detetive poderá usar Reconstrução dos Fatos para fazer **duas perguntas**, em vez de uma.\nSe superar a CD por 10 ou mais, ainda fará somente duas perguntas. O benefício exige que a evidência realmente altere a compreensão do caso; reorganizar informações antigas não basta.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c811eb66dee8f30b3c5f9" },
	{ "id": "detetive:parceiro-de-confianca", "name": "Parceiro de Confiança", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 7.", "text": "## Pré-requisito\nDetetive nível 7.\nO Detetive conquista a colaboração permanente de um parceiro, assistente ou contato recorrente, criado em conjunto com o Mestre. Esse personagem pode ser um investigador auxiliar, jornalista, advogado, técnico, informante, agente, hacker ou alguém dotado de uma capacidade incomum compatível com a campanha.\nNa aquisição do talento, são definidos:\n- Identidade e relação com o Detetive;\n- Área de especialidade;\n- Recursos e contatos plausíveis;\n- Limites, riscos e interesses próprios.\nO parceiro é controlado pelo Mestre e poderá ajudar com pesquisas, observação, contatos, tarefas paralelas, obtenção de acesso ou uso de sua especialidade sempre que estiver disponível e a ajuda for possível.\nEle não produz evidências inexistentes, não resolve casos sozinho e poderá exigir tempo, recursos, proteção ou reciprocidade. A aquisição é única: perder ou romper definitivamente essa parceria não concede automaticamente um substituto.", "source": "https://app.notion.com/p/3e4508f8aa6c814cb7cac987c960169f" },
	{ "id": "detetive:armadilha-de-conhecimento", "name": "Armadilha de Conhecimento", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 7 e Contradição Explorada.", "text": "## Pré-requisito\nDetetive nível 7 e Contradição Explorada.\nDurante uma entrevista, o Detetive poderá mencionar deliberadamente um detalhe falso ou incompleto sobre o caso. Se o interlocutor corrigir, completar ou reagir a uma informação que não deveria conhecer, o Detetive reconhece essa revelação sem precisar de um teste adicional.\nO interlocutor não é obrigado a reagir, e o silêncio não prova inocência nem culpa. Uma armadilha mal formulada poderá revelar ao alvo o que o Detetive sabe.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c816ebd03ed54a2c8f6d6" },
	{ "id": "detetive:plano-de-captura", "name": "Plano de Captura", "kind": "class", "classId": "detetive", "prerequisite": "Detetive nível 7.", "text": "## Pré-requisito\nDetetive nível 7.\nDepois de estudar o local, os hábitos conhecidos do alvo e as rotas disponíveis por pelo menos trinta minutos, o Detetive poderá preparar um plano de abordagem ou detenção.\nEle escolhe até um número de participantes igual ao bônus de proficiência. Cada escolhido recebe **+2 no primeiro teste** que realizar para ocupar uma posição prevista, bloquear uma rota, seguir o alvo ou iniciar a perseguição.\nO benefício termina se o alvo agir de maneira incompatível com as informações usadas no plano. Ele não concede bônus em ataques ou batalhas Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c816eba15d1c5ee3f3007" },
	{ "id": "detetive:caso-encerrado", "name": "Ápice — Caso Encerrado", "kind": "apex", "classId": "detetive", "prerequisite": "Detetive nível 10 e Olho para Ausências.", "text": "## Pré-requisito\nDetetive nível 10 e Olho para Ausências.\nDepois de reunir ao menos cinco evidências independentes e reconstruir a sequência principal de um caso, o Detetive poderá identificar **o acontecimento ausente** que necessariamente conecta duas ou mais evidências incompatíveis ou aparentemente desconexas.\nO Mestre revela uma ação, passagem ou interferência que ocorreu entre os fatos conhecidos, mesmo que não tenha deixado uma prova direta preservada. A conclusão deverá explicar consequências realmente presentes na investigação, mas não precisa revelar quem realizou a ação, seu motivo ou sua localização atual.\nEsse recurso poderá ser utilizado uma vez por caso. Ele não encerra automaticamente a investigação: transforma uma lacuna invisível em uma nova linha concreta de apuração.", "source": "https://app.notion.com/p/3e4508f8aa6c81fa8848e66d6111f4c7" },
	{ "id": "detetive:operador-invisivel", "name": "Ápice — Operador Invisível", "kind": "apex", "classId": "detetive", "prerequisite": "Detetive nível 10 e Parceiro de Confiança.", "text": "## Pré-requisito\nDetetive nível 10 e Parceiro de Confiança.\nO parceiro do Detetive torna-se capaz de conduzir uma frente investigativa paralela enquanto o personagem trabalha em outro ponto do caso.\nO Detetive define um objetivo concreto e fornece as informações e recursos disponíveis. O Mestre controla o parceiro e resolve sua atuação de acordo com sua especialidade, riscos e circunstâncias. Ele poderá, por exemplo:\n- Vigiar um segundo local;\n- Entrevistar uma testemunha;\n- Pesquisar registros;\n- Conseguir acesso por seus próprios contatos;\n- Acompanhar um suspeito;\n- Preparar uma retirada ou rota segura.\nQuando as duas frentes voltarem a se encontrar, o parceiro entrega um resultado concreto: uma pista, registro, testemunho, acesso, oportunidade ou confirmação útil. Uma falha gera uma complicação real, mas não transforma o período inteiro em uma tentativa sem informação.\nO parceiro continua sendo um personagem do Mestre, possui interesses próprios e não poderá realizar algo impossível para suas capacidades.", "source": "https://app.notion.com/p/3e4508f8aa6c8174a3a4f96cd3a8bbde" },
	{ "id": "detetive:dupla-indissociavel", "name": "Ápice — Dupla Indissociável", "kind": "apex", "classId": "detetive", "prerequisite": "Detetive nível 10 e Voz do Parceiro.", "text": "## Pré-requisito\nDetetive nível 10 e Voz do Parceiro.\nO vínculo entre o Detetive e seu Parceiro Investigativo torna os dois uma verdadeira dupla protagonista. O Pokémon deixa de ser controlado pelo Mestre e passa a ser controlado pelo jogador, mantendo personalidade, conhecimentos, limitações e interesses construídos até então.\nEnquanto o Detetive e esse Pokémon estiverem investigando juntos e ambos puderem contribuir para a análise, o Detetive recebe em Intuição um bônus igual a:\n```plain text\nAtaque Especial base do parceiro ÷ 20\n```\nO resultado é arredondado para baixo. O bônus se aplica somente a testes de Intuição diretamente ligados à investigação conduzida pela dupla.\nEle não se aplica a batalhas, concursos, captura, iniciativa ou interações sem relação com o caso. Também não altera o Ataque Especial do Pokémon nem qualquer outra estatística.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c810d8066f6e5d3923e9c" },
	{ "id": "diplomata:negociador-comercial", "name": "Negociador Comercial", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Ao comprar itens disponíveis regularmente em uma loja, o Diplomata paga **5% menos** que o preço de venda apresentado pelo comerciante.\nO desconto representa relacionamento, negociação e conhecimento de mercado. Ele não obriga a loja a vender mercadorias bloqueadas ou indisponíveis.", "source": "https://app.notion.com/p/3e4508f8aa6c814a8c10dcdafad52558" },
	{ "id": "diplomata:vendedor-persuasivo", "name": "Vendedor Persuasivo", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Ao vender um item para uma loja que normalmente o compraria, o Diplomata recebe **10% a mais** sobre o valor de compra oferecido pelo comerciante.\nO talento não transforma objetos sem demanda em mercadorias nem remove limites de estoque, legalidade ou recursos da loja.", "source": "https://app.notion.com/p/3e4508f8aa6c815b8dbdcacba66169c0" },
	{ "id": "diplomata:lista-de-convidados", "name": "Lista de Convidados", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "O Diplomata paga **metade do valor de entrada** em clubes, exposições, camarotes, festas, restaurantes, hotéis, eventos ou outros ambientes sociais exclusivos que vendam acesso ao público.\nQuando a entrada depender de convite, reputação ou vestimenta, o talento permite descobrir a forma legítima mais simples de obtê-la, mas não concede acesso automático a áreas privadas ou protegidas.", "source": "https://app.notion.com/p/3e4508f8aa6c8105b9cfc1b5d6fb9e0e" },
	{ "id": "diplomata:carta-de-apresentacao", "name": "Carta de Apresentação", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Depois de estudar uma instituição e preparar uma apresentação formal, o Diplomata poderá solicitar uma audiência com alguém que possua autoridade compatível com o assunto.\nSe a instituição tiver qualquer motivo plausível para ouvi-lo, receberá uma reunião breve ou uma resposta oficial, ainda que precise aguardar, apresentar credenciais ou aceitar condições. O talento não obriga a autoridade a concordar ou revelar informações restritas.", "source": "https://app.notion.com/p/3e4508f8aa6c81799543fa5efad4edc4" },
	{ "id": "diplomata:conhecimento-de-jurisdicao", "name": "Conhecimento de Jurisdição", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Após dez minutos consultando avisos, documentos públicos ou uma pessoa local, o Diplomata reconhece as regras públicas mais importantes da jurisdição:\n- Itens controlados ou proibidos;\n- Autoridades responsáveis;\n- Documentos e licenças exigidos;\n- Condutas que geram multa, detenção ou expulsão;\n- Procedimentos básicos de denúncia, recurso e autorização.\nLeis secretas, corrupção e exceções ocultas ainda exigem investigação.", "source": "https://app.notion.com/p/3e4508f8aa6c81498613ddb201dec4dd" },
	{ "id": "diplomata:canal-oficial", "name": "Canal Oficial", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "O Diplomata sabe encaminhar mensagens por gabinetes, consulados, associações, ligas, organizações e autoridades reconhecidas.\nQuando existir um canal institucional ativo, uma mensagem sua chega ao setor ou representante correto sem ser perdida em procedimentos comuns. O tempo de entrega continua dependendo da distância, segurança e urgência, e o destinatário não é obrigado a responder.", "source": "https://app.notion.com/p/3e4508f8aa6c81edbe1ffab359c3a97a" },
	{ "id": "diplomata:etiqueta-cosmopolita", "name": "Etiqueta Cosmopolita", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Ao chegar a uma região, comunidade ou círculo social novo, o Diplomata precisa de apenas um minuto de observação ou uma orientação breve para utilizar Etiqueta e Protocolo.\nAlém disso, uma falha por até quatro pontos em um teste social causada por diferença cultural gera constrangimento ou atraso, mas não reduz a disposição do grupo. Falhas graves produzem consequências normais.", "source": "https://app.notion.com/p/3e4508f8aa6c81d19098d29ed6737bc8" },
	{ "id": "diplomata:anfitriao-economico", "name": "Anfitrião Econômico", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Ao organizar uma recepção, reunião formal, jantar, celebração ou encontro diplomático, o Diplomata reduz em **20%** o custo de local, serviço e preparação necessários para o evento.\nO benefício exige negociação prévia e fornecedores disponíveis. Ele não reduz o preço de presentes, subornos, itens permanentes adquiridos durante o evento ou danos causados pelos participantes.", "source": "https://app.notion.com/p/3e4508f8aa6c814a90dfd3dd5468b394" },
	{ "id": "diplomata:porta-voz-reconhecido", "name": "Porta-Voz Reconhecido", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Um grupo poderá declarar o Diplomata como seu representante durante uma negociação. Enquanto essa função for aceita pelas demais partes, ele poderá apresentar informações, propostas e concessões em nome dos aliados presentes.\nUma vez durante a negociação, um aliado poderá fornecer conhecimento ou evidência relevante, concedendo **+2 ao próximo teste social do Diplomata** relacionado diretamente à contribuição.\nMentir sobre a autoridade recebida ou aceitar termos sem permissão poderá gerar consequências normalmente.\nAumente também em 1 seu Carisma, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c81f6a23bea64ffd500f9" },
	{ "id": "diplomata:hospitalidade-reciproca", "name": "Hospitalidade Recíproca", "kind": "class", "classId": "diplomata", "prerequisite": "", "text": "Quando visita uma organização, comunidade ou autoridade com a qual tenha concluído pessoalmente um acordo favorável, o Diplomata poderá solicitar hospedagem e alimentação básicas para si por até três dias.\nA hospitalidade será gratuita quando houver recursos e segurança para oferecê-la. Acompanhantes, luxo, serviços especializados e permanências maiores poderão exigir pagamento ou reciprocidade.", "source": "https://app.notion.com/p/3e4508f8aa6c810ebb1fcca3b77129e1" },
	{ "id": "diplomata:barganha-refinada", "name": "Barganha Refinada", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 5, Negociador Comercial e Vendedor Persuasivo.", "text": "## Pré-requisito\nDiplomata nível 5, Negociador Comercial e Vendedor Persuasivo.\nOs benefícios econômicos do Diplomata melhoram para:\n- **10% de desconto** sobre o preço de venda das lojas;\n- **20% de acréscimo** sobre o valor normal de compra oferecido pelas lojas.\nEsses valores substituem, e não se acumulam com, Negociador Comercial e Vendedor Persuasivo. Todas as limitações econômicas da classe continuam válidas.", "source": "https://app.notion.com/p/3e4508f8aa6c810abbf4c5f1a2dedca5" },
	{ "id": "diplomata:nome-na-porta", "name": "Nome na Porta", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 5 e Lista de Convidados.", "text": "## Pré-requisito\nDiplomata nível 5 e Lista de Convidados.\nO Diplomata poderá obter **entrada gratuita para si** em ambientes sociais exclusivos que normalmente comercializem ingressos ou reservas, desde que reserve com antecedência e cumpra vestimenta e conduta exigidas.\nAcompanhantes ainda pagam metade do valor por Lista de Convidados. O talento não concede acesso a reuniões privadas, áreas de segurança, eventos secretos ou locais que rejeitem publicamente o Diplomata.", "source": "https://app.notion.com/p/3e4508f8aa6c813b8606e3d0e1f6424f" },
	{ "id": "diplomata:licenca-facilitada", "name": "Licença Facilitada", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 5 e Conhecimento de Jurisdição.", "text": "## Pré-requisito\nDiplomata nível 5 e Conhecimento de Jurisdição.\nAo solicitar uma licença civil ou comercial para a qual realmente cumpra os requisitos, o Diplomata reduz em **25% a taxa administrativa** e pela metade o tempo burocrático normal.\nO talento não concede licença para armas ou itens restritos sem cumprir suas exigências, não falsifica antecedentes e não supera uma proibição legal.", "source": "https://app.notion.com/p/3e4508f8aa6c81719138e8f18acd5aa5" },
	{ "id": "diplomata:favor-institucional", "name": "Favor Institucional", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 5.", "text": "## Pré-requisito\nDiplomata nível 5.\nQuando o Diplomata conclui uma mediação importante ou presta um serviço reconhecido a uma instituição, poderá registrar um Favor Institucional com ela, mediante aprovação do Mestre.\nEle poderá consumir o favor para obter uma ajuda proporcional, como:\n- Uma apresentação formal;\n- Consulta a um registro não secreto;\n- Uso temporário de uma instalação;\n- Prioridade em um procedimento;\n- Empréstimo de equipamento comum;\n- Transporte ou hospedagem compatíveis.\nO Diplomata mantém um número máximo de favores igual ao bônus de proficiência. Um favor não obriga a instituição a agir contra seus princípios, leis ou segurança.", "source": "https://app.notion.com/p/3e4508f8aa6c811e91a1d9325bf1bb5b" },
	{ "id": "diplomata:tregua-de-emergencia", "name": "Trégua de Emergência", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 7.", "text": "## Pré-requisito\nDiplomata nível 7.\nO Diplomata poderá utilizar Voz de Trégua logo após um confronto físico entre pessoas começar, desde que ninguém tenha morrido e ainda exista possibilidade real de diálogo.\nEm caso de sucesso, a violência é interrompida até o fim da proposta breve do Diplomata. Nenhuma parte é obrigada a aceitar a negociação, e qualquer nova agressão encerra a trégua.\nEsse talento não interrompe uma batalha Pokémon formal nem afeta ações, golpes ou estatísticas de Pokémon.", "source": "https://app.notion.com/p/3e4508f8aa6c81ac9b0df74ff1ccd44b" },
	{ "id": "diplomata:comitiva-respeitavel", "name": "Comitiva Respeitável", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 7 e Nome na Porta.", "text": "## Pré-requisito\nDiplomata nível 7 e Nome na Porta.\nQuando obtém entrada por Nome na Porta, o Diplomata poderá incluir gratuitamente um número de acompanhantes igual ao seu bônus de proficiência.\nTodos precisam cumprir as exigências públicas do local e permanecer sob responsabilidade do Diplomata. O benefício não supera lotação, convite nominal, segurança ou proibição específica contra um integrante.", "source": "https://app.notion.com/p/3e4508f8aa6c813e9957d13e330a69bc" },
	{ "id": "diplomata:reputacao-precedente", "name": "Reputação Precedente", "kind": "class", "classId": "diplomata", "prerequisite": "Diplomata nível 9 e dois Favores Institucionais registrados com organizações diferentes.", "text": "## Pré-requisito\nDiplomata nível 9 e dois Favores Institucionais registrados com organizações diferentes.\nEm ambientes formais onde sua identidade e atuação possam ser reconhecidas, a disposição inicial de autoridades, organizações e profissionais melhora em **um grau**, até o máximo de receptiva.\nO benefício não funciona com inimigos pessoais, instituições prejudicadas pelo Diplomata ou grupos sem qualquer acesso à sua reputação. Comportamento posterior poderá alterar a disposição normalmente.", "source": "https://app.notion.com/p/3e4508f8aa6c81a89ba3da7767c5a677" },
	{ "id": "diplomata:embaixador-do-mercado", "name": "Ápice — Embaixador do Mercado", "kind": "apex", "classId": "diplomata", "prerequisite": "Diplomata nível 10 e Barganha Refinada.", "text": "## Pré-requisito\nDiplomata nível 10 e Barganha Refinada.\nOs benefícios comerciais do Diplomata passam a ser:\n- **15% de desconto** sobre o preço de venda das lojas;\n- **30% de acréscimo** sobre o valor normal de compra oferecido pelas lojas.\nEsses valores substituem todos os talentos comerciais anteriores e continuam sujeitos às regras contra acumulação e revenda imediata. O ápice não libera itens bloqueados, controlados ou fora do estoque.", "source": "https://app.notion.com/p/3e4508f8aa6c81dbb9fcfea3c5c066bd" },
	{ "id": "diplomata:persona-grata", "name": "Ápice — Persona Grata", "kind": "apex", "classId": "diplomata", "prerequisite": "Diplomata nível 10 e Comitiva Respeitável.", "text": "## Pré-requisito\nDiplomata nível 10 e Comitiva Respeitável.\nO Diplomata e até um número de acompanhantes igual ao dobro de seu bônus de proficiência recebem gratuitamente o melhor acesso público normalmente comercializado por hotéis, clubes, restaurantes, exposições, camarotes e eventos sociais.\nQuando o acesso depender de convite, o Diplomata poderá conseguir uma apresentação legítima em até um dia, desde que alguém ligado ao evento tenha motivo plausível para recebê-lo.\nO ápice não invade áreas privadas, secretas ou de segurança e não impede expulsão causada pela conduta do grupo.", "source": "https://app.notion.com/p/3e4508f8aa6c815694f9e7a1145fcfd3" },
	{ "id": "diplomata:acordo-impossivel", "name": "Ápice — Acordo Impossível", "kind": "apex", "classId": "diplomata", "prerequisite": "Diplomata nível 10.", "text": "## Pré-requisito\nDiplomata nível 10.\nDepois de ouvir todas as partes de uma negociação por pelo menos dez minutos, o Diplomata poderá identificar uma solução que nenhuma delas havia considerado, mas que respeita as necessidades indispensáveis declaradas por todos.\nO Mestre revela uma concessão, troca, garantia, divisão de responsabilidades ou interesse compartilhado capaz de formar uma base realmente viável para o acordo. A solução poderá exigir recursos, tempo, risco ou compromissos importantes, mas não será impossível nem secretamente inaceitável para uma das partes com base no que foi apresentado.\nAo propor essa solução, o Diplomata realiza o teste final de Persuasão com **vantagem**.\nAcordo Impossível poderá ser utilizado uma vez por negociação importante. Ele não controla as partes, não força a assinatura e não cria uma solução quando seus objetivos forem verdadeiramente inconciliáveis.\n<empty-block/>", "source": "https://app.notion.com/p/3e4508f8aa6c818ab987f3ec60a5ab1b" },
	{ "id": "encantador:espelhamento-social", "name": "Espelhamento Social", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Depois de conversar com uma pessoa por pelo menos um minuto, o Encantador poderá ajustar ritmo, vocabulário, postura e formalidade ao estilo dela.\nRecebe **+2 no próximo teste de Persuasão ou Enganação** realizado para fazê-la se sentir compreendida, confortável ou socialmente alinhada.\nO bônus não se aplica a ameaças, ordens ou pedidos incompatíveis com os limites percebidos por Leitura Afetiva.", "source": "https://app.notion.com/p/3e4508f8aa6c814e9343cac93bc8f002" },
	{ "id": "encantador:saida-elegante", "name": "Saída Elegante", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "O Encantador sabe transformar uma retirada em parte natural da interação.\nFora de combate, ele poderá deixar uma conversa ou evento acompanhado por um número de aliados igual ao seu modificador de Carisma. Quem desejar impedir ou seguir imediatamente a saída deverá vencer um teste de Intuição contra a Persuasão do Encantador.\nEm caso de falha, a pessoa percebe a retirada apenas depois de um minuto ou quando algo chamar atenção para a ausência. O talento não supera portas trancadas, guardas com ordem de detenção, perseguição já iniciada ou flagrante de crime.", "source": "https://app.notion.com/p/3e4508f8aa6c816180c8d21dfc2282c9" },
	{ "id": "encantador:ouvido-para-rumores", "name": "Ouvido para Rumores", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Após circular por pelo menos uma hora em uma reunião, festa, bar, hotel ou outro ambiente social ativo, o Encantador descobre:\n- O rumor mais repetido no local;\n- Quem parece saber mais sobre ele;\n- Se o assunto é tratado como diversão, medo, escândalo ou preocupação.\nA informação poderá ser falsa ou incompleta como qualquer rumor, mas o Mestre deverá indicar corretamente sua circulação e origem aparente.", "source": "https://app.notion.com/p/3e4508f8aa6c8119837be9b10b6757e9" },
	{ "id": "encantador:presente-certeiro", "name": "Presente Certeiro", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Depois de observar ou conversar com alguém, o Encantador consegue identificar uma categoria de presente, gesto ou lembrança que a pessoa receberia de maneira positiva.\nQuando oferece algo coerente e proporcional à relação, a disposição da pessoa melhora em **um grau** durante a interação, até o máximo de receptiva.\nO benefício não compra perdão, intimidade ou consentimento e não funciona quando o presente for inadequado, manipulativo ou claramente usado como suborno.", "source": "https://app.notion.com/p/3e4508f8aa6c81c3a27cf97447316444" },
	{ "id": "encantador:pedido-inofensivo", "name": "Pedido Inofensivo", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Quando uma pessoa estiver receptiva ao Encantador, ele poderá pedir um favor pequeno que não envolva risco relevante, gasto significativo, quebra de confiança ou violação de dever.\nSe o pedido for claramente simples para aquela pessoa, ela o atende sem necessidade de teste. Exemplos incluem entregar uma mensagem, fornecer uma orientação, guardar um lugar ou apresentar alguém conhecido.\nA pessoa poderá explicar por que não consegue ajudar quando houver impedimento real.", "source": "https://app.notion.com/p/3e4508f8aa6c81cfad78f695c8ebd4f8" },
	{ "id": "encantador:visual-adequado", "name": "Visual Adequado", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Com acesso a uma vestimenta coerente e alguns minutos de preparação, o Encantador adapta aparência, acessórios e postura ao ambiente social.\nDurante a primeira cena no evento, instituição ou círculo, recebe **+2 em todos os testes sociais nos quais sua apresentação pessoal seja relevante**.\nO benefício não imita uniformes oficiais, credenciais, identidade específica ou autoridade inexistente e termina se a aparência se tornar inadequada às circunstâncias.", "source": "https://app.notion.com/p/3e4508f8aa6c81c28f59dd0fb97f4f5e" },
	{ "id": "encantador:confidente", "name": "Confidente", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Depois de manter uma conversa privada e genuína por pelo menos dez minutos, o Encantador poderá oferecer escuta sem julgamento.\nSe a outra pessoa aceitar se abrir, o Mestre revela uma preocupação, desejo, insegurança ou necessidade que ela esteja disposta a compartilhar. A informação deverá ser pessoalmente relevante.\nEnquanto preservar essa confiança, o Encantador poderá solicitar **um favor significativo, porém seguro e compatível com a relação**, como fornecer uma informação reservada de baixo risco, oferecer abrigo, criar uma apresentação ou interceder socialmente. Depois disso, a pessoa poderá esperar reciprocidade antes de ajudar novamente.\nTrair a confidência encerra esse benefício e poderá prejudicar gravemente a reputação do Encantador.", "source": "https://app.notion.com/p/3e4508f8aa6c814ca97ce4aea3b734e1" },
	{ "id": "encantador:apresentacao-perfeita", "name": "Apresentação Perfeita", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "O Encantador sabe aproximar duas pessoas por meio de um interesse, necessidade ou experiência compartilhada.\nDepois de uma apresentação conduzida por ele:\n- A disposição inicial entre ambas melhora em **um grau** durante a primeira conversa;\n- Cada pessoa recebe **+2 no primeiro teste social** realizado diretamente com a outra;\n- Ambas aceitam manter uma conversa breve antes de decidir se desejam continuar a relação.\nÉ necessário existir algum ponto real de compatibilidade. O talento não cria atração romântica, amizade permanente ou cooperação entre inimigos declarados.", "source": "https://app.notion.com/p/3e4508f8aa6c813cad47fd6f4b5b43fe" },
	{ "id": "encantador:rosto-memoravel", "name": "Rosto Memorável", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Depois de uma interação positiva com duração mínima de um minuto, a pessoa recorda claramente o Encantador e aceita reconhecê-lo como contato conhecido.\nEm encontros futuros com essa pessoa:\n- O Encantador recebe **+2 no primeiro teste social** da conversa;\n- Poderá solicitar uma conversa breve sem precisar de nova apresentação;\n- A disposição não diminui apenas pela passagem do tempo.\nInformações negativas, conflitos ou ações posteriores ainda poderão alterar ou encerrar a relação.", "source": "https://app.notion.com/p/3e4508f8aa6c8158910ee767b75fc23a" },
	{ "id": "encantador:centro-movel", "name": "Centro Móvel", "kind": "class", "classId": "encantador", "prerequisite": "", "text": "Enquanto sustenta Centro das Atenções, o Encantador poderá caminhar pelo ambiente e conduzir o foco social consigo sem encerrar o efeito.\nAliados discretos poderão aproveitar essa movimentação para atravessar uma área observada ou mudar de posição. A distração ainda não oculta agressões, ameaças, objetos grandes ou ações realizadas diretamente diante do observador.", "source": "https://app.notion.com/p/3e4508f8aa6c8136b37dd74ab33485ef" },
	{ "id": "encantador:disfarce-social", "name": "Disfarce Social", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 5, domínio do Kit de Disfarce.", "text": "## Pré-requisito\nEncantador nível 5, domínio do Kit de Disfarce.\nO Encantador poderá assumir a aparência geral e os hábitos de um tipo social, como funcionário, convidado, turista, artista, estudante ou profissional de determinada área.\nUma falha por até quatro pontos em Enganação gera dúvida ou uma pergunta adicional, mas não denuncia imediatamente o disfarce. O talento não permite imitar uma pessoa específica, falsificar credenciais ou demonstrar conhecimento profissional que o Encantador não possua.", "source": "https://app.notion.com/p/3e4508f8aa6c8137a08ac61a75ad3a8e" },
	{ "id": "encantador:sem-ressentimentos", "name": "Sem Ressentimentos", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 5.", "text": "## Pré-requisito\nEncantador nível 5.\nUma vez por interação social, quando falhar em um teste de **Persuasão ou Enganação**, o Encantador poderá reformular imediatamente sua abordagem e realizar uma segunda rolagem.\nEle deverá aceitar obrigatoriamente o resultado da segunda rolagem, mesmo que seja inferior ao primeiro. As consequências do teste somente são aplicadas após esse novo resultado.\nSem Ressentimentos não poderá ser utilizado novamente na mesma interação, ainda que o assunto ou interlocutor mude.", "source": "https://app.notion.com/p/3e4508f8aa6c81c9a60cdc342ad8fe11" },
	{ "id": "encantador:confianca-compartilhada", "name": "Confiança Compartilhada", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 5 e Confidente.", "text": "## Pré-requisito\nEncantador nível 5 e Confidente.\nDepois de aconselhar um aliado por pelo menos dez minutos sobre uma interação social específica, o Encantador poderá ajudá-lo a preparar palavras, postura e abordagem.\nO aliado recebe **+2 no primeiro teste de Persuasão, Enganação, Intimidação ou Atuação** realizado naquela interação. O bônus termina se ele abandonar completamente a abordagem preparada.", "source": "https://app.notion.com/p/3e4508f8aa6c81bd8e6ffed2958a89d3" },
	{ "id": "encantador:redirecionar-a-conversa", "name": "Redirecionar a Conversa", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 5.", "text": "## Pré-requisito\nEncantador nível 5.\nQuando uma conversa se voltar para um assunto inconveniente, o Encantador poderá realizar Persuasão ou Enganação contra a Intuição do interlocutor mais atento.\nEm caso de sucesso, o Encantador estabelece um novo assunto e o anterior não poderá ser retomado pelos presentes durante **dez minutos**, salvo se surgir nova evidência, perigo imediato ou alguém de fora introduzir novamente o tema.\nOs participantes não esquecem o assunto; apenas aceitam que insistir naquele momento seria socialmente inadequado ou improdutivo.", "source": "https://app.notion.com/p/3e4508f8aa6c815ab6fecc38eb858ebb" },
	{ "id": "encantador:reputacao-bem-cuidada", "name": "Reputação Bem Cuidada", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 7 e Rosto Memorável.", "text": "## Pré-requisito\nEncantador nível 7 e Rosto Memorável.\nApós dedicar um dia de campanha a conversas, aparições e correções públicas em uma comunidade, o Encantador poderá reduzir em um grau a hostilidade causada exclusivamente por boatos, mal-entendidos ou uma impressão social negativa.\nO talento não apaga provas, crimes, dívidas, traições ou danos realmente praticados pelo Encantador.", "source": "https://app.notion.com/p/3e4508f8aa6c816b93faefa2b9268820" },
	{ "id": "encantador:circulo-de-admiradores", "name": "Círculo de Admiradores", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 7 e Ouvido para Rumores.", "text": "## Pré-requisito\nEncantador nível 7 e Ouvido para Rumores.\nEm uma comunidade onde tenha participado de ao menos um evento social relevante, o Encantador poderá formar um pequeno círculo de admiradores, conhecidos e contatos casuais.\nAo retornar, poderá conseguir rapidamente um rumor local, uma apresentação, companhia para um evento ou ajuda social simples. O círculo não assume riscos, não fornece segredos protegidos e se desfaz caso seja explorado ou maltratado.", "source": "https://app.notion.com/p/3e4508f8aa6c81459095d5f6382afd5f" },
	{ "id": "encantador:presenca-desarmante", "name": "Presença Desarmante", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 7 e Sem Ressentimentos.", "text": "## Pré-requisito\nEncantador nível 7 e Sem Ressentimentos.\nQuando alguém o acusa, confronta ou recebe com hostilidade social, o Encantador garante uma oportunidade de até um minuto para apresentar sua versão, desde que não exista perigo imediato.\nDepois da explicação, realiza um teste de Persuasão com **vantagem**. Em caso de sucesso:\n- A disposição melhora em um grau;\n- A pessoa adia qualquer agressão ou expulsão imediata;\n- O Encantador recebe uma oportunidade concreta de apresentar prova, cumprir uma condição ou deixar o local pacificamente.\nO talento não impede prisão legítima, defesa contra ameaça real ou consequências de evidências incontestáveis.\nAumente também em 1 seu Carisma, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e4508f8aa6c816881bfe8d8a1f1c08b" },
	{ "id": "encantador:quimica-social", "name": "Química Social", "kind": "class", "classId": "encantador", "prerequisite": "Encantador nível 7 e Apresentação Perfeita.", "text": "## Pré-requisito\nEncantador nível 7 e Apresentação Perfeita.\nQuando o Encantador e um aliado com quem já tenha preparado uma abordagem atuam juntos em uma interação social, o bônus de ajuda concedido entre eles nunca será inferior a **+2**, desde que a contribuição utilize a mesma perícia do teste principal e seja realmente relevante.\nO talento não permite duas ajudas simultâneas nem transforma uma contribuição incoerente em ajuda válida.", "source": "https://app.notion.com/p/3e4508f8aa6c8141b486ecdc6211829c" },
	{ "id": "encantador:icone-social", "name": "Ápice — Ícone Social", "kind": "apex", "classId": "encantador", "prerequisite": "Encantador nível 10.", "text": "## Pré-requisito\nEncantador nível 10.\nQuando Primeira Impressão puder ser aplicada, a disposição inicial melhora em **dois graus**, em vez de um:\n```plain text\nHostil → Indiferente\nDesconfiada → Receptiva\nIndiferente → Receptiva\n```\nUma pessoa já determinada a atacar continua imune. O benefício dura somente durante a primeira interação e não cria confiança permanente, atração ou consentimento.", "source": "https://app.notion.com/p/3e4508f8aa6c8134be5ee52e5e25b554" },
	{ "id": "encantador:laco-verdadeiro", "name": "Ápice — Laço Verdadeiro", "kind": "apex", "classId": "encantador", "prerequisite": "Encantador nível 10 e Confiança Compartilhada.", "text": "## Pré-requisito\nEncantador nível 10 e Confiança Compartilhada.\nO Encantador poderá transformar uma relação desenvolvida de maneira genuína durante a campanha em um Laço Verdadeiro. A pessoa escolhida precisa aceitar voluntariamente essa proximidade e será definida em conjunto com o Mestre.\nEsse personagem, controlado pelo Mestre, torna-se profundamente leal ao vínculo e poderá oferecer abrigo, informação, defesa social, recursos razoáveis ou assumir riscos significativos pelo Encantador. Ele nunca será obrigado a agir contra seus valores centrais, destruir a própria vida ou aceitar abuso.\nA escolha é única e permanente. O fim do vínculo não permite selecionar outra pessoa automaticamente.", "source": "https://app.notion.com/p/3e4508f8aa6c81809be1f54b8a6950ee" },
	{ "id": "encantador:salao-na-palma-da-mao", "name": "Ápice — Salão na Palma da Mão", "kind": "apex", "classId": "encantador", "prerequisite": "Encantador nível 10 e Centro Móvel.", "text": "## Pré-requisito\nEncantador nível 10 e Centro Móvel.\nDepois de interagir por pelo menos dez minutos em um evento social, o Encantador poderá definir o tom predominante do ambiente como acolhedor, festivo, íntimo, solene ou curioso.\nEnquanto sustentar sua presença, pessoas sem forte motivo para resistir acompanham esse tom, e o Encantador e seus aliados recebem **+2 em testes sociais compatíveis com ele**. A mudança poderá facilitar aproximações e conversas, mas não transforma inimigos em amigos, não encobre perigo evidente e não obriga ninguém a permanecer no evento.\nSomente um tom poderá estar ativo por vez.", "source": "https://app.notion.com/p/3e4508f8aa6c814ba7b3c577d84055ff" },
	{ "id": "explorador:olho-do-tempo", "name": "Olho do Tempo", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Após observar o céu, vento, umidade e comportamento do ambiente por dez minutos, o Explorador conhece a tendência climática das próximas **12 horas** na região.\nO Mestre informa precipitação, mudança relevante de temperatura, vento forte e a aproximação de uma condição perigosa previsível. Fenômenos sobrenaturais ou produzidos artificialmente somente são percebidos quando deixam sinais naturais.", "source": "https://app.notion.com/p/3e5508f8aa6c819ea7bee7fb318bf534" },
	{ "id": "explorador:forrageador-eficiente", "name": "Forrageador Eficiente", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Ao passar duas horas procurando recursos em um ambiente que realmente possua água e alimento, o Explorador encontra o suficiente para sustentar um número de pessoas igual ao seu bônus de proficiência por um dia.\nO recurso encontrado é consumido normalmente e não se transforma em mercadoria armazenável. Ambientes estéreis, contaminados ou incompatíveis continuam sem fornecer alimento seguro.", "source": "https://app.notion.com/p/3e5508f8aa6c81b2aae8c8e09a70f3d6" },
	{ "id": "explorador:busca-direcionada-de-pokemon", "name": "Busca Direcionada de Pokémon", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "O Explorador poderá declarar uma espécie de Pokémon selvagem que deseja encontrar e passar uma hora procurando sinais em um ambiente compatível.\nSe a espécie existir naquela região e houver uma população selvagem acessível, ele realiza um teste de Sobrevivência contra uma CD definida pela raridade e pelas condições do local.\nEm caso de sucesso, encontra um rastro ativo e provoca um encontro em horda com a espécie durante a etapa seguinte da busca. Em caso de falha, perde o período de procura, mas não recebe uma conclusão falsa sobre a presença do Pokémon.\nO talento não localiza Pokémon individuais mantidos em segredo, cativeiro ou locais inacessíveis e não garante captura, disposição favorável, forma regional, sexo, natureza, habilidade ou condição shiny.", "source": "https://app.notion.com/p/3e5508f8aa6c811e82b7d8e339dbc7c8" },
	{ "id": "explorador:conhecimento-de-habitat", "name": "Conhecimento de Habitat", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5 e Busca Direcionada de Pokémon.", "text": "## Pré-requisito\nExplorador nível 5 e Busca Direcionada de Pokémon.\nDepois de encontrar sinais válidos de uma espécie, o Explorador poderá interpretar seu padrão de atividade antes de prosseguir. O Mestre informa:\n- O período em que costuma estar ativa;\n- Se aparece sozinha, em pares ou grupos;\n- O tipo de abrigo ou alimento que procura;\n- Um comportamento territorial ou defensivo relevante.\nAo ajustar a busca a essas informações, o Explorador realiza com **vantagem** o próximo teste de Busca Direcionada para essa espécie na mesma região.\nO talento descreve hábitos observáveis da população local e não revela atributos, golpes, IVs, natureza, habilidade ou outras informações individuais.", "source": "https://app.notion.com/p/3e5508f8aa6c817cb77adcf0bfa0f6f6" },
	{ "id": "explorador:trilha-apagada", "name": "Trilha Apagada", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "O Explorador poderá ocultar os sinais de passagem de um grupo com até um número de integrantes igual ao dobro de seu bônus de proficiência.\nO grupo se desloca em ritmo normal, mas perseguidores realizam com **desvantagem** testes para encontrar ou seguir seus rastros. O efeito termina quando o grupo corre, utiliza veículos que deixam marcas evidentes ou atravessa um local onde ocultar a passagem seja impossível.", "source": "https://app.notion.com/p/3e5508f8aa6c8128bc6ae2cfb4882008" },
	{ "id": "explorador:marcha-calculada", "name": "Marcha Calculada", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Ao liderar uma viagem com duração mínima de quatro horas, o Explorador poderá aumentar em **20%** a distância percorrida pelo grupo sem exigir marcha forçada.\nO benefício depende de pausas, distribuição de carga e ritmo definidos pelo Explorador. Ele não aumenta deslocamento em combate nem se aplica a veículos automáticos.", "source": "https://app.notion.com/p/3e5508f8aa6c81adb15dc62a22521ec9" },
	{ "id": "explorador:localizador-de-ruinas", "name": "Localizador de Ruínas", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "O Explorador poderá passar quatro horas examinando relevo, vegetação, cursos d’água, trilhas antigas e relatos locais em busca de construções abandonadas, ruínas, entradas soterradas ou outros vestígios de ocupação.\nSe existir uma estrutura desse tipo na região e houver sinais que possam ser encontrados, realiza um teste de Sobrevivência ou Investigação.\nEm caso de sucesso, descobre a direção aproximada, uma estimativa de distância e um indício da rota de acesso. Se superar a CD por 10 ou mais, também identifica o principal obstáculo ou perigo conhecido do caminho.\nO talento localiza vestígios; não revela conteúdo interno, história, armadilhas ou entradas sem qualquer manifestação externa.", "source": "https://app.notion.com/p/3e5508f8aa6c81f69239c2b7a0156c70" },
	{ "id": "explorador:localizador-de-desaparecidos", "name": "Localizador de Desaparecidos", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Ao procurar uma pessoa ou Pokémon desaparecido fora de combate, o Explorador recebe **+2 em Sobrevivência e Percepção**.\nNo primeiro sucesso da busca, além da pista normal, descobre uma destas informações à escolha:\n- O estado provável do desaparecido;\n- A distância aproximada;\n- O perigo mais imediato em sua rota;\n- O caminho mais seguro para alcançá-lo.\nA conclusão precisa ser sustentada pelos sinais disponíveis.", "source": "https://app.notion.com/p/3e5508f8aa6c81ea90f7f9a16893e982" },
	{ "id": "explorador:abrigo-de-emergencia", "name": "Abrigo de Emergência", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Com dez minutos de trabalho, um Kit de Sobrevivência e materiais disponíveis, o Explorador poderá construir abrigo temporário para até seis pessoas.\nDurante seis horas, o abrigo impede que clima comum cause condições ou exaustão e concede vantagem em Fortitude contra clima severo. Uma condição extrema ainda exige traje, equipamento ou retirada do local.", "source": "https://app.notion.com/p/3e5508f8aa6c817ab2bfff3e780fb0a9" },
	{ "id": "explorador:especialista-de-terreno", "name": "Especialista de Terreno", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Ao adquirir este talento, escolha um terreno: floresta, montanha, deserto, pântano, ambiente gelado, litoral, subterrâneo ou urbano em ruínas.\nNesse terreno, o Explorador recebe **+2 em Sobrevivência e Percepção** para orientação, perigos ambientais e localização de rotas.\nEste talento poderá ser adquirido novamente para outro terreno.", "source": "https://app.notion.com/p/3e5508f8aa6c816abae7c2e6b441bb47" },
	{ "id": "explorador:rota-de-retorno", "name": "Rota de Retorno", "kind": "class", "classId": "explorador", "prerequisite": "", "text": "Depois de percorrer e registrar uma rota por Cartografia de Campo, o Explorador poderá preparar um caminho de retorno com pontos de referência e locais de parada.\nO grupo poderá refazer essa rota sem testes de orientação e em **20% menos tempo**, desde que o terreno não tenha mudado significativamente. Esse benefício substitui, e não se acumula com, Marcha Calculada.", "source": "https://app.notion.com/p/3e5508f8aa6c8195a073d54ce81d781a" },
	{ "id": "explorador:linha-de-vida", "name": "Linha de Vida", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5.", "text": "## Pré-requisito\nExplorador nível 5.\nQuando um aliado visível falhar ao atravessar um obstáculo natural preparado pelo Explorador, ele poderá realizar imediatamente um teste de Atletismo ou Acrobacia contra a mesma CD.\nEm caso de sucesso, impede queda, arrastamento, separação ou outra consequência imediata e coloca o aliado em uma posição segura próxima. Em caso de falha, reduz a gravidade da consequência quando houver corda, ancoragem ou outro meio coerente.\nO talento não alcança alguém fora de seu alcance ou em situação fisicamente impossível de resgatar.", "source": "https://app.notion.com/p/3e5508f8aa6c817a9e65fbb979e92d32" },
	{ "id": "explorador:leitura-do-horizonte", "name": "Leitura do Horizonte", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5.", "text": "## Pré-requisito\nExplorador nível 5.\nDepois de observar uma região elevada ou aberta por dez minutos, o Explorador poderá localizar a direção aproximada de até dois elementos visíveis ou dedutíveis:\n- Água;\n- Abrigo natural;\n- Fumaça ou ocupação;\n- Travessia possível;\n- Área de vegetação incomum;\n- Mudança perigosa de terreno;\n- Rota de aproximação mais discreta.\nA leitura não atravessa barreiras completas nem revela estruturas subterrâneas sem sinais externos.\nAumente também em 1 sua Sabedoria ou Constituição, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c81ac9db5d9dad7b61344" },
	{ "id": "explorador:vigilia-perimetral", "name": "Vigília Perimetral", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5 e Acampamento Seguro.", "text": "## Pré-requisito\nExplorador nível 5 e Acampamento Seguro.\nAo preparar um acampamento, o Explorador poderá instalar sinais discretos, linhas de alerta e pontos de observação ao redor da área.\nA primeira criatura ou grupo que entrar no perímetro sem conhecer sua organização será detectado antes de alcançar os ocupantes, salvo se superar a Percepção passiva do Explorador com Furtividade.\nO sistema alerta o acampamento, mas não causa dano, impede aproximação nem substitui a vigília.", "source": "https://app.notion.com/p/3e5508f8aa6c81edb512cbee2ecddfe0" },
	{ "id": "explorador:rastros-improvaveis", "name": "Rastros Improváveis", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5.", "text": "## Pré-requisito\nExplorador nível 5.\nO Explorador não sofre desvantagem para seguir rastros antigos, parcialmente apagados, misturados ou afetados por chuva e vento moderados.\nQuando o rastro desaparecer completamente em um trecho, ele poderá identificar a direção mais provável de continuação e o próximo ponto onde sinais poderiam reaparecer. Teletransporte, voo prolongado ou ausência física total de passagem ainda interrompem a trilha.", "source": "https://app.notion.com/p/3e5508f8aa6c81bc96acfe720f73eba7" },
	{ "id": "explorador:ritmo-sustentado", "name": "Ritmo Sustentado", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 5 e Marcha Calculada.", "text": "## Pré-requisito\nExplorador nível 5 e Marcha Calculada.\nO grupo liderado pelo Explorador poderá manter viagem por até **duas horas adicionais** antes que o período seja considerado marcha forçada.\nO benefício não remove necessidade de descanso, água e alimento e não se acumula com outro uso de Ritmo Sustentado no mesmo dia de campanha.", "source": "https://app.notion.com/p/3e5508f8aa6c81029edef78cfe445e3c" },
	{ "id": "explorador:caminho-alternativo", "name": "Caminho Alternativo", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 7 e Leitura do Horizonte.", "text": "## Pré-requisito\nExplorador nível 7 e Leitura do Horizonte.\nDiante de uma rota bloqueada ou excessivamente perigosa, o Explorador poderá passar uma hora analisando a região para encontrar uma alternativa fisicamente possível.\nO Mestre apresenta uma rota que contorne o obstáculo e informa seu principal custo: tempo adicional, equipamento, exposição, esforço ou outro perigo. A rota nunca será totalmente gratuita, mas também não poderá conduzir secretamente a um impedimento idêntico sem sinais prévios.", "source": "https://app.notion.com/p/3e5508f8aa6c810bb1fdc34afcdf558a" },
	{ "id": "explorador:ponto-de-apoio", "name": "Ponto de Apoio", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 7 e Logística de Expedição.", "text": "## Pré-requisito\nExplorador nível 7 e Logística de Expedição.\nO Explorador poderá estabelecer um esconderijo de suprimentos em local selvagem após uma hora de trabalho. Ele registra a posição e protege o conteúdo contra clima e animais comuns.\nO ponto comporta até **20 espaços de itens**. Encontrá-lo sem o mapa ou instruções exige superar a CD de Sobrevivência do Explorador. O conteúdo continua existindo fisicamente e poderá ser roubado por alguém que localize o esconderijo.", "source": "https://app.notion.com/p/3e5508f8aa6c81e48e0bff009d628723" },
	{ "id": "explorador:guia-de-montaria", "name": "Guia de Montaria", "kind": "class", "classId": "explorador", "prerequisite": "Explorador nível 7 e treinamento em Montaria Pokémon.", "text": "## Pré-requisito\nExplorador nível 7 e treinamento em Montaria Pokémon.\nAo conduzir uma viagem com um Pokémon adequado à montaria ou tração e disposto a cooperar, o Explorador aumenta em **20%** a distância diária percorrida pelo grupo.\nO Pokémon precisa possuir força, porte e anatomia compatíveis com a carga. O talento não altera atributos, deslocamento em batalha, fadiga de combate ou capacidade de veículos.", "source": "https://app.notion.com/p/3e5508f8aa6c817d81e4c83088fc8a20" },
	{ "id": "explorador:senhor-das-rotas", "name": "Ápice — Senhor das Rotas", "kind": "apex", "classId": "explorador", "prerequisite": "Explorador nível 10.", "text": "## Pré-requisito\nExplorador nível 10.\nO Explorador não poderá se perder por meios naturais em uma região na qual consiga observar marcos, céu, relevo ou sinais ambientais.\nQuando lidera o grupo:\n- O tempo de viagem é reduzido em **25%**;\n- Terrenos naturais difíceis comuns não reduzem o deslocamento dos aliados;\n- Um erro de orientação nunca conduz o grupo a um perigo sem que o Explorador perceba sinais prévios.\nA redução substitui Marcha Calculada e Rota de Retorno. Labirintos sobrenaturais, teletransporte e alterações artificiais do espaço ainda poderão desorientá-lo.", "source": "https://app.notion.com/p/3e5508f8aa6c81e68905e01883bbcb2e" },
	{ "id": "explorador:rastro-inevitavel", "name": "Ápice — Rastro Inevitável", "kind": "apex", "classId": "explorador", "prerequisite": "Explorador nível 10 e Rastros Improváveis.", "text": "## Pré-requisito\nExplorador nível 10 e Rastros Improváveis.\nAo possuir qualquer vestígio autêntico de passagem, o Explorador poderá reconstruir a trilha mesmo através de superfícies que normalmente não preservariam pegadas.\nA cada trecho relevante, o Mestre deverá fornecer um sinal indireto verdadeiro, como vegetação alterada, deslocamento de animais, poeira, odores, testemunhos ou mudança no ambiente. O Explorador também descobre se o alvo mudou deliberadamente seu método de deslocamento.\nO ápice não rastreia teletransporte e não informa a localização atual sem que exista uma continuidade possível.", "source": "https://app.notion.com/p/3e5508f8aa6c8181b02acb07371f46c7" },
	{ "id": "explorador:instinto-de-descoberta", "name": "Ápice — Instinto de Descoberta", "kind": "apex", "classId": "explorador", "prerequisite": "Explorador nível 10, Busca Direcionada de Pokémon e Localizador de Ruínas.", "text": "## Pré-requisito\nExplorador nível 10, Busca Direcionada de Pokémon e Localizador de Ruínas.\nAo iniciar uma expedição, o Explorador poderá escolher uma espécie de Pokémon selvagem, uma ruína ou uma estrutura perdida que pretenda encontrar na região.\nDepois de oito horas de busca, se o objetivo existir, estiver fisicamente acessível e deixar qualquer sinal no ambiente, o Explorador encontra uma pista conclusiva e uma rota viável até ele sem precisar realizar o teste inicial de localização.\nPara uma espécie, a rota conduz a um encontro possível com sua população selvagem. Para uma estrutura, conduz a uma entrada ou ponto externo alcançável. Perigos, obstáculos, exploração interna e captura continuam sendo resolvidos normalmente.\nO ápice não cria o objetivo, não atravessa barreiras impossíveis e não localiza indivíduos deliberadamente ocultos sem vestígios.", "source": "https://app.notion.com/p/3e5508f8aa6c81f3af58c97e69637e33" },
	{ "id": "fotografo:fotografia-noturna", "name": "Fotografia Noturna", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Ao utilizar equipamento capaz de longa exposição ou amplificação adequada, o Fotógrafo não sofre desvantagem causada por baixa iluminação em testes de Ofício — Fotografia.\nA imagem exige que o objeto permaneça visível pelo equipamento e poderá registrar movimento com menor nitidez. Escuridão total ainda exige uma fonte de luz ou tecnologia apropriada.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81b4a74ae09b388eacfb" },
	{ "id": "fotografo:sequencia-de-acao", "name": "Sequência de Ação", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Ao utilizar Registro Oportuno, o Fotógrafo poderá produzir uma sequência curta de imagens em vez de uma única fotografia.\nA sequência registra posições sucessivas e permite determinar direção, ordem de movimentos e intervalo aproximado entre ações visíveis. Quem analisar o conjunto recebe **+2 em Investigação** para reconstruir aquele acontecimento.", "source": "https://app.notion.com/p/3e5508f8aa6c81b29fbec4958a7f5442" },
	{ "id": "fotografo:armadilha-fotografica", "name": "Armadilha Fotográfica", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Com dez minutos de preparação, o Fotógrafo poderá posicionar uma câmera para registrar automaticamente movimento em uma área delimitada.\nA câmera permanece ativa por até 24 horas ou até o limite de sua bateria e armazenamento. As imagens registram horário e tudo que atravesse o enquadramento dentro do alcance do equipamento.\nA câmera continua sendo um objeto físico e poderá ser percebida, danificada ou removida.", "source": "https://app.notion.com/p/3e5508f8aa6c81858517dd60678de97f" },
	{ "id": "fotografo:registro-de-especie", "name": "Registro de Espécie", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Quando produz uma fotografia clara que permita identificar uma espécie ou forma de Pokémon encontrada pessoalmente, o Fotógrafo poderá registrá-la como **vista em sua Pokédex**.\nA imagem precisa mostrar características suficientes para confirmação e representar um encontro real. Fotografias de terceiros, ilustrações, telas ou imagens de arquivo não concedem o registro.\nO talento não marca o Pokémon como capturado e não revela informações que a Pokédex ainda não deveria apresentar.", "source": "https://app.notion.com/p/3e5508f8aa6c815eafbdec9b9c55e8df" },
	{ "id": "fotografo:ampliacao-forense", "name": "Ampliação Forense", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Ao examinar uma fotografia de qualidade adequada durante dez minutos, o Fotógrafo poderá ampliar e tratar a imagem sem inventar informação.\nEle recebe **+2 em Investigação ou Percepção visual** para encontrar detalhes pequenos, reflexos, inscrições, marcas, placas, objetos parcialmente cobertos ou diferenças entre elementos registrados.\nO talento não recupera detalhes fora de foco, ocultos ou abaixo da resolução do equipamento.\nAumente também em 1 sua Inteligência ou Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c8152acfdeb1e6f1baf17" },
	{ "id": "fotografo:retrato-que-aproxima", "name": "Retrato que Aproxima", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Depois de produzir e entregar um retrato cuidadoso a uma pessoa disposta ou a um treinador junto de seu Pokémon, a disposição do retratado melhora em **um grau** durante a interação, até o máximo de receptiva.\nO benefício funciona apenas quando o retrato possui valor afetivo ou pessoal verdadeiro. Ele não compra perdão, confiança permanente ou consentimento.", "source": "https://app.notion.com/p/3e5508f8aa6c81bb82cbebfb830680c3" },
	{ "id": "fotografo:credencial-de-imprensa", "name": "Credencial de Imprensa", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Quando um evento, instituição ou acontecimento aceita cobertura pública, o Fotógrafo poderá solicitar entrada profissional para documentá-lo.\nEle recebe acesso gratuito às áreas destinadas à imprensa e uma oportunidade de registrar o evento sem comprar ingresso comum. O talento não concede entrada a setores privados, cenas isoladas, instalações secretas ou locais onde fotografar seja proibido.", "source": "https://app.notion.com/p/3e5508f8aa6c817bb923e9947b52a5a3" },
	{ "id": "fotografo:valor-documental", "name": "Valor Documental", "kind": "class", "classId": "fotografo", "prerequisite": "", "text": "Fotografias de eventos relevantes, espécies raras, descobertas, personalidades ou fenômenos poderão ser vendidas ou licenciadas como documentos profissionais.\nO Mestre define o valor conforme raridade, qualidade, exclusividade, interesse público e risco do registro. Uma mesma imagem somente poderá ser vendida com exclusividade uma vez; licenças posteriores possuem valor menor.\nImagens obtidas ilegalmente poderão gerar consequências e não encontram comprador legítimo automaticamente.", "source": "https://app.notion.com/p/3e5508f8aa6c81acb8b2c42ce7fa8bc5" },
	{ "id": "fotografo:comparacao-temporal", "name": "Comparação Temporal", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 5 e Ampliação Forense.", "text": "## Pré-requisito\nFotógrafo nível 5 e Ampliação Forense.\nAo comparar fotografias do mesmo local, pessoa, objeto ou Pokémon produzidas em momentos diferentes, o Fotógrafo poderá realizar Investigação para identificar alterações sutis.\nEm caso de sucesso, reconhece o que foi acrescentado, removido, deslocado, reparado, danificado ou deliberadamente disfarçado entre os registros. Se superar a CD por 10 ou mais, também determina a provável ordem das alterações visíveis.", "source": "https://app.notion.com/p/3e5508f8aa6c8170b302fc11385b10c8" },
	{ "id": "fotografo:rede-de-cameras", "name": "Rede de Câmeras", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 5 e Armadilha Fotográfica.", "text": "## Pré-requisito\nFotógrafo nível 5 e Armadilha Fotográfica.\nO Fotógrafo poderá manter simultaneamente um número de armadilhas fotográficas igual ao seu bônus de proficiência.\nAo recolher os equipamentos, identifica automaticamente quais registraram atividade relevante e em qual horário, sem precisar analisar manualmente todas as imagens. Cada câmera ainda precisa ser posicionada, alimentada e recuperada fisicamente.", "source": "https://app.notion.com/p/3e5508f8aa6c81378f95cfa95202bc7b" },
	{ "id": "fotografo:registro-comportamental", "name": "Registro Comportamental", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 5 e Registro de Espécie.", "text": "## Pré-requisito\nFotógrafo nível 5 e Registro de Espécie.\nDepois de fotografar uma espécie selvagem durante pelo menos dez minutos sem provocar confronto, o Fotógrafo poderá documentar um comportamento natural.\nO Mestre responde uma pergunta sustentada pelas imagens:\n- Do que ela está se alimentando?\n- O que está protegendo?\n- Qual sinal utiliza para alertar o grupo?\n- Em que período está mais ativa?\n- Como reage à presença de outras espécies?\n- Qual direção costuma seguir?\nO registro descreve aquela população e não revela estatísticas ou capacidades de combate.", "source": "https://app.notion.com/p/3e5508f8aa6c810ab289e04dcf8d9b8d" },
	{ "id": "fotografo:panorama-de-reconhecimento", "name": "Panorama de Reconhecimento", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 5.", "text": "## Pré-requisito\nFotógrafo nível 5.\nApós passar dez minutos produzindo um panorama de uma área, o Fotógrafo registra rotas visíveis, coberturas, entradas, saídas, elevações e obstáculos.\nQuem consultar o panorama recebe **+2 no primeiro teste de Investigação, Percepção ou Sobrevivência** relacionado à navegação ou análise visual daquele local.\nMudanças posteriores poderão tornar partes do registro obsoletas.", "source": "https://app.notion.com/p/3e5508f8aa6c8125ad2ed28d53c8171c" },
	{ "id": "fotografo:segundo-enquadramento", "name": "Segundo Enquadramento", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 5.", "text": "## Pré-requisito\nFotógrafo nível 5.\nUma vez por cena, ao falhar em um teste de Ofício — Fotografia, o Fotógrafo poderá ajustar imediatamente foco, exposição ou posição e realizar uma segunda rolagem.\nEle deverá aceitar obrigatoriamente o segundo resultado, mesmo que seja inferior. A nova tentativa somente será possível se o acontecimento ainda puder ser fotografado ou se Registro Oportuno tiver produzido uma sequência.", "source": "https://app.notion.com/p/3e5508f8aa6c81088a1de1719e02949d" },
	{ "id": "fotografo:fotojornalismo", "name": "Fotojornalismo", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 7 e Valor Documental.", "text": "## Pré-requisito\nFotógrafo nível 7 e Valor Documental.\nAo publicar um conjunto verdadeiro, verificável e contextualizado de imagens sobre um acontecimento relevante, o Fotógrafo poderá alterar em **um grau** a disposição pública de uma comunidade em relação ao assunto registrado.\nA mudança ocorre após tempo suficiente para a publicação circular. Autoridades poderão contestá-la, mas precisarão apresentar outra narrativa ou evidência; negar sem explicação não elimina seu efeito.\nImagens manipuladas ou apresentadas de forma enganosa anulam o talento e prejudicam a reputação do Fotógrafo.", "source": "https://app.notion.com/p/3e5508f8aa6c81bb80ddffce41372bca" },
	{ "id": "fotografo:cobertura-de-campo", "name": "Cobertura de Campo", "kind": "class", "classId": "fotografo", "prerequisite": "Fotógrafo nível 7.", "text": "## Pré-requisito\nFotógrafo nível 7.\nEnquanto documenta um desastre, perseguição, tempestade, desabamento ou outro acontecimento perigoso fora de combate, o Fotógrafo poderá continuar registrando sem sofrer desvantagem causada apenas por movimento, pressão ou instabilidade do ambiente.\nAlém disso, uma falha por até quatro pontos não danifica o equipamento. O talento não protege o personagem do perigo nem permite ignorar condições que tornem fotografar fisicamente impossível.\nAumente também em 1 sua Constituição, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c81f48f10d2efaba59d3b" },
	{ "id": "fotografo:instante-perfeito", "name": "Ápice — Instante Perfeito", "kind": "apex", "classId": "fotografo", "prerequisite": "Fotógrafo nível 10.", "text": "## Pré-requisito\nFotógrafo nível 10.\nUma vez por cena, quando qualquer acontecimento visual ocorrer dentro do alcance e capacidade de seu equipamento, o Fotógrafo poderá registrá-lo automaticamente sem teste, mesmo que dure apenas um instante.\nA imagem possui a melhor nitidez que o equipamento e as condições poderiam produzir. O ápice não permite fotografar algo fora do enquadramento possível, invisível, totalmente oculto ou rápido demais para o próprio equipamento captar.", "source": "https://app.notion.com/p/3e5508f8aa6c81e2bf13c5ae7e3d07b6" },
	{ "id": "fotografo:fotografo-de-lendas", "name": "Ápice — Fotógrafo de Lendas", "kind": "apex", "classId": "fotografo", "prerequisite": "Fotógrafo nível 10, Registro de Espécie e Valor Documental.", "text": "## Pré-requisito\nFotógrafo nível 10, Registro de Espécie e Valor Documental.\nQuando o Fotógrafo produz pessoalmente o primeiro registro claro de uma descoberta extraordinária da campanha, a imagem torna-se uma Fotografia Lendária.\nSão exemplos válidos:\n- Um Pokémon lendário ou mítico encontrado de verdade;\n- Uma forma de Pokémon ainda não documentada naquela campanha;\n- Um fenômeno natural ou Pokémon extremamente raro;\n- Uma descoberta histórica ou científica inédita;\n- Um acontecimento único de grande importância.\nCada descoberta distinta poderá gerar somente uma Fotografia Lendária. O registro concede os seguintes benefícios:\n- A espécie e a forma são registradas como vistas na Pokédex do Fotógrafo, quando aplicável;\n- A fotografia vale **cinco vezes** o valor que receberia por Valor Documental;\n- O Fotógrafo torna-se uma referência naquele assunto e recebe **+2 em testes sociais para conseguir audiência, acesso ou informações diretamente relacionadas à descoberta**.\nA fotografia precisa ser autêntica, identificável e registrar a descoberta em seu contexto real. Uma imagem encenada, copiada ou produzida por outra pessoa não recebe os benefícios.", "source": "https://app.notion.com/p/3e5508f8aa6c818c8393e0d074750f6d" },
	{ "id": "fotografo:imagem-que-move-multidoes", "name": "Ápice — Imagem que Move Multidões", "kind": "apex", "classId": "fotografo", "prerequisite": "Fotógrafo nível 10 e Fotojornalismo.", "text": "## Pré-requisito\nFotógrafo nível 10 e Fotojornalismo.\nQuando publica uma imagem autêntica que registra de maneira clara um acontecimento de grande importância pública, o Fotógrafo poderá transformá-la em símbolo daquele evento.\nA disposição pública poderá mudar em **dois graus**, e pelo menos uma autoridade, organização ou grupo diretamente afetado será obrigado a responder publicamente, investigar ou apresentar sua própria evidência.\nO ápice não determina qual será a resposta, não garante justiça e não funciona quando a imagem não demonstra o acontecimento alegado por conta própria.", "source": "https://app.notion.com/p/3e5508f8aa6c814294d1e2325084b4e0" },
	{ "id": "guarda-pokemon:interposicao-protetora", "name": "Interposição Protetora", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Quando uma pessoa adjacente for atingida por um ataque que o Guarda consiga perceber, ele poderá usar sua reação para se colocar entre ela e o agressor.\nO Guarda se desloca até 1,5 metro e se torna o alvo do ataque, recebendo o dano e os efeitos em seu lugar.\nPara realizar a interposição:\n- O Guarda deverá conseguir alcançar o espaço entre o atacante e o alvo.\n- Seu deslocamento não poderá estar completamente impedido.\n- O ataque deverá permitir uma intervenção física.\n- O Guarda deverá declarar a reação antes da aplicação do dano.\nA característica poderá proteger pessoas e Pokémon fora de uma batalha formal. Ela não poderá ser utilizada para alterar o alvo de golpes durante uma batalha entre Pokémon.\nComo utiliza uma reação, Interposição Protetora poderá ser empregada no máximo uma vez por rodada, mas não possui limite diário.\nAumente também em 1 sua Constituição, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e1508f8aa6c8030bf02f2a903bbe9be" },
	{ "id": "guarda-pokemon:patrulha-atenta", "name": "Patrulha Atenta", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "O Guarda recebe:\n```plain text\n+2 em testes de Percepção relacionados à segurança de uma área\n```\nO bônus poderá ser utilizado para:\n- Perceber invasores.\n- Identificar comportamento suspeito.\n- Encontrar uma entrada forçada.\n- Notar uma arma escondida de maneira inadequada.\n- Reconhecer sinais de luta.\n- Localizar pontos vulneráveis em uma área protegida.\n- Perceber alguém seguindo sua patrulha.\n- Encontrar objetos abandonados propositalmente.\nO benefício não se aplica a buscas sem relação com segurança, patrulha ou identificação de ameaças.\n<empty-block/>", "source": "https://app.notion.com/p/3e1508f8aa6c80b6928ce12e2324f193" },
	{ "id": "guarda-pokemon:voz-de-autoridade", "name": "Voz de Autoridade", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "O Guarda sabe emitir ordens breves, claras e difíceis de ignorar em situações de risco.\nQuando uma pessoa capaz de ouvi-lo estiver prestes a agir por pânico, desinformação ou indecisão, o Guarda poderá usar **Intimidação** ou **Persuasão** para dar uma instrução imediata, como parar, recuar, largar um objeto, procurar abrigo ou liberar uma passagem.\nEm caso de sucesso, a pessoa interrompe a ação precipitada e dispõe de tempo suficiente para compreender a ordem antes de decidir como agir. Se estiver genuinamente disposta a cooperar, seguirá a instrução durante a emergência.\nVoz de Autoridade não controla mentes, não obriga um inimigo decidido a se render e não concede autoridade legal onde ela não existe.", "source": "https://app.notion.com/p/3e5508f8aa6c81d4b946e0b6fbc6347e" },
	{ "id": "guarda-pokemon:contencao-nao-letal", "name": "Contenção Não Letal", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Ao causar dano a uma pessoa com uma arma não letal, arma corpo a corpo ou ataque desarmado, o Guarda poderá declarar que está empregando força de contenção.\nSe esse dano reduzir o alvo a 0 PV, ele ficará **inconsciente e estável**, sem sofrer um ferimento grave provocado pelo golpe final.\nAlém disso, o Guarda não sofre penalidade por tentar desarmar, derrubar ou imobilizar uma pessoa sem causar dano, desde que disponha de uma forma coerente de fazê-lo.\nEste talento não se aplica a Pokémon e não interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81a2854ee1ba0d171370" },
	{ "id": "guarda-pokemon:formacao-de-escudo", "name": "Formação de Escudo", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "domínio em Escudos.", "text": "**Pré-requisito:** domínio em Escudos.\nEnquanto estiver utilizando um escudo, o Guarda poderá oferecer cobertura a uma pessoa adjacente. Contra ataques e perigos físicos que atravessem a direção protegida, essa pessoa recebe o mesmo bônus de Defesa concedido pelo escudo.\nComo reação, o Guarda poderá manter a formação ao se deslocar até 1,5 metro junto da pessoa protegida, desde que ambos terminem adjacentes.\nA proteção termina se o Guarda ficar incapacitado, perder o escudo ou deixar de conseguir se posicionar entre a ameaça e a pessoa. O talento não altera a Defesa de Pokémon participantes de uma batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c810a9c1ad466813c5f39" },
	{ "id": "guarda-pokemon:controle-de-multidao", "name": "Controle de Multidão", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "O Guarda consegue organizar civis durante tumultos, acidentes e evacuações.\nCom uma ação e instruções audíveis, ele poderá coordenar um grupo de até **5 × seu bônus de proficiência** pessoas dispostas a cooperar. Até o fim da cena, esse grupo:\n- Não entra em pânico por simples aglomeração, gritos ou movimento desordenado.\n- Consegue atravessar uma rota indicada sem se dispersar.\n- Evita bloquear saídas e áreas de atendimento.\n- Reconhece rapidamente os pontos de reunião indicados pelo Guarda.\nQuando for necessário um teste coletivo para evacuar ou manter a ordem, o Guarda realiza um único teste apropriado pelo grupo. Pessoas hostis ou que não compreendam as instruções não são afetadas.", "source": "https://app.notion.com/p/3e5508f8aa6c8104871dd0b83bec72f4" },
	{ "id": "guarda-pokemon:perimetro-seguro", "name": "Perímetro Seguro", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Após dez minutos examinando uma área e utilizando materiais disponíveis, o Guarda poderá estabelecer um perímetro de segurança.\nEle define acessos, pontos cegos, rotas de saída e sinais simples de violação. Enquanto permanecer válido:\n- Invasores não conseguem entrar sem deixar indícios, salvo por meios extraordinários.\n- O Guarda reconhece imediatamente qual acesso foi violado ao encontrar o perímetro.\n- Pessoas designadas recebem **+2 em Percepção** para vigiar os pontos indicados.\n- Uma evacuação iniciada dentro do perímetro já possui uma rota segura definida.\nO perímetro cobre uma construção pequena, acampamento ou área equivalente. Mudanças relevantes no terreno exigem nova preparação.", "source": "https://app.notion.com/p/3e5508f8aa6c813eb639f0c884457129" },
	{ "id": "guarda-pokemon:perseguicao-oficial", "name": "Perseguição Oficial", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Quando persegue uma pessoa, veículo ou montaria que esteja fugindo, o Guarda recebe **+2 em Atletismo ou Pilotagem** para manter a perseguição.\nUma vez por rodada, quando o perseguido cria um obstáculo comum — derruba objetos, fecha uma passagem, atravessa uma multidão ou muda bruscamente de direção — o Guarda poderá superar esse obstáculo sem perder distância caso seja bem-sucedido no teste correspondente.\nO benefício termina se o Guarda perder completamente a trilha ou interromper voluntariamente a perseguição. Não se aplica a uma perseguição entre Pokémon durante uma batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c81548de8f7fd64d88c9b" },
	{ "id": "guarda-pokemon:procedimento-de-abordagem", "name": "Procedimento de Abordagem", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Ao observar uma pessoa por pelo menos uma rodada antes de se aproximar, o Guarda poderá identificar uma destas informações:\n- Se as mãos dela escondem ou preparam um objeto.\n- Qual é a rota de fuga mais provável.\n- Qual pessoa ou objeto parece receber sua maior atenção.\n- Se ela está procurando uma oportunidade para atacar ou fugir.\n- Qual posição permite abordá-la sem bloquear a saída de civis.\nDurante a abordagem, o primeiro teste do Guarda para ordenar que a pessoa pare, mostre as mãos ou se afaste de um perigo recebe **+2**.\nO talento não revela pensamentos, culpa ou mentiras; ele interpreta postura e circunstâncias observáveis.", "source": "https://app.notion.com/p/3e5508f8aa6c81fca676cc15aeb0e851" },
	{ "id": "guarda-pokemon:reconhecimento-de-especie", "name": "Reconhecimento de Espécie", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "O Guarda foi treinado para reconhecer Pokémon durante patrulhas e ocorrências.\nAo examinar uma aparição, imagem, vocalização, pegada, pelo, pena, escama ou marca recente, poderá realizar **Natureza Pokémon**, **Conhecimento: Pokémon** ou outra perícia coerente para identificar:\n- A espécie e, quando perceptível, a forma.\n- A quantidade aproximada de indivíduos.\n- O porte e a fase geral de desenvolvimento.\n- Se os sinais pertencem a um Pokémon selvagem ou habituado a pessoas.\n- Se existe indício visível de ferimento, exaustão ou agitação.\nUma falha nunca fornece uma identificação falsa: apenas deixa a informação inconclusiva. Formas desconhecidas, disfarces e vestígios insuficientes ainda podem impedir a identificação.\nAumente também em 1 sua Sabedoria, respeitando o limite de atributos do sistema.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81efbf08f27f43f5d51a" },
	{ "id": "guarda-pokemon:leitura-de-ocorrencia-pokemon", "name": "Leitura de Ocorrência Pokémon", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "Reconhecimento de Espécie.", "text": "**Pré-requisito:** Reconhecimento de Espécie.\nReconhecimento de Espécie identifica o Pokémon e interpreta vestígios isolados. Leitura de Ocorrência Pokémon permite reconstruir **a sequência formada por vários vestígios**.\nDepois de examinar por pelo menos dez minutos uma área em que tenha ocorrido um incidente envolvendo Pokémon, o Guarda realiza um teste apropriado, normalmente **Investigação**, **Natureza Pokémon** ou **Conhecimento: Pokémon**.\nEm caso de sucesso, o Mestre descreve a ordem geral dos acontecimentos comprovada pelos sinais existentes. O Guarda também poderá fazer uma pergunta:\n- Onde o incidente provavelmente começou?\n- Quantos momentos distintos formaram a ocorrência?\n- Qual participante chegou ou saiu primeiro?\n- Em que ponto o comportamento do Pokémon mudou?\n- Houve perseguição, emboscada, contenção ou tentativa de fuga?\n- Alguma pessoa parece ter conduzido, atraído ou coagido o Pokémon?\n- Qual vestígio não combina com a sequência predominante?\nSe superar a CD por 10 ou mais, poderá fazer duas perguntas.\nO talento não identifica automaticamente culpados, não revela intenções e não cria informações ausentes. Ele diferencia-se de um teste comum porque organiza evidências dispersas em uma cronologia confiável, desde que a área ainda conserve sinais suficientes.\nA mesma ocorrência só poderá ser reconstruída novamente quando surgirem evidências novas.", "source": "https://app.notion.com/p/3e5508f8aa6c8194bbd1ecbe3f8e215e" },
	{ "id": "guarda-pokemon:rede-de-cadastros", "name": "Rede de Cadastros", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "Os guardas que participam de uma força de segurança local normalmente conseguem solicitar consultas aos cadastros públicos e policiais daquela jurisdição. Este talento representa uma rede profissional mais ampla e um histórico de cooperação que facilita esse acesso, mesmo fora da unidade em que o personagem trabalha.\nQuando existirem registros compatíveis, o Guarda poderá solicitar informações sobre:\n- Registro e proprietário de um Pokémon.\n- Poké Bolas vinculadas a uma ocorrência.\n- Pokémon declarados perdidos, roubados ou apreendidos.\n- Licenças de transporte, criação ou manejo.\n- Histórico oficial de transferências.\n- Ocorrências anteriores associadas ao registro consultado.\nO acesso **não é automático nem gratuito**. O Guarda ainda precisa identificar-se, justificar a consulta e respeitar sigilo, jurisdição e disponibilidade do sistema.\nNos testes necessários para obter autorização, localizar o setor responsável ou convencer um contato profissional a realizar a consulta, o Guarda recebe:\n**+2 em Persuasão ou Investigação**\nAlém disso, pedidos que normalmente levariam vários dias são respondidos no menor prazo plausível para a instituição. Registros sigilosos, apagados, estrangeiros ou protegidos por investigação exigem autorização superior e podem continuar indisponíveis.", "source": "https://app.notion.com/p/3e5508f8aa6c81cc9b71c2c6f865ba5d" },
	{ "id": "guarda-pokemon:busca-por-pokemon-desaparecido", "name": "Busca por Pokémon Desaparecido", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "Reconhecimento de Espécie.", "text": "**Pré-requisito:** Reconhecimento de Espécie.\nDepois de receber uma descrição confiável ou examinar um vestígio do Pokémon procurado, o Guarda recebe **+2 em Investigação ou Sobrevivência** para localizá-lo.\nNo primeiro sucesso de cada etapa da busca, ele também descobre uma informação útil: direção seguida, intervalo aproximado desde a passagem, condição aparente, presença de acompanhantes ou risco imediato na rota.\nO bônus vale tanto para Pokémon selvagens deslocados quanto para Pokémon perdidos ou roubados, mas exige uma pista real ligada ao indivíduo ou à espécie.", "source": "https://app.notion.com/p/3e5508f8aa6c81289e86db6513af7186" },
	{ "id": "guarda-pokemon:unidade-de-resgate-pokemon", "name": "Unidade de Resgate Pokémon", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "Reconhecimento de Espécie e nível 5 de Guarda Pokémon.", "text": "**Pré-requisitos:** Reconhecimento de Espécie e nível 5 de Guarda Pokémon.\nO Guarda sabe retirar Pokémon feridos, presos ou assustados de locais perigosos sem agravar sua condição. Quando dispõe de equipamento apropriado, ele poderá:\n- Improvisar uma contenção adequada ao porte e à anatomia identificados.\n- Transportar um Pokémon incapacitado sem causar dano adicional.\n- Retirá-lo de escombros, água, fogo ou armadilhas com segurança.\n- Manter distância e rotas de fuga adequadas para evitar uma reação defensiva.\n- Coordenar auxiliares que não possuam treinamento específico.\nUma falha por até 4 pontos não agrava o ferimento nem provoca uma reação do Pokémon; o resgate apenas não avança. Falhas graves produzem consequências normais. O talento não recupera PV e não funciona durante batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c8140998ef7971731fb7f" },
	{ "id": "guarda-pokemon:patrulheiro-de-reserva", "name": "Patrulheiro de Reserva", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "", "text": "O Guarda é treinado para fiscalizar reservas, parques, rotas rurais e áreas de preservação.\nEle recebe **+2 em Percepção ou Sobrevivência** para encontrar armadilhas ilegais, sinais de caça ou captura clandestina, invasões, incêndios recentes, contaminação, destruição de habitat e circulação em áreas restritas.\nAo encontrar um desses sinais, o Guarda também consegue estimar se ocorreu nas últimas horas, no último dia ou há mais tempo, desde que o ambiente não tenha apagado completamente os vestígios.", "source": "https://app.notion.com/p/3e5508f8aa6c8170bb02e14a38531288" },
	{ "id": "guarda-pokemon:desarme-de-armadilhas-de-caca", "name": "Desarme de Armadilhas de Caça", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "Patrulheiro de Reserva.", "text": "**Pré-requisito:** Patrulheiro de Reserva.\nO Guarda poderá utilizar **Sobrevivência** ou **Ladinagem** para desarmar armadilhas destinadas a capturar, ferir ou conter pessoas e Pokémon.\nSe falhar por até 4 pontos:\n- A armadilha não é acionada.\n- Nenhuma criatura é ferida.\n- O mecanismo não é destruído.\n- O desarme não é concluído.\n- Uma nova tentativa exige ferramenta, ajuda ou abordagem diferente.\nDepois de desarmá-la, o Guarda poderá preservar o mecanismo como evidência ou remontá-lo de forma inofensiva para identificar quem retorna ao local.", "source": "https://app.notion.com/p/3e5508f8aa6c818197c8fa5ec6dc3b97" },
	{ "id": "guarda-pokemon:rastreador-de-infratores", "name": "Rastreador de Infratores", "kind": "class", "classId": "guarda-pokemon", "prerequisite": "Patrulheiro de Reserva e nível 5 de Guarda Pokémon.", "text": "**Pré-requisitos:** Patrulheiro de Reserva e nível 5 de Guarda Pokémon.\nAo encontrar vestígios de caça, captura clandestina, invasão ou dano ambiental, o Guarda consegue separar a trilha dos infratores das marcas deixadas por Pokémon e visitantes comuns.\nEle recebe **+2 em Sobrevivência** para seguir os responsáveis e não perde automaticamente a trilha quando ela cruza uma estrada, curso d’água raso ou área frequentada. Nesses locais, um novo teste ainda poderá ser exigido.\nAo superar a CD por 10 ou mais, também identifica um detalhe do grupo: quantidade aproximada, meio de transporte, carga pesada, presença de Pokémon acompanhando ou direção provável do destino.", "source": "https://app.notion.com/p/3e5508f8aa6c816b9e4ede53735406f7" },
	{ "id": "guarda-pokemon:muralha-humana", "name": "Ápice — Muralha Humana", "kind": "apex", "classId": "guarda-pokemon", "prerequisite": "nível 10 de Guarda Pokémon.", "text": "**Pré-requisito:** nível 10 de Guarda Pokémon.\nQuando pessoas em uma área de até 6 metros forem ameaçadas por um ataque, desabamento, explosão, disparos ou outro perigo físico perceptível, o Guarda poderá usar sua reação para assumir o controle da proteção imediata.\nEle se desloca até seu deslocamento, posiciona proteções disponíveis e escolhe até **seu bônus de proficiência** pessoas. Até o início do próximo turno do Guarda:\n- Os escolhidos recebem cobertura contra a ameaça indicada.\n- Podem deslocar-se para abrigo sem provocar reações do agressor.\n- Uma pessoa que seria reduzida a 0 PV permanece com 1 PV.\nDepois de utilizado, o Guarda precisa concluir um descanso curto ou longo antes de empregar Muralha Humana novamente.\nO ápice protege pessoas e Pokémon fora de batalhas formais, mas nunca altera ataques, alvos ou dano em uma batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c811ea789f0532f03b9cd" },
	{ "id": "guarda-pokemon:guardiao-da-reserva", "name": "Ápice — Guardião da Reserva", "kind": "apex", "classId": "guarda-pokemon", "prerequisite": "nível 10 de Guarda Pokémon, Patrulheiro de Reserva e Rastreador de Infratores.", "text": "**Pré-requisitos:** nível 10 de Guarda Pokémon, Patrulheiro de Reserva e Rastreador de Infratores.\nAo patrulhar uma região natural por pelo menos uma hora, o Guarda compreende o estado geral daquela área. O Mestre informa se existe algum evento relevante recente ou em andamento, como:\n- Captura ou caça clandestina.\n- Incêndio, contaminação ou destruição de habitat.\n- Pokémon feridos, deslocados ou presos.\n- Invasão de uma área protegida.\n- Armadilhas ou acampamentos ilegais.\n- Alteração anormal na circulação das espécies.\nSe houver uma ocorrência, o Guarda descobre a direção geral e o caminho mais seguro até seus sinais. Evidências intencionalmente ocultadas ainda exigem testes, mas não podem tornar o acontecimento totalmente indetectável enquanto deixarem efeitos reais no ambiente.", "source": "https://app.notion.com/p/3e5508f8aa6c81a0bc51e60c55b19944" },
	{ "id": "guarda-pokemon:comandante-de-operacao", "name": "Ápice — Comandante de Operação", "kind": "apex", "classId": "guarda-pokemon", "prerequisite": "nível 10 de Guarda Pokémon e Controle de Multidão ou Perímetro Seguro.", "text": "**Pré-requisitos:** nível 10 de Guarda Pokémon e Controle de Multidão ou Perímetro Seguro.\nAo assumir a coordenação de uma busca, evacuação, resgate, defesa de local ou contenção humana, o Guarda define até três objetivos claros e distribui funções entre os participantes.\nEnquanto todos puderem receber suas instruções:\n- Cada participante recebe **+2** no primeiro teste diretamente ligado à função recebida.\n- Uma falha por até 4 pontos não provoca uma consequência em cadeia sobre os demais grupos; apenas aquela tarefa deixa de avançar.\n- O Guarda sabe imediatamente quando um dos objetivos foi concluído, abandonado ou comprometido, desde que exista algum meio de comunicação.\n- Civis cooperativos podem ser organizados sem atrapalhar equipes treinadas.\nUma operação permanece ativa até o fim da cena ou até seus objetivos deixarem de ser possíveis. O ápice não concede ações extras e não modifica o desempenho de Pokémon em batalha.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c818780e1e75442d3af9e" },
	{ "id": "ladino:analise-de-seguranca", "name": "Análise de Segurança", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino poderá utilizar Ladinagem no lugar de Investigação para examinar sistemas físicos de segurança.\nIsso inclui:\n- Fechaduras.\n- Armadilhas.\n- Cofres.\n- Alarmes.\n- Passagens ocultas acionadas por mecanismos.\n- Portas reforçadas.\n- Janelas protegidas.\n- Dispositivos de contenção.\n- Sinais de adulteração em mecanismos.\nEm caso de sucesso, poderá descobrir como o sistema funciona, como foi manipulado ou qual parte representa seu ponto mais vulnerável.\nAnálise de Segurança não desativa o mecanismo. Depois de examiná-lo, ainda será necessário realizar o teste apropriado para manipulá-lo.\nSistemas digitais continuam exigindo Tecnologia, salvo quando possuírem componentes físicos que possam ser examinados separadamente.", "source": "https://app.notion.com/p/3e1508f8aa6c8013b0bcf90bbbba3cad" },
	{ "id": "ladino:batedor-de-carteiras", "name": "Batedor de Carteiras", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Quando utiliza **Ladinagem** para retirar discretamente um objeto pequeno que uma pessoa carrega, o Ladino poderá observar o alvo por uma rodada e escolher uma vantagem:\n- Realizar a tentativa sem penalidade mesmo que o objeto esteja preso por um fecho simples.\n- Substituir o objeto por outro de peso e formato semelhantes.\n- Manter o objeto escondido em sua mão ou roupa imediatamente após retirá-lo.\nSe for bem-sucedido por 10 ou mais acima da CD, a ausência do objeto só poderá ser percebida quando o alvo tentar utilizá-lo ou conferir seus pertences.\nO talento não permite retirar objetos firmemente segurados, vestidos ou grandes demais para serem ocultados.", "source": "https://app.notion.com/p/3e5508f8aa6c81568b50f30da78789d6" },
	{ "id": "ladino:olho-para-o-premio", "name": "Olho para o Prêmio", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Depois de observar uma sala, pessoa ou exposição por pelo menos um minuto, o Ladino poderá identificar qual objeto visível provavelmente possui maior valor monetário ou importância para a segurança do local.\nEle também reconhece:\n- Qual objeto recebe vigilância incomum.\n- Qual peça parece ser uma réplica ou isca.\n- Qual pertence é consultado com maior frequência.\n- Qual item poderá ser removido sem alterar imediatamente a aparência do conjunto.\nOlho para o Prêmio não revela propriedades ocultas ou mágicas, nem determina um preço exato. Quando houver uma tentativa deliberada de enganá-lo, o Mestre poderá exigir **Investigação** ou **Intuição**.", "source": "https://app.notion.com/p/3e5508f8aa6c813fad1bf548b7d2de0c" },
	{ "id": "ladino:maos-vazias", "name": "Mãos Vazias", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Quando for revistado, o Ladino poderá esconder em seu corpo um objeto de tamanho Minúsculo e até 0,5 kg.\nQuem realiza a revista deverá superar um teste de Percepção ou Investigação contra:\n**CD = 8 + bônus de proficiência + modificador de Destreza do Ladino**\nO Ladino escolhe onde o objeto está oculto ao preparar o esconderijo. Uma revista que remova roupas, utilize equipamento especializado ou conheça previamente o objeto recebe vantagem.\nO talento não esconde armas ou objetos cuja forma torne o esconderijo fisicamente impossível.", "source": "https://app.notion.com/p/3e5508f8aa6c818c9086d99160995a84" },
	{ "id": "ladino:compartimento-clandestino", "name": "Compartimento Clandestino", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino poderá gastar uma hora e uma carga do Kit de Ladinagem para criar um compartimento oculto em uma bag, móvel ou veículo.\nO compartimento comporta até **1 espaço de itens** e não aumenta a capacidade normal do recipiente. Encontrá-lo exige Investigação contra:\n**CD = 8 + bônus de proficiência + modificador de Inteligência do Ladino**\nO compartimento poderá ser aberto sem ferramentas por quem conhecer seu mecanismo. Danificar ou desmontar completamente o objeto revela o esconderijo sem teste.\nCada recipiente só poderá possuir um Compartimento Clandestino criado por este talento.", "source": "https://app.notion.com/p/3e5508f8aa6c81e689c6eeeee46be37e" },
	{ "id": "ladino:rota-de-fuga", "name": "Rota de Fuga", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Depois de passar pelo menos dez minutos em uma construção, rua ou área delimitada, o Ladino poderá memorizar uma rota de saída.\nEnquanto a rota permanecer acessível:\n- Ele sempre sabe a direção geral da saída escolhida.\n- Recebe **+2 em testes para escapar de perseguidores** nesse local.\n- Não fica perdido por fumaça, escuridão ou confusão comum.\n- No primeiro obstáculo inesperado da fuga, poderá identificar imediatamente uma alternativa plausível.\nO benefício termina quando alterações relevantes bloquearem a rota ou quando o Ladino deixar a região.", "source": "https://app.notion.com/p/3e5508f8aa6c813c8488cf850144c29a" },
	{ "id": "ladino:sombra-persistente", "name": "Sombra Persistente", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Quando segue discretamente uma pessoa fora de combate, o Ladino poderá alternar entre cobertura, multidões e caminhos paralelos sem perder o alvo apenas por deixá-lo fora de vista durante alguns instantes.\nEle recebe **+2 em Furtividade** para acompanhar o alvo sem ser percebido. Em um sucesso, também aprende uma informação relacionada ao percurso: destino provável, rotina aparente, ponto de encontro, desvio incomum ou presença de outro perseguidor.\nO talento não permite atravessar áreas abertas sem cobertura nem reencontrar alguém cuja trilha tenha sido completamente perdida.\nAumente também em 1 sua Destreza, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c812b9d0fc633a2a0a278" },
	{ "id": "ladino:contato-clandestino", "name": "Contato Clandestino", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino possui um contato recorrente ligado a um meio clandestino escolhido com o Mestre, como contrabando, falsificação, segurança privada, informação, transporte discreto ou mercado ilegal.\nQuando estiver em uma comunidade onde essa rede possa atuar, o Ladino poderá localizar um intermediário em algumas horas. O contato poderá:\n- Indicar quem negocia determinado produto ou serviço.\n- Avaliar se uma proposta parece uma armadilha.\n- Transmitir uma mensagem sem revelar diretamente o remetente.\n- Apresentar uma oportunidade de trabalho clandestino.\n- Informar o preço e a disponibilidade de algo ilegal ou controlado.\nO contato não trabalha gratuitamente, não garante estoque e não arrisca a própria vida sem uma razão. O Mestre controla sua personalidade, interesses e informações.", "source": "https://app.notion.com/p/3e5508f8aa6c81f2a5aed475dc257932" },
	{ "id": "ladino:mercado-paralelo", "name": "Mercado Paralelo", "kind": "class", "classId": "ladino", "prerequisite": "Contato Clandestino.", "text": "**Pré-requisito:** Contato Clandestino.\nO Ladino consegue procurar compradores e vendedores fora do comércio regular. Quando um item não estiver disponível nas lojas locais, ele poderá solicitar ao contato que procure uma oferta clandestina em outras cidades, regiões ou redes de distribuição.\nA busca poderá encontrar:\n- Itens legais que não são vendidos naquela localidade.\n- Equipamentos raros ou especializados.\n- Itens controlados ou restritos.\n- Mercadorias cuja venda pública esteja temporariamente bloqueada.\nO Mestre define o prazo conforme distância, raridade e dificuldade de transporte. Encontrar uma oferta não obriga o Ladino a aceitá-la.\n**Mercado Paralelo não concede desconto.** O vendedor poderá cobrar o preço normal, acrescentar transporte, exigir pagamento antecipado, pedir um favor ou aumentar o valor devido ao risco e à escassez.\nProdutos únicos, inexistentes, proibidos de circular ou indisponíveis em toda a região continuam inalcançáveis. A procedência também poderá ser duvidosa, e o talento não torna a compra legal, segura ou anônima.", "source": "https://app.notion.com/p/3e5508f8aa6c819f9323daa7ed68d869" },
	{ "id": "ladino:armadilheiro", "name": "Armadilheiro", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino poderá construir armadilhas simples utilizando um Kit de Ladinagem. Cada armadilha exige **dez minutos**, **uma carga do kit** e materiais comuns compatíveis com o local.\nEle poderá manter um número de armadilhas ativas igual ao seu **bônus de proficiência**. Criar outra desmonta a mais antiga sem recuperar a carga.\n### Regras gerais\n- **CD para perceber:** 8 + bônus de proficiência + modificador de Inteligência.\n- **CD para desarmar:** igual à CD para perceber.\n- **CD de resistência:** 8 + bônus de proficiência + modificador de Inteligência.\n- Perceber utiliza Percepção ou Investigação.\n- Desarmar utiliza Ladinagem.\n- Quem conhece a posição da armadilha poderá atravessá-la sem acioná-la.\n- Uma criatura só sofre o efeito se possuir tamanho e anatomia compatíveis.\n- As armadilhas não podem ser montadas durante uma batalha.\n### Modelos iniciais\n**Alarme:** cobre uma passagem de até 3 metros. Quando acionado, produz um som audível a 30 metros ou outro sinal simples escolhido na montagem. Não causa dano.\n**Tropeço:** cobre uma linha de até 3 metros. O alvo realiza Reflexos. Em uma falha, fica **Caído**. Não causa dano.\n**Laço:** ocupa um espaço de 1,5 metro. O alvo realiza Reflexos. Em uma falha, fica **Imobilizado** até gastar uma ação e superar a CD com Atletismo ou até alguém desarmar o mecanismo.\n**Impacto:** ocupa um espaço de 1,5 metro. O alvo realiza Reflexos, sofrendo **1d6 + modificador de Inteligência de dano físico** em uma falha, ou metade em um sucesso.\nO dano de Impacto aumenta para **2d6 no nível 5** e **3d6 no nível 9** de Ladino. Uma armadilha de Impacto nunca poderá utilizar venenos, explosivos ou munições sem um talento ou regra que autorize esses componentes.\nUma armadilha desarmada poderá ser desmontada em um minuto, mas a carga utilizada não é recuperada.", "source": "https://app.notion.com/p/3e5508f8aa6c817789f3fe0b61d3ec2b" },
	{ "id": "ladino:instalacao-veloz", "name": "Instalação Veloz", "kind": "class", "classId": "ladino", "prerequisite": "Armadilheiro e nível 5 de Ladino.", "text": "**Pré-requisitos:** Armadilheiro e nível 5 de Ladino.\nO Ladino passa a construir uma armadilha conhecida em **uma ação completa**, desde que já esteja com o Kit de Ladinagem em mãos e o espaço escolhido esteja ao seu alcance.\nUma armadilha instalada dessa forma possui **−2 em suas CDs** e permanece visível para qualquer criatura que a observe diretamente. O custo de uma carga e o limite de armadilhas ativas permanecem normais.\nInstalação Veloz permite reagir a uma perseguição ou preparar uma contenção imediata, mas não poderá ser utilizada no turno de uma batalha Pokémon nem afetar Pokémon que estejam participando dela.", "source": "https://app.notion.com/p/3e5508f8aa6c8141b6c7c39d41c8e0c3" },
	{ "id": "ladino:mecanismo-oculto", "name": "Mecanismo Oculto", "kind": "class", "classId": "ladino", "prerequisite": "Armadilheiro.", "text": "**Pré-requisito:** Armadilheiro.\nQuando termina de construir uma armadilha, o Ladino poderá gastar mais dez minutos camuflando seu mecanismo.\nA CD para **perceber** a armadilha aumenta em **+2**, mas as CDs para desarmá-la e resistir a seus efeitos não mudam.\nAlém disso, uma criatura que falhar por até 4 pontos ao procurar a armadilha não percebe que existe algo suspeito. Uma falha maior ainda poderá revelar sinais indiretos, a critério do Mestre.\nA camuflagem precisa combinar com o ambiente; mudanças como chuva intensa, movimentação de móveis ou remoção da cobertura poderão eliminar o bônus.", "source": "https://app.notion.com/p/3e5508f8aa6c8136ab75d7167a6ef39f" },
	{ "id": "ladino:armadilhas-de-contencao-pokemon", "name": "Armadilhas de Contenção Pokémon", "kind": "class", "classId": "ladino", "prerequisite": "Armadilheiro.", "text": "**Pré-requisito:** Armadilheiro.\nO Ladino aprende a adaptar suas armadilhas à anatomia, aos sentidos e ao comportamento de Pokémon. Essa preparação é usada em resgates, proteção de áreas, captura de invasores, contenção de Pokémon agressivos e retirada segura de criaturas de locais perigosos.\nAntes da montagem, ele escolhe uma espécie que conheça ou um grupo coerente de Pokémon com anatomia semelhante. Em caso de dúvida, realiza **Conhecimento: Pokémon** ou **Natureza Pokémon** para compreender o alvo.\nPreparar a adaptação acrescenta dez minutos ao tempo normal e não consome uma carga adicional. Contra os Pokémon escolhidos:\n- A CD para perceber a armadilha aumenta em **+2**, pois odores, posição e aparência são ajustados aos sentidos da espécie.\n- A CD para resistir ou escapar aumenta em **+2**, pois o mecanismo considera porte, força, membros e forma de locomoção.\n- A armadilha nunca causa um ferimento grave por acidente.\n- O modelo Impacto causa dano não letal e não poderá reduzir o Pokémon abaixo de **1 PV**.\nAlém dos modelos comuns de Armadilheiro, o Ladino poderá construir:\n### Cercado de Contenção\nOcupa uma área de 1,5 metro e utiliza duas cargas do Kit de Ladinagem. Quando acionado, o Pokémon realiza Reflexos. Em uma falha, barreiras, rede ou estrutura apropriada fecham a área e o deixam **Contido**.\nO Pokémon poderá gastar uma ação para tentar escapar com Atletismo contra a CD da armadilha. Ataques ou capacidades naturais coerentes também poderão romper a estrutura, conforme o material utilizado.\nUma criatura contida continua consciente e poderá reagir defensivamente. O talento não a domestica, não a torna capturada e não permite transportá-la sem equipamento adequado.\nArmadilhas de Contenção Pokémon **não podem ser instaladas ou ativadas como ação durante uma batalha Pokémon**. Elas não alteram chance de captura, atributos, golpes, precisão, dano, fuga ou qualquer outra regra de combate.", "source": "https://app.notion.com/p/3e5508f8aa6c81fcb038ecf3a63035f8" },
	{ "id": "ladino:armadilha-combinada", "name": "Armadilha Combinada", "kind": "class", "classId": "ladino", "prerequisite": "Armadilheiro e nível 7 de Ladino.", "text": "**Pré-requisitos:** Armadilheiro e nível 7 de Ladino.\nO Ladino poderá gastar **duas cargas do Kit de Ladinagem** e vinte minutos para combinar dois modelos de armadilha conhecidos no mesmo mecanismo.\nQuando acionada, a vítima realiza uma única resistência contra a CD normal:\n- Em uma falha, sofre os dois efeitos.\n- Em um sucesso, evita efeitos que seriam completamente negados e sofre metade do dano de Impacto, se houver.\nA armadilha combinada conta como **duas armadilhas ativas** para o limite do Ladino. Dois mecanismos de dano não podem ser combinados entre si.", "source": "https://app.notion.com/p/3e5508f8aa6c81fb9953f7dde0723bde" },
	{ "id": "ladino:desarme-reversivel", "name": "Desarme Reversível", "kind": "class", "classId": "ladino", "prerequisite": "Armadilheiro.", "text": "**Pré-requisito:** Armadilheiro.\nQuando desarma com sucesso uma armadilha que possua componentes reutilizáveis, o Ladino poderá preservar seu mecanismo.\nDepois de dez minutos de trabalho, escolhe um benefício:\n- Recuperar materiais equivalentes a **uma carga do Kit de Ladinagem**, sem ultrapassar a capacidade máxima do kit.\n- Remontar a armadilha no mesmo local sob seu controle, utilizando as CDs originais ou as próprias, escolhendo as menores.\n- Transformar o mecanismo em uma evidência segura e transportável.\nExplosivos consumidos, substâncias químicas, componentes destruídos e mecanismos incompatíveis não podem ser recuperados.", "source": "https://app.notion.com/p/3e5508f8aa6c81c9802fec18cfb7f1cb" },
	{ "id": "ladino:sabotagem-discreta", "name": "Sabotagem Discreta", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino poderá utilizar Ladinagem para provocar uma falha futura em um mecanismo, veículo, fechadura, alarme ou equipamento simples, em vez de quebrá-lo imediatamente.\nEle define um gatilho plausível, como a próxima ativação, alguns minutos de uso ou determinada peça ser movimentada. Até o gatilho ocorrer, uma inspeção casual não revela a sabotagem.\nA falha produz apenas um efeito que o próprio mecanismo poderia sofrer: travar, desligar, soltar uma peça, emitir ruído, perder alimentação ou impedir uma abertura.\nSabotagem Discreta não cria explosões, não transforma objetos em armas e não afeta sistemas cuja complexidade exija Tecnologia ou outro conhecimento específico.", "source": "https://app.notion.com/p/3e5508f8aa6c81d28c89e21887af02bf" },
	{ "id": "ladino:sem-deixar-rastros", "name": "Sem Deixar Rastros", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Depois de agir em uma área, o Ladino poderá gastar dez minutos removendo sinais de sua presença.\nEle elimina pegadas comuns, resíduos de ferramentas, objetos deslocados e indícios superficiais de entrada. Testes para descobrir que alguém esteve no local recebem **−2**.\nSe o Ladino superar uma CD definida pelo Mestre com Furtividade ou Ladinagem, também poderá fazer parecer que a entrada aconteceu por outro acesso plausível.\nO talento não remove registros digitais, testemunhas, danos estruturais, impressões já coletadas ou evidências que o Ladino desconheça.", "source": "https://app.notion.com/p/3e5508f8aa6c8137a1cdfda46ff111b3" },
	{ "id": "ladino:entrada-alternativa", "name": "Entrada Alternativa", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "O Ladino é especializado em alcançar acessos que não foram feitos para circulação comum.\nQuando procura uma maneira de entrar em uma construção ou área protegida sem utilizar a entrada principal, ele poderá identificar uma alternativa plausível, caso exista:\n- Janela, claraboia ou varanda alcançável.\n- Passagem de manutenção.\n- Cobertura ou construção adjacente.\n- Canalização ou estrutura escalável.\n- Abertura temporária causada pela rotina do local.\nDurante a aproximação por essa rota, o Ladino recebe **+2 no primeiro teste de Acrobacia ou Atletismo** necessário para alcançá-la.\nO talento não cria uma passagem inexistente, não atravessa barreiras seladas e não garante que o acesso encontrado esteja destrancado ou sem vigilância.", "source": "https://app.notion.com/p/3e5508f8aa6c81e1a596d687b73bddd4" },
	{ "id": "ladino:ferramenta-improvisada", "name": "Ferramenta Improvisada", "kind": "class", "classId": "ladino", "prerequisite": "", "text": "Quando não possui acesso ao Kit de Ladinagem, o Ladino poderá adaptar um objeto comum para realizar uma única tentativa de abrir uma fechadura, desarmar uma armadilha ou manipular um mecanismo simples.\nA ferramenta improvisada elimina a impossibilidade de realizar o teste, mas o Ladino sofre **−2** e o objeto é inutilizado depois da tentativa, independentemente do resultado.\nEm caso de falha por até 4 pontos, **Manipulação Cuidadosa** ainda se aplica normalmente.\nFerramenta Improvisada não funciona em mecanismos eletrônicos, fechaduras de alta segurança ou dispositivos que exijam peças especializadas.", "source": "https://app.notion.com/p/3e5508f8aa6c813d8671c58341dc0995" },
	{ "id": "ladino:ladrao-fantasma", "name": "Ápice — Ladrão Fantasma", "kind": "apex", "classId": "ladino", "prerequisite": "nível 10 de Ladino.", "text": "**Pré-requisito:** nível 10 de Ladino.\nAntes de iniciar uma infiltração, o Ladino escolhe um objeto transportável que tenha visto ou cuja localização conheça. Enquanto buscar exclusivamente esse objeto, recebe:\n- Vantagem no primeiro teste de Furtividade de cada nova área.\n- A capacidade de reconhecer imediatamente uma réplica destinada a substituir o alvo.\n- Nenhuma penalidade por carregar o objeto durante a fuga, salvo se ele for Volumoso.\nSe retirar o objeto e sair do local sem ser identificado, investigadores comuns não conseguem determinar automaticamente quando ou por qual acesso ocorreu o furto; precisarão reconstruir a ação por evidências reais.\nO ápice não torna o Ladino invisível, não atravessa barreiras e não apaga testemunhas ou registros.", "source": "https://app.notion.com/p/3e5508f8aa6c81ee917af7917406f2c8" },
	{ "id": "ladino:labirinto-de-gatilhos", "name": "Ápice — Labirinto de Gatilhos", "kind": "apex", "classId": "ladino", "prerequisite": "nível 10 de Ladino, Armadilheiro e Armadilha Combinada.", "text": "**Pré-requisitos:** nível 10 de Ladino, Armadilheiro e Armadilha Combinada.\nCom uma hora de trabalho e **quatro cargas do Kit de Ladinagem**, o Ladino poderá preparar uma zona de até 12 metros com uma rede de armadilhas interligadas.\nA rede possui quatro pontos de acionamento distribuídos na área, mas conta como apenas quatro armadilhas para o limite do Ladino. Cada ponto utiliza um modelo conhecido e as CDs normais do personagem.\nQuando um ponto for acionado, o Ladino escolhe na montagem se:\n- Apenas aquele mecanismo é ativado.\n- Um segundo ponto previamente conectado também é ativado.\n- O acionamento apenas revela silenciosamente a posição do intruso ao Ladino.\nDescobrir um ponto não revela automaticamente os demais. Desarmar o mecanismo central com Ladinagem contra a CD do Ladino desativa toda a rede.\nA rede não poderá ser montada durante combate e não interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81b39b9ae6b23643b15d" },
	{ "id": "ladino:ninguem-esteve-aqui", "name": "Ápice — Ninguém Esteve Aqui", "kind": "apex", "classId": "ladino", "prerequisite": "nível 10 de Ladino e Sem Deixar Rastros.", "text": "**Pré-requisitos:** nível 10 de Ladino e Sem Deixar Rastros.\nDepois de concluir uma infiltração e dispor de trinta minutos para limpar o percurso, o Ladino poderá restaurar fechaduras, objetos e acessos manipulados ao estado aparente anterior.\nUma investigação sem evidência externa não consegue provar automaticamente que houve invasão. Para descobrir a passagem, será necessário superar a CD de Ladinagem do personagem em cada área relevante:\n**CD = 8 + bônus de proficiência + modificador de Destreza**\nMesmo em caso de sucesso, o investigador descobre apenas que ocorreu uma adulteração e qual trecho foi afetado; identidade, objetivo e método completo ainda dependem de outras evidências.\nO ápice não apaga gravações, memórias, ferimentos, itens ausentes evidentes ou consequências que não possam ser fisicamente restauradas.", "source": "https://app.notion.com/p/3e5508f8aa6c81b08501d6f72219e44f" },
	{ "id": "medico:antidoto-de-emergencia", "name": "Antídoto de Emergência", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico poderá gastar dez minutos, uma carga do Kit Médico e materiais compatíveis para reduzir a progressão de uma toxina ou doença em uma pessoa.\nDepois de identificar o agente ou seus sintomas, realiza Medicina contra a CD do efeito. Em caso de sucesso:\n- O paciente realiza imediatamente uma nova resistência contra o veneno ou doença.\n- Essa resistência recebe **+2**.\n- Um sucesso interrompe a progressão, mas não remove consequências já sofridas.\nAntídoto de Emergência não funciona contra agentes sem tratamento plausível, não substitui o medicamento específico e só poderá conceder uma resistência adicional por exposição.", "source": "https://app.notion.com/p/3e5508f8aa6c818d8ad3f543c4eb11fe" },
	{ "id": "medico:cirurgiao", "name": "Cirurgião", "kind": "class", "classId": "medico", "prerequisite": "nível 5 de Médico.", "text": "**Pré-requisito:** nível 5 de Médico.\nQuando realiza uma cirurgia em instalação adequada, o Médico recebe **+2 em Medicina** e poderá tratar ferimentos que normalmente exigiriam encaminhamento para outro profissional.\nEm caso de sucesso, escolha um benefício adicional:\n- Reduzir pela metade o tempo de recuperação imposto pelo procedimento.\n- Evitar uma sequela permanente que ainda pudesse ser prevenida.\n- Preservar um membro ou órgão que seria perdido.\n- Remover completamente um corpo estranho sem causar dano adicional.\nCada cirurgia exige equipamentos, equipe auxiliar e tempo compatíveis. Cirurgião não permite restaurar estruturas já destruídas nem realizar procedimentos impossíveis para a medicina disponível.\nAumente também em 1 sua Inteligência ou Sabedoria, respeitando o limite de atributos do sistema.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c8108898acb31e5198be0" },
	{ "id": "medico:protocolo-preventivo", "name": "Protocolo Preventivo", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Durante um descanso curto ou longo, o Médico poderá orientar até **1 + seu modificador de Sabedoria** pessoas sobre riscos específicos que consiga prever, como calor, frio, altitude, contaminação, esforço prolongado ou doença regional.\nAté o próximo descanso, cada participante recebe **+2 na primeira resistência de Fortitude** contra o risco escolhido.\nO protocolo exige suprimentos e comportamento preventivo compatíveis. Ele deixa de beneficiar quem ignorar deliberadamente as instruções, abandonar o equipamento necessário ou se expuser de forma extrema.", "source": "https://app.notion.com/p/3e5508f8aa6c81218c80d7cc65619f5d" },
	{ "id": "medico:gestao-de-suprimentos-medicos", "name": "Gestão de Suprimentos Médicos", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico sabe organizar materiais, separar doses e utilizar componentes sem desperdiçar o restante do kit.\nQuando conclui com sucesso um procedimento que consumiria mais de uma carga do Kit Médico, reduz o custo em **uma carga**, até o mínimo de uma.\nEm procedimentos que consomem apenas uma carga, uma vez por descanso longo o Médico poderá rolar `1d6` após o uso. Com resultado 5 ou 6, a carga não é consumida.\nEsse benefício não se aplica a cargas perdidas por falha, itens médicos completos, medicamentos raros ou materiais cujo preço seja contado separadamente.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c816489ebe450e43a83a5" },
	{ "id": "medico:medicina-integrada", "name": "Medicina Integrada", "kind": "class", "classId": "medico", "prerequisite": "treinamento em Medicina Pokémon.", "text": "**Pré-requisito:** treinamento em Medicina Pokémon.\nO Médico compreende semelhanças e diferenças relevantes entre anatomia humana e Pokémon.\nQuando uma característica ou talento da classe exigir Medicina para uma pessoa, ele poderá aplicá-lo a um Pokémon utilizando **Medicina Pokémon**, desde que possua equipamento adequado à espécie.\nIsso inclui controle de sangramento, antídoto, atendimento de campo, diagnóstico e cirurgia plausível. Benefícios que tratem emoções humanas, usem medicamentos incompatíveis ou dependam de fisiologia exclusivamente humana continuam indisponíveis.\nTodo atendimento ocorre fora de batalha e nunca altera atributos, golpes, PP, EV, IV, precisão ou qualquer cálculo competitivo do Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c818da3c2db53bcd6f151" },
	{ "id": "medico:atendimento-agil", "name": "Atendimento Ágil", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico reduz de dez minutos para **um minuto** o tempo necessário para utilizar Atendimento Emergencial.\nTodos os demais requisitos permanecem: uma carga do Kit Médico, acesso ao paciente, local minimamente seguro e ausência de interrupção.\nSe a situação ainda for um confronto ativo, o Médico primeiro precisa retirar o paciente da área imediata de ameaça. Atendimento Ágil não transforma o procedimento em uma ação de combate.", "source": "https://app.notion.com/p/3e5508f8aa6c81348be2c72641f5fc3d" },
	{ "id": "medico:atendimento-revitalizante", "name": "Atendimento Revitalizante", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Quando utiliza Atendimento Emergencial, o Médico poderá gastar **duas cargas adicionais** do Kit Médico para recuperar o paciente com:\n**1d6 + modificador de Sabedoria em PV**\nEsse valor substitui o 1 PV normal da característica. O paciente desperta se nenhuma outra condição o mantiver Inconsciente.\nO limite de receber Atendimento Emergencial apenas uma vez antes de um descanso longo ou tratamento em instalação médica permanece normal.", "source": "https://app.notion.com/p/3e5508f8aa6c81b68712c6a064cf7484" },
	{ "id": "medico:atendimento-coletivo", "name": "Atendimento Coletivo", "kind": "class", "classId": "medico", "prerequisite": "nível 5 de Médico.", "text": "**Pré-requisito:** nível 5 de Médico.\nO Médico poderá utilizar Atendimento Emergencial em várias pessoas durante o mesmo procedimento.\nPara cada paciente além do primeiro:\n- O tempo total aumenta em cinco minutos.\n- Uma carga adicional do Kit Médico é consumida.\n- O Médico precisa ter acesso contínuo a todos durante o atendimento.\nEle poderá tratar um número máximo de pacientes igual ao seu **bônus de proficiência**. Cada um recupera 1 PV e registra separadamente o limite da característica.\nAtendimento Ágil reduz somente o tempo do primeiro paciente.", "source": "https://app.notion.com/p/3e5508f8aa6c8156b7e2ea9ab2e2b954" },
	{ "id": "medico:suporte-vital", "name": "Suporte Vital", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Quando começa Atendimento Emergencial em um paciente com 0 PV, o Médico poderá gastar uma carga adicional do Kit Médico para manter respiração, circulação e proteção do ferimento durante o procedimento.\nAté o atendimento terminar ou ser interrompido:\n- Dano contínuo de **Queimado**, **Envenenado** ou **Gravemente Envenenado** não provoca falhas adicionais nas salvaguardas contra a morte.\n- O paciente não piora apenas por permanecer com 0 PV.\n- Um transporte cuidadoso de até 3 metros não interrompe o procedimento.\nSuporte Vital suspende as consequências, mas não remove a condição. Se o Atendimento Emergencial terminar sem tratar a causa, o dano contínuo volta a ocorrer normalmente.", "source": "https://app.notion.com/p/3e5508f8aa6c81c8867fc2d8736147a8" },
	{ "id": "medico:retirada-de-emergencia", "name": "Retirada de Emergência", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Depois de concluir Atendimento Emergencial, o Médico poderá preparar o paciente para transporte durante o mesmo procedimento.\nAté chegar a um local seguro ou instalação médica:\n- O transporte comum não reabre ferimentos estabilizados.\n- Terreno irregular não provoca automaticamente perda de PV.\n- Quem carregar o paciente recebe **+2 em Atletismo** apenas para evitar quedas e movimentos prejudiciais.\n- O Médico reconhece imediatamente se a rota ou método de transporte ameaça agravar a condição.\nO benefício termina se o paciente sofrer novo dano, for transportado de forma incompatível ou permanecer sem atendimento pelo tempo indicado pelo Mestre.", "source": "https://app.notion.com/p/3e5508f8aa6c811487d3dc05017d8515" },
	{ "id": "medico:recuperacao-intensiva", "name": "Recuperação Intensiva", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Quando utiliza Recuperação Assistida durante um descanso longo, o Médico poderá gastar uma carga adicional do Kit Médico por paciente.\nCada paciente atendido recupera PV adicionais iguais a:\n**2 × bônus de proficiência do Médico + modificador de Sabedoria**\nEsse valor substitui o bônus normal de Recuperação Assistida e mantém o mínimo de 1 PV.\nUm paciente só recebe Recuperação Intensiva uma vez no mesmo descanso, e benefícios de vários Médicos não se acumulam.", "source": "https://app.notion.com/p/3e5508f8aa6c811bb540f8b0dd7ca44c" },
	{ "id": "medico:recuperacao-em-etapas", "name": "Recuperação em Etapas", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Depois que um paciente recebe Recuperação Assistida durante um descanso longo, o Médico poderá preparar orientações, curativos e doses para a etapa seguinte.\nNa próxima vez em que esse paciente concluir um descanso curto dentro das 24 horas seguintes, recupera PV adicionais iguais ao **bônus de proficiência do Médico**.\nO benefício termina após ser utilizado, depois de 24 horas ou se o paciente contrariar de maneira relevante as instruções médicas.\nVários preparos de Recuperação em Etapas não se acumulam.", "source": "https://app.notion.com/p/3e5508f8aa6c8180a11bdd0034a659bf" },
	{ "id": "medico:plano-individual-de-recuperacao", "name": "Plano Individual de Recuperação", "kind": "class", "classId": "medico", "prerequisite": "", "text": "Durante Recuperação Assistida, o Médico poderá escolher uma dificuldade específica de cada paciente:\n- Dor provocada por ferimento.\n- Mobilidade reduzida.\n- Fraqueza física.\n- Dificuldade de concentração.\n- Recuperação após doença ou veneno já neutralizado.\nAté o próximo descanso longo, a primeira vez em que o paciente sofrer uma penalidade numérica decorrente da dificuldade escolhida, ele reduz essa penalidade em **2 pontos**, até o mínimo de zero.\nO plano não remove condições ativas nem permite utilizar uma parte do corpo incapacitada.", "source": "https://app.notion.com/p/3e5508f8aa6c81d583dbed2046f22bc1" },
	{ "id": "medico:tratamento-de-queimaduras", "name": "Tratamento de Queimaduras", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico aprimora os primeiros socorros contra a condição **Queimado**.\nCom uma carga do Kit Médico e um minuto de atendimento, poderá realizar Medicina contra a CD da condição. Em caso de sucesso:\n- O dano contínuo da queimadura é interrompido.\n- A desvantagem causada pela condição fica suspensa.\n- O paciente poderá concluir um descanso curto sem que a queimadura volte a produzir seus efeitos.\nA condição será removida definitivamente ao final desse descanso se o paciente permanecer protegido e receber os cuidados indicados. Em uma falha, o atendimento apenas apaga fontes externas de fogo e não consome uma nova tentativa de tratamento completo.", "source": "https://app.notion.com/p/3e5508f8aa6c810894bcd748372d50bd" },
	{ "id": "medico:estimulo-neuromuscular", "name": "Estímulo Neuromuscular", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico poderá tratar a condição **Paralisado** utilizando uma carga do Kit Médico e dez minutos de atendimento.\nEle realiza Medicina contra a CD da condição. Em caso de sucesso, escolha um efeito:\n- O paciente realiza imediatamente uma nova resistência de Fortitude com **+2**.\n- Os efeitos da paralisia ficam suspensos por dez minutos, permitindo transporte e atendimento.\nSe superar a CD por 10 ou mais, a condição é removida.\nUma mesma pessoa só poderá receber uma nova resistência por Estímulo Neuromuscular para a mesma aplicação da condição.", "source": "https://app.notion.com/p/3e5508f8aa6c815c9364f37cd02f279a" },
	{ "id": "medico:aquecimento-controlado", "name": "Aquecimento Controlado", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico poderá tratar a condição **Congelado** sem expor o paciente a calor perigoso.\nCom uma carga do Kit Médico, uma fonte segura de calor e uma ação completa, realiza Medicina contra a CD da condição.\nEm caso de sucesso, o paciente realiza imediatamente uma resistência de Fortitude com vantagem. Se já possuía vantagem por outra fonte, recebe **+2** em seu lugar.\nSe superar a CD por 10 ou mais, o gelo é removido diretamente.\nEm uma falha por até 4 pontos, o procedimento não causa queimaduras nem choque térmico, mas também não progride.", "source": "https://app.notion.com/p/3e5508f8aa6c81d29ebad6e61de87088" },
	{ "id": "medico:resposta-neurologica", "name": "Resposta Neurológica", "kind": "class", "classId": "medico", "prerequisite": "", "text": "O Médico poderá intervir contra **Adormecido** ou **Confuso** quando a condição possuir origem física, química, tecnológica ou Pokémon.\nCom uma ação, uma carga do Kit Médico e acesso ao paciente, realiza Medicina contra a CD da condição.\nEm caso de sucesso:\n- Um paciente Adormecido realiza imediatamente uma nova resistência de Vontade com **+2**.\n- Um paciente Confuso ignora a próxima rolagem prejudicial de `1` ou `2` no `1d6` e age normalmente naquele turno.\nSe superar a CD por 10 ou mais, a condição termina.\nUma pessoa recebe apenas uma intervenção de Resposta Neurológica para cada aplicação da condição. O talento não funciona contra sono natural, controle mental ou trauma psicológico.", "source": "https://app.notion.com/p/3e5508f8aa6c8136a07dedd3682ffde8" },
	{ "id": "medico:recuperacao-da-exaustao", "name": "Recuperação da Exaustão", "kind": "class", "classId": "medico", "prerequisite": "nível 5 de Médico.", "text": "**Pré-requisito:** nível 5 de Médico.\nDurante Recuperação Assistida em um descanso longo, o Médico poderá dedicar duas cargas do Kit Médico a um paciente Exausto.\nSe o descanso possuir água, alimento, abrigo e segurança adequados, o paciente remove:\n**1 nível adicional de Exaustão**\nEsse nível é removido além da recuperação normal do descanso. Um mesmo paciente só poderá receber esse benefício uma vez dentro de cada período de 24 horas, independentemente de quantos Médicos o atendam.\nO talento não funciona enquanto a fonte da Exaustão continuar ativa.", "source": "https://app.notion.com/p/3e5508f8aa6c8170af4bf2698418bd3a" },
	{ "id": "medico:entre-a-vida-e-a-morte", "name": "Ápice — Entre a Vida e a Morte", "kind": "apex", "classId": "medico", "prerequisite": "nível 10 de Médico e Primeiros Segundos.", "text": "**Pré-requisitos:** nível 10 de Médico e Primeiros Segundos.\nQuando uma pessoa sofrer parada cardíaca, respiratória ou for declarada morta há no máximo **um minuto** por uma causa fisicamente reversível, o Médico poderá iniciar reanimação.\nO procedimento exige um Kit Médico de nível 3, três cargas, dez minutos e Medicina CD 25.\nEm caso de sucesso, o paciente retorna com **0 PV, Estável e inconsciente**, sofre um ferimento grave apropriado e precisará de tratamento especializado antes de recuperar PV normalmente.\nEm uma falha, o Médico poderá continuar tentando enquanto o período inicial de um minuto ainda não tiver terminado, consumindo novamente tempo e cargas conforme possível.\nEste ápice não funciona quando o corpo foi destruído, o cérebro sofreu dano irreversível, a causa permanece ativa ou a morte não pode ser revertida por medicina. Uma pessoa reanimada dessa forma não poderá receber o benefício novamente até concluir toda a recuperação do ferimento causado.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81e3a73cfe7b254fc5bb" },
	{ "id": "medico:medicina-de-emergencia", "name": "Ápice — Medicina de Emergência", "kind": "apex", "classId": "medico", "prerequisite": "nível 10 de Médico e Atendimento Ágil.", "text": "**Pré-requisitos:** nível 10 de Médico e Atendimento Ágil.\nO Médico poderá utilizar Atendimento Emergencial com **uma ação completa**, consumindo duas cargas do Kit Médico.\nO paciente recupera **1d6 + modificador de Sabedoria em PV**, desperta se nenhuma outra condição o impedir e poderá ser preparado para transporte imediatamente.\nSe possuir Suporte Vital, seus efeitos são aplicados sem custo adicional durante essa ação.\nDepois de receber Medicina de Emergência, o paciente continua sujeito ao limite normal do Atendimento Emergencial e não poderá receber novamente a característica antes de um descanso longo ou tratamento em instalação médica.\nEsse ápice trata uma pessoa adjacente e não pode ser utilizado em Pokémon participantes de uma batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c8154b160dd1ad1d88617" },
	{ "id": "medico:recuperacao-extraordinaria", "name": "Ápice — Recuperação Extraordinária", "kind": "apex", "classId": "medico", "prerequisite": "nível 10 de Médico e Recuperação Intensiva.", "text": "**Pré-requisitos:** nível 10 de Médico e Recuperação Intensiva.\nQuando acompanha um paciente durante um descanso longo em condições adequadas, o Médico poderá concentrar todo o período na recuperação dessa pessoa.\nAo final do descanso:\n- O paciente recupera o máximo possível em seus dados de recuperação, em vez de rolá-los.\n- Recebe o benefício de Recuperação Intensiva.\n- Remove uma condição física moderada que permita tratamento completo.\n- Reduz em dois dias o tempo restante de recuperação de um ferimento, até o mínimo de um dia.\nO Médico só poderá aplicar Recuperação Extraordinária a um paciente por descanso longo, e esse paciente não poderá receber o mesmo ápice novamente antes de concluir outro descanso longo.", "source": "https://app.notion.com/p/3e5508f8aa6c811fadf2f662997c77b7" },
	{ "id": "mentalista:palacio-da-memoria", "name": "Palácio da Memória", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "O Mentalista consegue organizar informações dentro de estruturas mentais e recuperá-las posteriormente com grande precisão.\nDepois de observar ou estudar algo por pelo menos um minuto, poderá armazená-lo como uma memória estruturada.\nCada memória poderá conter:\n- Uma página de texto.\n- Um mapa simples.\n- Uma imagem ou cena.\n- A disposição dos objetos de um ambiente.\n- Até cinco minutos de uma conversa.\n- Uma sequência curta de números, símbolos ou instruções.\n- A aparência e o comportamento de uma pessoa.\nO Mentalista poderá manter simultaneamente uma quantidade de memórias estruturadas igual a:\n```plain text\nBônus de proficiência + modificador de Inteligência\n```\nO mínimo será de uma memória.\nEnquanto estiver armazenada, ele poderá recordar seu conteúdo sem realizar teste. A memória conserva aquilo que realmente foi percebido, mas não revela detalhes que passaram despercebidos no momento original.\nAo ultrapassar o limite, o Mentalista escolhe uma memória anterior para deixar de manter com precisão. Ela passa a ser lembrada normalmente, como qualquer outra experiência.", "source": "https://app.notion.com/p/3e1508f8aa6c80e3b339fe12ba0cc0eb" },
	{ "id": "mentalista:persona-preparada", "name": "Persona Preparada", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "O Mentalista poderá construir uma identidade de cobertura utilizando um Kit de Disfarce e pelo menos uma hora de preparação.\nEle define nome, ocupação, origem, objetivo aparente, maneira de falar, postura e três fatos pessoais que sustentem a identidade.\nEnquanto permanecer caracterizado:\n- Perguntas comuns sobre os fatos preparados não exigem Enganação.\n- Sua aparência suporta uma inspeção casual sem teste.\n- Objetos e documentos simples compatíveis com a profissão parecem pertencer naturalmente à persona.\nUma contradição, inspeção física, documento oficial ou pessoa que conheça o indivíduo imitado ainda poderá exigir Enganação ou Atuação.\nO Mentalista poderá manter uma Persona Preparada por vez. Preparar outra encerra a anterior.", "source": "https://app.notion.com/p/3e5508f8aa6c8122833ac666af0bdaab" },
	{ "id": "mentalista:disfarce-de-ocasiao", "name": "Disfarce de Ocasião", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "O Mentalista consegue alterar rapidamente os sinais pelos quais é reconhecido.\nCom dez minutos, um Kit de Disfarce e roupas ou materiais plausíveis, poderá modificar idade aparente, posição social, ocupação, silhueta e traços gerais.\nO disfarce não imita uma pessoa específica, mas quem estiver procurando o Mentalista por uma descrição anterior recebe **−2 em Percepção ou Investigação** para reconhecê-lo.\nUma conversa prolongada, revista ou comparação direta com uma imagem atual permite um teste normal contra sua Enganação ou Atuação.", "source": "https://app.notion.com/p/3e5508f8aa6c81e6b74eed5a8396b859" },
	{ "id": "mentalista:voz-emprestada", "name": "Voz Emprestada", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Depois de ouvir uma pessoa falar durante pelo menos dez minutos, o Mentalista poderá reproduzir sua voz, ritmo, vocabulário e vícios de linguagem.\nQuem apenas ouvir a imitação sem ver o Mentalista precisará superar a Enganação dele com Intuição para perceber a falsidade.\nA imitação poderá transmitir frases que a pessoa seria capaz de dizer, mas não concede conhecimento de senhas, fatos pessoais ou idiomas desconhecidos.\nGravações analisadas por equipamento especializado e pessoas intimamente familiarizadas com a voz recebem vantagem para reconhecer a imitação.", "source": "https://app.notion.com/p/3e5508f8aa6c81b78cc3fe9100654cc2" },
	{ "id": "mentalista:maneirismos-copiados", "name": "Maneirismos Copiados", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Depois de observar uma pessoa por pelo menos uma hora, o Mentalista poderá copiar postura, gestos, expressões recorrentes e ritmo de movimento.\nQuando estiver disfarçado como essa pessoa, recebe **+2 em Atuação ou Enganação** contra observadores que a conheçam apenas profissional ou superficialmente.\nQuem convive intimamente com o indivíduo ainda poderá reconhecer diferenças de memória, hábitos privados e reações emocionais.\nO Mentalista poderá manter maneirismos copiados de uma quantidade de pessoas igual ao seu modificador de Inteligência, mínimo de uma.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81daac3dd9407f0e3705" },
	{ "id": "mentalista:rosto-na-multidao", "name": "Rosto na Multidão", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "O Mentalista sabe adotar comportamentos comuns ao ambiente para evitar ser lembrado.\nQuando passa por um local público sem chamar atenção deliberadamente, testemunhas comuns recordarão apenas características genéricas: roupa, porte aproximado e direção seguida.\nPara lembrar detalhes suficientes para reconhecê-lo depois, uma testemunha deverá superar a Furtividade ou Enganação do Mentalista com Percepção.\nO benefício termina se ele conversar longamente com a testemunha, realizar algo incomum, apresentar-se formalmente ou se tornar o centro da atenção.", "source": "https://app.notion.com/p/3e5508f8aa6c81c8938efdee41412a8b" },
	{ "id": "mentalista:quebra-de-ritmo", "name": "Quebra de Ritmo", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Quando uma pessoa estiver concentrada em uma tarefa que dependa de observação, fala ou precisão, o Mentalista poderá utilizar uma ação para quebrar seu ritmo com uma pergunta, gesto, ruído ou interrupção calculada.\nEle realiza Enganação ou Atuação contra a Vontade do alvo.\nEm caso de sucesso, escolha um efeito:\n- O alvo perde a reação até o início do próximo turno.\n- O alvo recebe **−2 no próximo teste de Percepção ou Intuição**.\n- Uma tarefa delicada realizada pelo alvo é pausada sem ser perdida.\nO efeito não funciona contra uma pessoa que não consiga perceber o estímulo e não interfere em Pokémon durante batalhas.", "source": "https://app.notion.com/p/3e5508f8aa6c8137ac1bd1fa957720ec" },
	{ "id": "mentalista:atencao-encadeada", "name": "Atenção Encadeada", "kind": "class", "classId": "mentalista", "prerequisite": "Quebra de Ritmo.", "text": "**Pré-requisito:** Quebra de Ritmo.\nQuando obtém sucesso em **Desvio de Atenção** ou **Quebra de Ritmo**, o Mentalista poderá conectar a distração inicial a um segundo estímulo preparado.\nA atenção do alvo permanece circulando entre os dois estímulos por até **um minuto**. Durante esse período:\n- Recebe **−2 em Percepção** para acontecimentos que não envolvam os estímulos.\n- Não percebe automaticamente uma ação discreta realizada fora do foco.\n- Um aliado poderá executar uma tarefa breve, como atravessar uma passagem, guardar um objeto ou manipular um mecanismo, realizando os testes normalmente.\nO efeito termina imediatamente se o alvo sofrer dano, perceber uma ameaça evidente, for alertado diretamente ou se um dos estímulos deixar de existir.\nA mesma pessoa não poderá ser afetada novamente por Atenção Encadeada durante a mesma cena.", "source": "https://app.notion.com/p/3e5508f8aa6c8182a005ef4fb3c8843a" },
	{ "id": "mentalista:distracao-coletiva", "name": "Distração Coletiva", "kind": "class", "classId": "mentalista", "prerequisite": "Desvio de Atenção e nível 5 de Mentalista.", "text": "**Pré-requisitos:** Desvio de Atenção e nível 5 de Mentalista.\nO Mentalista poderá direcionar seu Desvio de Atenção a uma quantidade de observadores igual ao seu bônus de proficiência, desde que todos percebam o mesmo estímulo.\nEle realiza uma única Enganação e compara o resultado com a Intuição de cada observador. Apenas aqueles que forem superados desviam a atenção e permitem que o aliado refaça o teste.\nObservadores previamente alertados sobre a tentativa recebem vantagem.", "source": "https://app.notion.com/p/3e5508f8aa6c812cb29cd598e16214f6" },
	{ "id": "mentalista:saida-sem-despedida", "name": "Saída Sem Despedida", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Quando não for o centro exclusivo da atenção, o Mentalista poderá preparar sua retirada durante uma conversa, reunião ou aglomeração.\nEle utiliza uma ação para introduzir uma mudança de assunto, nova pessoa de interesse ou motivo para que os presentes olhem em outra direção. Depois disso, poderá se afastar utilizando seu deslocamento.\nQuem quiser perceber imediatamente sua saída deverá superar Enganação com Intuição.\nEm caso de sucesso do Mentalista, os presentes só percebem sua ausência quando precisarem interagir novamente com ele. O talento não funciona em locais sem saída ou contra quem esteja encarregado especificamente de vigiá-lo.", "source": "https://app.notion.com/p/3e5508f8aa6c814fa153cb5751c939a8" },
	{ "id": "mentalista:assinatura-comportamental", "name": "Assinatura Comportamental", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Depois de observar uma pessoa por pelo menos dez minutos, o Mentalista poderá memorizar sua assinatura comportamental: ritmo de fala, postura, forma de olhar, distribuição de peso, pausas e pequenos hábitos involuntários.\nEnquanto mantiver essa assinatura na memória, ele poderá:\n- Reconhecer a pessoa mesmo sob disfarce visual comum.\n- Perceber que alguém está imitando essa pessoa sem reproduzir corretamente seus hábitos.\n- Distinguir o indivíduo de outra pessoa fisicamente semelhante.\n- Confirmar se uma gravação longa o bastante apresenta o comportamento esperado.\nQuando houver uma imitação especialmente preparada, o Mentalista realiza **Intuição com vantagem** contra a Enganação ou Atuação do imitador.\nA assinatura não atravessa transformações corporais que eliminem toda possibilidade de observação e não substitui identificação legal. O Mentalista poderá manter um número de assinaturas igual ao seu **bônus de proficiência**; ao exceder o limite, escolhe uma anterior para esquecer.\nAumente também em 1 sua Inteligência ou Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c819eb088ea515c349f2c" },
	{ "id": "mentalista:quebra-de-blefe", "name": "Quebra de Blefe", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Quando uma pessoa obtiver sucesso em Enganação contra o Mentalista ou contra alguém que ele consiga observar, o Mentalista poderá intervir imediatamente apontando uma inconsistência no comportamento, na cronologia ou na escolha de palavras.\nEle realiza **Intuição contra o resultado da Enganação original**.\nEm caso de sucesso, o alvo deverá repetir a rolagem de Enganação e aceitar o segundo resultado. As pessoas presentes avaliam novamente a afirmação utilizando esse novo resultado.\nQuebra de Blefe não revela automaticamente a verdade e não informa qual parte da história é falsa. O Mentalista apenas rompe a segurança com que o blefe havia sido aceito.\nUma mesma declaração só poderá ser afetada uma vez por este talento.", "source": "https://app.notion.com/p/3e5508f8aa6c8147b924c1d7e68d3eee" },
	{ "id": "mentalista:mapa-de-relacoes", "name": "Mapa de Relações", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Depois de observar um grupo interagindo por pelo menos dez minutos, o Mentalista poderá reconstruir sua dinâmica social.\nEle identifica:\n- Quem possui maior autoridade prática.\n- Quem procura aprovação de quem.\n- Qual pessoa parece isolada ou contrariada.\n- Quais duas pessoas demonstram maior confiança.\n- Onde existe tensão perceptível.\nDurante a cena, poderá utilizar uma dessas relações como argumento e receber **+2 em um teste social** coerente.\nRelações deliberadamente ocultadas poderão exigir Intuição contra Enganação. O talento interpreta comportamento, não conhece cargos ou vínculos secretos sem sinais.", "source": "https://app.notion.com/p/3e5508f8aa6c81528405e63c02a5c308" },
	{ "id": "mentalista:reacao-antecipada", "name": "Reação Antecipada", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Depois de observar uma pessoa durante uma cena, o Mentalista poderá prever como ela provavelmente reagirá a uma ação imediata e específica.\nAntes de agir, ele pergunta ao Mestre qual destas respostas parece mais provável:\n- Confrontar.\n- Recuar.\n- Pedir ajuda.\n- Negociar.\n- Proteger alguém ou algo.\n- Fingir indiferença.\nA resposta considera apenas o que o Mentalista observou. Se ele agir exatamente sobre essa previsão, recebe **+2 na iniciativa ou no primeiro teste social** decorrente da ação, escolhendo o aplicável.\nInformações ocultas ou mudanças súbitas poderão tornar a previsão incorreta.", "source": "https://app.notion.com/p/3e5508f8aa6c813aaa48cadee56bde2d" },
	{ "id": "mentalista:semente-de-duvida", "name": "Semente de Dúvida", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "O Mentalista poderá apontar uma inconsistência real em uma afirmação, plano ou ordem recebida por outra pessoa.\nDepois de uma conversa de pelo menos um minuto, realiza Persuasão ou Enganação contra a Vontade do alvo.\nEm caso de sucesso, o alvo não abandona automaticamente sua posição, mas hesita antes de agir sobre ela. Até obter confirmação ou nova evidência:\n- Não poderá utilizar reação para executar aquela ordem.\n- Recebe **−2 no primeiro teste** diretamente necessário para sustentá-la.\nA inconsistência precisa existir ou ser apoiada por uma evidência falsa plausível. A pessoa poderá eliminar o efeito verificando os fatos.", "source": "https://app.notion.com/p/3e5508f8aa6c81df9706fd7eabf342ae" },
	{ "id": "mentalista:inducao-hipnotica", "name": "Indução Hipnótica", "kind": "class", "classId": "mentalista", "prerequisite": "", "text": "Durante uma conversa, o Mentalista poderá conduzir discretamente o ritmo, as associações e a atenção da outra pessoa até que ela responda antes de perceber a intenção real da pergunta.\nEle escolhe **uma informação específica** que a pessoa conheça conscientemente e que possa ser expressa em uma resposta curta. Em seguida, realiza:\n**Persuasão contra Vontade**\nEm caso de sucesso, o alvo revela uma informação verdadeira relacionada ao assunto da conversa sem perceber, naquele instante, que ultrapassou o que pretendia contar.\nLogo depois de falar, a pessoa percebe que revelou algo que talvez devesse ter guardado. Ela se lembra normalmente da conversa e poderá reagir com silêncio, irritação, suspeita, medo ou encerrando o diálogo.\nIndução Hipnótica:\n- Não faz o alvo inventar uma resposta.\n- Não acessa memórias esquecidas ou inconscientes.\n- Não obriga ações.\n- Não impede que a pessoa perceba a revelação depois de falar.\n- Não poderá ser repetida contra a mesma pessoa no mesmo dia.\nSe a tentativa falhar, o alvo percebe que o Mentalista estava tentando conduzi-lo a revelar alguma coisa, mesmo que não compreenda toda a técnica.", "source": "https://app.notion.com/p/3e5508f8aa6c818eab42f6d8680ef78a" },
	{ "id": "mentalista:persona-irretocavel", "name": "Ápice — Persona Irretocável", "kind": "apex", "classId": "mentalista", "prerequisite": "nível 10 de Mentalista, Persona Preparada, Voz Emprestada e Maneirismos Copiados.", "text": "**Pré-requisitos:** nível 10 de Mentalista, Persona Preparada, Voz Emprestada e Maneirismos Copiados.\nO Mentalista poderá preparar durante um descanso longo uma representação completa de uma pessoa que tenha estudado diretamente.\nContra quem não possua vínculo íntimo com o imitado, a persona não exige testes enquanto o Mentalista agir dentro das informações e comportamentos preparados.\nQuando surgir uma contradição inesperada, o Mentalista poderá realizar Enganação ou Atuação. Em caso de falha por até 4 pontos, o observador percebe uma estranheza, mas interpreta como cansaço, estresse ou mudança de humor; a identidade não é imediatamente revelada.\nDocumentos biométricos, capacidades físicas impossíveis, memórias privadas e pessoas íntimas ainda poderão desmascará-lo.", "source": "https://app.notion.com/p/3e5508f8aa6c81d280ccedb3523b48d9" },
	{ "id": "mentalista:mestre-da-atencao", "name": "Ápice — Mestre da Atenção", "kind": "apex", "classId": "mentalista", "prerequisite": "nível 10 de Mentalista e Distração Coletiva.", "text": "**Pré-requisitos:** nível 10 de Mentalista e Distração Coletiva.\nCom uma ação e um estímulo que todos possam perceber, o Mentalista poderá reorganizar o foco de uma cena inteira.\nEscolhe até **dez pessoas** e realiza Enganação ou Atuação contra a Vontade de cada uma. Quem falhar fica **Fascinado** pelo estímulo até o início do próximo turno do Mentalista.\nO efeito termina imediatamente para uma pessoa que sofrer dano, perceber ameaça evidente ou não puder mais perceber o estímulo.\nMestre da Atenção não funciona durante batalhas Pokémon e não poderá afetar a mesma pessoa novamente na mesma cena.", "source": "https://app.notion.com/p/3e5508f8aa6c81f8a3deff837ee9b3d2" },
	{ "id": "mentalista:arquiteto-social", "name": "Ápice — Arquiteto Social", "kind": "apex", "classId": "mentalista", "prerequisite": "nível 10 de Mentalista.", "text": "**Pré-requisito:** nível 10 de Mentalista.\nDepois de observar uma organização, grupo ou comunidade durante pelo menos um dia, o Mentalista poderá mapear seus interesses, rivalidades, autoridades formais e influências informais.\nEle escolhe um objetivo social plausível, como conseguir uma audiência, fazer circular uma informação, provocar uma reunião, obter apoio para uma proposta ou atrasar uma decisão.\nO Mestre informa três caminhos possíveis para alcançar o objetivo, cada um ligado a uma pessoa, relação ou interesse que possa ser influenciado.\nNa primeira tentativa realizada por cada caminho, o Mentalista recebe **+2 no teste social** e uma falha por até 4 pontos gera uma exigência, atraso ou custo, em vez de encerrar definitivamente a oportunidade.\nO ápice não controla o grupo, não garante o objetivo e não cria relações que não existam.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81278d57f23afa8763db" },
	{ "id": "mestre-pokemon:pontaria-paciente", "name": "Pontaria Paciente", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Fora de uma batalha, antes de arremessar uma Poké Bola, o Mestre Pokémon poderá gastar uma ação observando o deslocamento do alvo.\nSe permanecer capaz de vê-lo até a tentativa, realiza o próximo teste de Captura com **vantagem**.\nDurante uma batalha Pokémon contra um Pokémon selvagem, essa experiência se torna automática:\n**Todos os testes de Captura realizados pelo Mestre Pokémon para acertar o Pokémon selvagem são feitos com vantagem.**\nNesse caso, não é necessário gastar uma ação anterior mirando. A própria ação de captura já utiliza a vantagem.\nA preparação fora de batalha termina se o treinador sofrer uma condição que impeça concentração, perder o Pokémon de vista ou realizar outra ação além de se reposicionar.\nPontaria Paciente melhora apenas o acerto da Poké Bola. A porcentagem posterior de captura não é alterada. Uma falha automática provocada por Reflect não é evitada pela vantagem.", "source": "https://app.notion.com/p/3e5508f8aa6c81219097cd66d4cee76b" },
	{ "id": "mestre-pokemon:arremesso-angulado", "name": "Arremesso Angulado", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "O Mestre Pokémon consegue utilizar paredes, solo, obstáculos e trajetórias curvas para alcançar um Pokémon protegido.\nQuando existir uma trajetória fisicamente possível, ele poderá:\n- Ignorar **cobertura parcial** no teste para acertar uma Poké Bola.\n- Reduzir em 2 pontos a penalidade provocada por um ângulo difícil.\n- Contornar a barreira produzida por **Reflect** em uma batalha contra Pokémon selvagem.\nNormalmente, uma tentativa de captura contra um Pokémon selvagem protegido por Reflect falha automaticamente na etapa do arremesso. Com Arremesso Angulado, o Mestre Pokémon ignora essa falha automática e realiza o teste de Captura normalmente, lançando por cima, pelas laterais ou por meio de um ricochete plausível.\nO talento não remove Reflect, não reduz sua duração e não interfere em nenhum ataque da batalha.\nSe o arremesso depender de um ricochete, uma falha por 5 ou mais faz a Poké Bola cair em outro ponto plausível do cenário, sem atingir outra criatura.\nArremesso Angulado não atravessa cobertura total e não modifica a porcentagem de captura calculada depois do acerto.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81cebcfbc45272052dbf" },
	{ "id": "mestre-pokemon:escolha-adequada", "name": "Escolha Adequada", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Durante uma batalha contra um Pokémon selvagem, o Mestre Pokémon reconhece imediatamente quais Poké Balls estão sendo beneficiadas pelas condições atuais.\nQuando abrir a seleção de Poké Balls, cada modelo que possuir deverá mostrar:\n- Seu efeito de captura.\n- A condição necessária para ativar o efeito.\n- Se o benefício está **ativo** ou **inativo** naquele momento.\n- Qual benefício ativo será aplicado, como multiplicador ou modificador próprio da Poké Ball.\nAs Poké Balls atualmente beneficiadas deverão receber uma indicação visual clara, permitindo comparar as opções antes da tentativa.\nAs informações são atualizadas quando o Pokémon, o ambiente, o turno, o horário ou outra condição relevante mudar.\nEscolha Adequada não revela a porcentagem final de captura, os PV numéricos do Pokémon nem informações que o treinador ainda não possa observar. O talento apenas explica os efeitos das Poké Balls disponíveis e indica quais estão realmente ativos.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c81fc9267ef213f36feec" },
	{ "id": "mestre-pokemon:arremesso-perfeito", "name": "Arremesso Perfeito", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "nível 5 de Mestre Pokémon.", "text": "**Pré-requisito:** nível 5 de Mestre Pokémon.\nQuando o resultado do teste para acertar a Poké Bola superar a CD por **10 ou mais**, o arremesso posiciona a bola no melhor ponto possível para a ativação.\nDepois de aplicar todos os modificadores normais, a chance de captura recebe:\n**+5 pontos percentuais**\nA chance final não poderá ultrapassar 95% por causa deste talento. Arremesso Perfeito não se aplica se o acerto for automático ou dispensar teste.", "source": "https://app.notion.com/p/3e5508f8aa6c81d59965db8d9dd85d9a" },
	{ "id": "mestre-pokemon:capturador-especialista", "name": "Capturador Especialista", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "nível 5 de Mestre Pokémon.", "text": "**Pré-requisito:** nível 5 de Mestre Pokémon.\nO Mestre Pokémon entende como aproximar-se, ativar e lançar a Poké Bola sem desperdiçar o instante correto.\nQuando acerta uma tentativa de captura, poderá receber **+5 pontos percentuais** na chance final.\nPara utilizar o benefício, deverá ter observado o Pokémon durante pelo menos uma rodada e ser capaz de perceber seus movimentos.\nSomado a outros talentos do treinador, o bônus total aplicado diretamente à porcentagem de captura não poderá ultrapassar **+10 pontos percentuais**.\nAumente também em 1 sua Destreza ou Sabedoria, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c8132b9b5c936e2f027b5" },
	{ "id": "mestre-pokemon:captura-sem-risco", "name": "Captura Sem Risco", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Quando o Mestre Pokémon falha no teste para acertar uma Poké Bola, a bola não é perdida nem destruída.\nComo ela não atingiu o Pokémon, não chega a ser ativada e poderá ser recuperada normalmente.\nDurante uma batalha contra Pokémon selvagem:\n- Toda Poké Bola que errar o arremesso é registrada como recuperável.\n- Ela permanece fora da bag até o encerramento do combate.\n- Ao final da batalha, retorna automaticamente para a bag do treinador.\n- A devolução acontece mesmo que a batalha termine por vitória, derrota, captura ou fuga.\nIsso também se aplica a Poké Balls desviadas por Reflect antes de serem ativadas.\nSe a Poké Bola atingir o Pokémon e a captura falhar na etapa percentual, ela é consumida normalmente. Captura Sem Risco protege apenas tentativas que falharam no arremesso.", "source": "https://app.notion.com/p/3e5508f8aa6c815e973ff27c35986925" },
	{ "id": "mestre-pokemon:registro-de-campo", "name": "Registro de Campo", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Depois de observar uma espécie durante dez minutos ou examinar um indivíduo capturado, o Mestre Pokémon poderá criar uma entrada de campo na Pokédex ou em suas anotações.\nA entrada registra:\n- Habitat observado.\n- Alimentação aparente.\n- Horário de atividade.\n- Comportamento diante de pessoas.\n- Sinais, pegadas ou vocalizações.\n- Uma necessidade de cuidado percebida.\nQuando voltar a procurar essa espécie na mesma região, recebe **+2 no primeiro teste de Conhecimento: Pokémon, Natureza ou Sobrevivência** relacionado à entrada.\nO registro contém apenas informações realmente observadas ou confirmadas.", "source": "https://app.notion.com/p/3e5508f8aa6c812197c0f8a27e6c16f1" },
	{ "id": "mestre-pokemon:rastreador-de-especies", "name": "Rastreador de Espécies", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Depois de encontrar um vestígio identificável de um Pokémon, o Mestre poderá utilizar **Conhecimento: Pokémon** no lugar de Sobrevivência para determinar a espécie, direção e tempo aproximado desde sua passagem.\nSe a espécie estiver registrada em seu Registro de Campo, também poderá distinguir seus sinais dos de espécies semelhantes e recebe **+2 para seguir a trilha**.\nO talento não cria rastros onde não existem nem identifica automaticamente um indivíduo específico.", "source": "https://app.notion.com/p/3e5508f8aa6c81399493ef0a3d72fe0d" },
	{ "id": "mestre-pokemon:busca-direcionada", "name": "Busca Direcionada", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "Rastreador de Espécies.", "text": "**Pré-requisito:** Rastreador de Espécies.\nO Mestre Pokémon poderá declarar uma espécie selvagem e passar uma hora procurando sinais em um ambiente compatível.\nSe a espécie existir naquela região e houver indivíduos acessíveis, um sucesso em Conhecimento: Pokémon ou Sobrevivência encontra uma trilha recente ou reduz a busca à área correta.\nSe superar a CD por 10 ou mais, também descobre uma informação: quantidade aproximada, horário mais favorável, risco ambiental ou presença de outra espécie próxima.\nBusca Direcionada não faz Pokémon inexistentes aparecerem e não garante que o encontro seja seguro ou imediato.", "source": "https://app.notion.com/p/3e5508f8aa6c8149a46ae570580f658f" },
	{ "id": "mestre-pokemon:isca-ecologica", "name": "Isca Ecológica", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Depois de identificar uma espécie presente na região, o Mestre Pokémon poderá preparar por trinta minutos um ponto de observação com alimento, odor, som ou objeto coerente com seus hábitos.\nEle consome uma porção adequada de alimento ou material definido pelo Mestre. Se um indivíduo da espécie estiver nas proximidades, poderá aproximar-se durante a próxima hora.\nO Pokémon não se torna amistoso, capturável ou desprevenido automaticamente. O ponto apenas cria uma oportunidade de observação ou contato.\nUma isca inadequada, ambiente perigoso ou presença de predadores poderá atrair outra espécie ou afastar o alvo.\n<empty-block/>", "source": "https://app.notion.com/p/3e5508f8aa6c8121ab55f7a418c4132a" },
	{ "id": "mestre-pokemon:observador-de-formas", "name": "Observador de Formas", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "O Mestre Pokémon desenvolveu um olhar atento para pequenos sinais de presença: pegadas quase apagadas, sons distantes, marcas no ambiente e hábitos que passariam despercebidos por outros treinadores.\nQuando procura deliberadamente um Pokémon que exista na região, recebe:\n**+2 nos testes realizados durante a busca**\nO bônus ajuda a localizar tanto a espécie mais comum quanto suas formas presentes naquela região, mas não faz surgir um Pokémon que não esteja disponível no local.", "source": "https://app.notion.com/p/3e5508f8aa6c81ba80f2d89d51666911" },
	{ "id": "mestre-pokemon:encontro-incomum", "name": "Encontro Incomum", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "Registro de Campo e nível 5 de Mestre Pokémon.", "text": "**Pré-requisitos:** Registro de Campo e nível 5 de Mestre Pokémon.\nQuando explora um habitat, o Mestre poderá procurar sinais que outros treinadores normalmente ignorariam.\nEm um sucesso de Conhecimento: Pokémon ou Percepção, o Mestre deverá incluir na oportunidade encontrada uma destas possibilidades existentes na região:\n- Uma espécie rara.\n- Uma forma regional ou alternativa.\n- Um indivíduo fora do horário habitual.\n- Um comportamento pouco documentado.\n- Um habitat secundário escondido.\nO talento não cria espécies, formas shiny ou encontros que a região não possua. O Mestre define qual possibilidade é coerente.", "source": "https://app.notion.com/p/3e5508f8aa6c819f84b1c4194bbabcda" },
	{ "id": "mestre-pokemon:leitura-de-comportamento-pokemon", "name": "Leitura de Comportamento Pokémon", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Depois de observar um Pokémon fora de batalha por pelo menos um minuto, o Mestre poderá utilizar Empatia Pokémon para identificar sua intenção predominante:\n- Fugir.\n- Defender território.\n- Proteger outro indivíduo.\n- Procurar alimento ou ajuda.\n- Investigar por curiosidade.\n- Preparar uma agressão.\nEm caso de sucesso, também identifica uma ação que provavelmente agravaria a situação.\nEssa leitura não controla o Pokémon, não revela pensamentos e poderá mudar se as circunstâncias se alterarem.", "source": "https://app.notion.com/p/3e5508f8aa6c81eb9c07c17764281f01" },
	{ "id": "mestre-pokemon:contato-sem-confronto", "name": "Contato sem Confronto", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "Leitura de Comportamento Pokémon.", "text": "**Pré-requisito:** Leitura de Comportamento Pokémon.\nQuando encontra um Pokémon selvagem que ainda não entrou em confronto, o Mestre poderá passar um minuto demonstrando que não representa ameaça.\nEle realiza Empatia Pokémon contra a Vontade ou CD definida pelo Mestre. Em caso de sucesso, o Pokémon não inicia uma agressão ou fuga imediata e permite uma interação simples, como deixar alimento, recuar, observar ou pedir passagem.\nO efeito termina diante de ameaça, aproximação forçada, tentativa de captura ou comportamento incompatível.\nContato sem Confronto não melhora a relação inicial, não domestica o Pokémon e não substitui captura.", "source": "https://app.notion.com/p/3e5508f8aa6c815bab99f4dcf21ded1c" },
	{ "id": "mestre-pokemon:rotina-confortavel", "name": "Rotina Confortável", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "Durante Rotina de Equipe, o Mestre Pokémon poderá adaptar alimentação, descanso e espaço às preferências individuais de seus Pokémon.\nOs Pokémon atendidos recebem **+2 de Amizade** ao final do descanso, desde que possuam alimento, água, segurança e espaço compatíveis.\nEsse ganho só poderá ocorrer uma vez por Pokémon a cada dia e não se acumula com outra aplicação de Rotina Confortável.\nO talento não concede bônus de combate nem substitui eventos, cuidados ou limites normais de Amizade.", "source": "https://app.notion.com/p/3e5508f8aa6c812782d7c317340c56d7" },
	{ "id": "mestre-pokemon:sinais-de-equipe", "name": "Sinais de Equipe", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "", "text": "O Mestre Pokémon poderá ensinar durante um descanso um conjunto de sinais simples a um Pokémon com pelo menos **50 de Amizade**.\nOs sinais podem comunicar:\n- Aproximar-se ou afastar-se.\n- Esperar.\n- Procurar uma pessoa ou objeto conhecido.\n- Alertar sobre algo percebido.\n- Retornar ao treinador.\n- Permanecer em determinado local.\nO Pokémon precisa ser capaz de perceber o sinal e compreender o conceito. Sinais de Equipe funcionam fora de combate e não concedem ações, prioridade ou comandos especiais durante batalhas.", "source": "https://app.notion.com/p/3e5508f8aa6c8145a738ce0854393bb3" },
	{ "id": "mestre-pokemon:auxiliar-pokemon", "name": "Auxiliar Pokémon", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "Sinais de Equipe.", "text": "**Pré-requisito:** Sinais de Equipe.\nFora de combate, um Pokémon com pelo menos 50 de Amizade poderá ajudar o Mestre em um teste quando sua anatomia, sentidos ou capacidades naturais contribuírem de maneira real.\nO Pokémon não realiza a perícia no lugar do treinador. Ele fornece +2 na pericia utilizada.\nExemplos incluem farejar uma trilha, iluminar uma área, alcançar um ponto elevado, mover um obstáculo ou detectar vibrações.\nAuxiliar Pokémon não modifica testes de Captura, concursos ou qualquer ação realizada em batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c81eeb03ae8083567fcba" },
	{ "id": "mestre-pokemon:captura-inesperada", "name": "Captura Inesperada", "kind": "class", "classId": "mestre-pokemon", "prerequisite": "nível 5 de Mestre Pokémon.", "text": "**Pré-requisito:** nível 5 de Mestre Pokémon.\nQuando o Mestre Pokémon tenta capturar um Pokémon selvagem **fora de uma batalha Pokémon**, ele aproveita o instante em que o alvo ainda não está preparado para resistir à Poké Bola.\nSe o arremesso acertar, o cálculo percentual considera o HP do Pokémon como:\n**No máximo 50% dos PV máximos**\nIsso significa:\n- Um Pokémon com HP cheio será calculado como se estivesse com metade do HP.\n- Um Pokémon acima da metade também será calculado com 50%.\n- Um Pokémon que já esteja abaixo da metade mantém seu HP real, pois esse valor é mais favorável.\n- Nenhum dano é causado e o HP verdadeiro do Pokémon não é alterado.\nO benefício vale apenas para a **primeira Poké Bola lançada antes do início de um confronto**.\nSe a captura falhar, o Pokémon percebe a tentativa e reage normalmente, podendo fugir, tornar-se hostil ou iniciar uma batalha. Outras tentativas utilizam o HP real, salvo se uma nova cena e uma nova oportunidade legítima de aproximação forem estabelecidas pelo Mestre.\nCaptura Inesperada não funciona contra Pokémon que já estejam lutando, alertas para uma tentativa de captura, impedidos de serem capturados ou participando de batalha formal.", "source": "https://app.notion.com/p/3e5508f8aa6c81a28fa8c5af8d1627f1" },
	{ "id": "mestre-pokemon:mestre-da-captura", "name": "Ápice — Mestre da Captura", "kind": "apex", "classId": "mestre-pokemon", "prerequisite": "nível 10 de Mestre Pokémon e Capturador Especialista.", "text": "**Pré-requisitos:** nível 10 de Mestre Pokémon e Capturador Especialista.\nDurante batalhas contra Pokémon selvagens, toda Poké Bola que acertar o alvo realiza normalmente a primeira tentativa percentual de captura.\nSe essa primeira tentativa falhar, o ápice ativa imediatamente:\n**Uma segunda tentativa percentual de captura é realizada em seguida.**\nA segunda tentativa:\n- Utiliza a mesma Poké Bola e os mesmos modificadores da primeira.\n- Não exige outro teste de arremesso.\n- Não consome outra ação.\n- Não consome outra Poké Bola.\n- Deve aceitar o segundo resultado.\nO efeito ocorre automaticamente em cada arremesso bem-sucedido contra um Pokémon selvagem.\nO ápice não funciona quando a captura é impossível, quando o arremesso falha, quando Reflect bloqueia a Poké Bola antes do acerto ou quando outro efeito impede que a porcentagem de captura seja calculada.", "source": "https://app.notion.com/p/3e5508f8aa6c81859e9ae6c823a78534" },
	{ "id": "mestre-pokemon:enciclopedia-viva", "name": "Ápice — Enciclopédia Viva", "kind": "apex", "classId": "mestre-pokemon", "prerequisite": "nível 10 de Mestre Pokémon e Registro de Campo.", "text": "**Pré-requisitos:** nível 10 de Mestre Pokémon e Registro de Campo.\nQuando observa uma espécie por uma rodada, o Mestre poderá consultar de memória seu conhecimento acumulado.\nSe a espécie possuir informações públicas ou registradas, ele reconhece automaticamente:\n- Nome e forma conhecida.\n- Habitat e alimentação comuns.\n- Comportamento geral.\n- Linha evolutiva documentada.\n- Métodos conhecidos de evolução.\n- Sinais evidentes de forma regional ou alternativa.\nAlém disso, poderá fazer ao Mestre uma pergunta sobre uma característica prática conhecida da espécie. A resposta será verdadeira, mas não revelará atributos numéricos, golpes atuais, habilidade individual ou informações secretas daquele Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81cd980acadf89eb1afc" },
	{ "id": "mestre-pokemon:companheiros-de-jornada", "name": "Ápice — Companheiros de Jornada", "kind": "apex", "classId": "mestre-pokemon", "prerequisite": "nível 10 de Mestre Pokémon.", "text": "**Pré-requisito:** nível 10 de Mestre Pokémon.\nDurante um descanso longo, o Mestre poderá organizar uma atividade coletiva com até seis Pokémon de sua equipe.\nCada Pokémon participante recebe **+5 de Amizade**, respeitando o limite normal, e o Mestre poderá estabelecer com cada um um sinal novo sem gastar tempo adicional.\nAté o próximo descanso longo, uma vez, quando o grupo enfrentar um obstáculo fora de combate, até três desses Pokémon poderão contribuir para a mesma tarefa. Apenas o maior bônus de ajuda é aplicado, mas as diferentes contribuições permitem executar uma tarefa que exigiria capacidades variadas.\nO ápice não concede efeitos em batalha, não altera atributos e não permite que Pokémon realizem perícias impossíveis para sua anatomia.", "source": "https://app.notion.com/p/3e5508f8aa6c814caa19e550b904d360" },
	{ "id": "psiquico:controle-delicado", "name": "Controle Delicado", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "O Psíquico aprende a utilizar a Telecinese Menor com precisão equivalente à das próprias mãos.\nEnquanto enxergar o objeto e mantiver a concentração, poderá escrever, girar uma chave já inserida, separar componentes, costurar, operar controles, manipular ferramentas simples ou executar outra tarefa delicada a até 9 metros.\nQuando a ação exigir uma perícia, realiza o teste normalmente. A distância não substitui ferramentas, domínio de kit ou treinamento necessários.\nControle Delicado não permite atacar, empunhar armas ofensivamente, acionar ou arremessar Poké Bolas, retirar algo segurado por outra criatura nem interferir em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c8138b730eefa9b681c89" },
	{ "id": "psiquico:impulso-telecinetico", "name": "Impulso Telecinético", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "O Psíquico poderá usar uma ação para projetar ou atrair uma pessoa que enxergue a até 9 metros.\nO alvo realiza uma resistência de Fortitude contra a CD psíquica. Em caso de falha, é deslocado 3 metros em linha reta, aproximando-se ou afastando-se do Psíquico. Uma criatura poderá aceitar o efeito sem realizar a resistência.\nO deslocamento termina diante de uma barreira e não causa dano por colisão. O talento poderá afastar alguém de um perigo, romper um cerco humano ou alcançar uma borda segura, mas não poderá ser usado contra Pokémon durante uma batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c814ba792d16503093af2" },
	{ "id": "psiquico:telecinese-ampliada", "name": "Telecinese Ampliada", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico.**", "text": "**Pré-requisito: nível 5 de Psíquico.**\nA Telecinese Menor passa a afetar objetos soltos de até 25 quilogramas, seu alcance aumenta para 18 metros e o objeto poderá percorrer até 12 metros por rodada ou período equivalente.\nSe possuir Controle Delicado, também poderá executar tarefas precisas dentro do novo alcance.\nO aumento não remove as demais limitações da Telecinese Menor: objetos segurados continuam protegidos, a capacidade não realiza ataques nem capturas e não interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81bd9531df773d276224" },
	{ "id": "psiquico:resgate-telecinetico", "name": "Resgate Telecinético", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Telecinese Ampliada.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Telecinese Ampliada.**\nQuando uma pessoa, objeto importante ou estrutura leve começar a cair dentro do alcance da Telecinese Ampliada, o Psíquico poderá reagir imediatamente para desacelerar a queda.\nEle reduz em até 12 metros a distância considerada para o dano da queda e poderá conduzir o alvo até o ponto seguro mais próximo que suporte seu peso. Se a queda ainda exceder essa distância, o efeito reduz o impacto, mas não o elimina.\nO Psíquico deverá manter a concentração até concluir o resgate. O talento não poderá retirar um Pokémon de uma batalha nem alterar consequências de golpes.", "source": "https://app.notion.com/p/3e5508f8aa6c8114a41af171790685a0" },
	{ "id": "psiquico:barreira-cinetica", "name": "Barreira Cinética", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico.**", "text": "**Pré-requisito: nível 5 de Psíquico.**\nQuando o próprio Psíquico for alvo de um ataque físico que consiga perceber, poderá usar sua reação para erguer uma barreira telecinética instantânea e receber:\n```plain text\n+2 na Defesa contra esse ataque\n```\nA barreira desaparece após a resolução do ataque e não exige concentração. Ela protege somente o Psíquico, não reduz dano de área e não poderá ser projetada sobre Pokémon ou utilizada para interferir em uma batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81e6a328e94c1587f6d1" },
	{ "id": "psiquico:levitacao-psiquica", "name": "Levitação Psíquica", "kind": "class", "classId": "psiquico", "prerequisite": "nível 7 de Psíquico e Telecinese Ampliada.**", "text": "**Pré-requisitos: nível 7 de Psíquico e Telecinese Ampliada.**\nO Psíquico poderá sustentar o próprio corpo no ar enquanto mantiver concentração. Ele se desloca até 6 metros por rodada, inclusive verticalmente, e deverá permanecer a até 18 metros de uma superfície ou estrutura capaz de orientar seu movimento.\nA levitação não permite transportar peso acima da própria capacidade de carga. Se a concentração terminar, o Psíquico desce de maneira controlada por até 6 metros; acima disso, cairá normalmente após essa distância.\nA capacidade não poderá ser utilizada para carregar Pokémon durante batalhas ou produzir vantagens para seus golpes.", "source": "https://app.notion.com/p/3e5508f8aa6c813e9859e2694077a993" },
	{ "id": "psiquico:elo-telepatico", "name": "Elo Telepático", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "A Telepatia poderá permanecer ativa mesmo quando o alvo sair do campo de visão, desde que continue consciente, disposto e a até 60 metros.\nAlém disso, o Psíquico poderá intermediar a comunicação entre si e duas criaturas dispostas. Cada participante ouvirá apenas aquilo que o Psíquico decidir transmitir, e nenhum deles poderá acessar pensamentos não enviados voluntariamente.\nO elo exige concentração e termina para quem sair do alcance. Durante batalhas Pokémon, continua contando apenas como comunicação normal do treinador.", "source": "https://app.notion.com/p/3e5508f8aa6c81599996ef3cafe3f3ff" },
	{ "id": "psiquico:rede-telepatica", "name": "Rede Telepática", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Elo Telepático.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Elo Telepático.**\nO Psíquico poderá conectar simultaneamente um número de criaturas conscientes e dispostas igual ao seu bônus de proficiência, além de si mesmo, dentro de 60 metros.\nTodos os participantes poderão transmitir palavras, emoções e imagens simples à rede enquanto permanecerem no alcance. O Psíquico poderá silenciar ou retirar qualquer participante e deverá manter a concentração.\nA rede não compartilha sentidos, pensamentos involuntários ou informações que um participante desconheça. Em batalhas Pokémon, não concede ações adicionais, coordenação mecânica, prioridade ou qualquer bônus.", "source": "https://app.notion.com/p/3e5508f8aa6c8198927ec6cf27eebf41" },
	{ "id": "psiquico:projecao-sensorial", "name": "Projeção Sensorial", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Elo Telepático.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Elo Telepático.**\nCom a permissão de uma criatura consciente a até 18 metros, o Psíquico poderá perceber por meio da visão e da audição dela enquanto mantiver concentração.\nDurante o efeito, deixa de enxergar e ouvir pelos próprios sentidos. Ele não controla o alvo, não acessa pensamentos e não utiliza sentidos especiais que a criatura possua além de visão e audição comuns.\nCom um Pokémon disposto, a projeção poderá ser usada em exploração, busca e resgate, mas não durante uma batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81ec8063ec0a805b7aaf" },
	{ "id": "psiquico:leitura-superficial", "name": "Leitura Superficial", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Elo Telepático.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Elo Telepático.**\nO Psíquico poderá tentar perceber aquilo que ocupa imediatamente a mente de uma criatura consciente a até 9 metros. O alvo realiza uma resistência de Vontade contra a CD psíquica.\nEm caso de falha, o Psíquico identifica por alguns instantes:\n- O pensamento dominante naquele momento.\n- A emoção mais intensa associada a ele.\n- Uma imagem ou palavra diretamente ligada ao pensamento.\nA leitura não acessa memórias, segredos escolhidos pelo Psíquico, conhecimento técnico completo nem respostas que não estejam sendo pensadas. Perguntas e acontecimentos poderão naturalmente direcionar o assunto da mente, mas não obrigam o alvo a pensar em algo específico.\nAo fim da tentativa, tendo resistido ou não, o alvo percebe que sua mente foi tocada e fica imune a novas tentativas do mesmo Psíquico até o fim da cena. O talento não pode ser usado em Pokémon durante batalhas.", "source": "https://app.notion.com/p/3e5508f8aa6c81219318f43838ddee31" },
	{ "id": "psiquico:mensagem-longinqua", "name": "Mensagem Longínqua", "kind": "class", "classId": "psiquico", "prerequisite": "nível 7 de Psíquico e Elo Telepático.**", "text": "**Pré-requisitos: nível 7 de Psíquico e Elo Telepático.**\nApós dez minutos de concentração, o Psíquico poderá enviar uma mensagem mental de até 25 palavras a uma criatura consciente que conheça pessoalmente e esteja na mesma região.\nO destinatário reconhece a identidade psíquica do remetente, poderá recusar a mensagem e, se aceitar, responder imediatamente com até 25 palavras. A capacidade não revela onde ele está e falha sem expor informações caso esteja inconsciente, fora da região ou protegido contra contato psíquico.\nCada manifestação transmite apenas uma mensagem e uma resposta; uma conversa prolongada exige novas concentrações de dez minutos.", "source": "https://app.notion.com/p/3e5508f8aa6c8140b4a6fdfea26db6c0" },
	{ "id": "psiquico:escudo-mental", "name": "Escudo Mental", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "A mente do Psíquico torna-se treinada contra intrusão e manipulação sobrenatural.\nEle recebe:\n```plain text\n+2 em Vontade contra leitura mental, controle, sugestão, alteração de memória ou detecção psíquica\n```\nSempre que resistir a um desses efeitos, percebe que houve uma tentativa e identifica a direção aproximada da origem, caso ela esteja a até 18 metros.\nO talento protege apenas o próprio Psíquico e não impede persuasão, enganação ou intimidação realizadas por meios normais.", "source": "https://app.notion.com/p/3e5508f8aa6c81d6b838ffaf4284ee0d" },
	{ "id": "psiquico:veu-psiquico", "name": "Véu Psíquico", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Escudo Mental.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Escudo Mental.**\nEnquanto mantiver concentração, o Psíquico encobre a própria presença mental. Percepções extrassensoriais deixam de detectá-lo automaticamente e tentativas de ler, localizar ou identificar sua mente exigem que o usuário supere a CD psíquica em um teste da capacidade utilizada.\nO véu não torna o Psíquico invisível, não oculta sons, rastros ou calor e termina caso ele utilize Leitura Superficial, Impulso Telecinético ou outra capacidade psíquica hostil contra uma criatura.", "source": "https://app.notion.com/p/3e5508f8aa6c81baa80dfe991929eced" },
	{ "id": "psiquico:psicometria", "name": "Psicometria", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "Após examinar por dez minutos um objeto ou um espaço delimitado, o Psíquico poderá perceber o vestígio emocional mais intenso deixado ali nos últimos trinta dias.\nO Mestre descreve uma impressão sensorial breve associada ao acontecimento, que poderá revelar:\n- A emoção predominante.\n- Se uma ou várias consciências participaram.\n- Uma imagem, som ou sensação marcante.\n- A direção pela qual a presença principal chegou ou partiu.\nPsicometria não reproduz o passado com exatidão, identifica pessoas, lê pensamentos antigos nem substitui Investigação. Um mesmo vestígio não fornecerá novas informações em tentativas repetidas, salvo quando forem encontradas novas evidências.", "source": "https://app.notion.com/p/3e5508f8aa6c815c97dce0c9ce5ed615" },
	{ "id": "psiquico:rastreamento-mental", "name": "Rastreamento Mental", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico.**", "text": "**Pré-requisito: nível 5 de Psíquico.**\nDepois de perceber uma mente com Percepção Extrassensorial, o Psíquico poderá se concentrar nela. O alvo realiza uma resistência de Vontade contra a CD psíquica.\nEm caso de falha, durante até um minuto o Psíquico conhece a direção e a distância aproximada daquela presença e consegue distingui-la das demais, mesmo que ela se mova atrás de obstáculos comuns.\nO efeito termina se o alvo sair de um raio de 60 metros, atravessar uma barreira que bloqueie percepção psíquica ou se a concentração for interrompida. Ele não revela identidade, pensamentos ou espécie. Uma criatura que resistir ficará imune a novas tentativas do mesmo Psíquico até o fim da cena.", "source": "https://app.notion.com/p/3e5508f8aa6c815d863ede7d41f642dc" },
	{ "id": "psiquico:sentido-de-perigo", "name": "Sentido de Perigo", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "A Percepção Extrassensorial do Psíquico permanece como um alerta instintivo mesmo quando não está sendo utilizada ativamente.\nEle não poderá ser surpreendido por uma criatura consciente que esteja dentro dos 6 metros de sua Percepção Extrassensorial, salvo se a criatura estiver ocultando deliberadamente sua presença psíquica e vencer a resistência ou teste aplicável.\nO talento não identifica a ameaça antes que ela aja, não revela armadilhas sem mente, máquinas automáticas, acidentes naturais ou a intenção exata de uma presença.", "source": "https://app.notion.com/p/3e5508f8aa6c81488d62fcc51c1cbbb6" },
	{ "id": "psiquico:premonicao-breve", "name": "Premonição Breve", "kind": "class", "classId": "psiquico", "prerequisite": "nível 7 de Psíquico e Sentido de Perigo.**", "text": "**Pré-requisitos: nível 7 de Psíquico e Sentido de Perigo.**\nUma fração de segundo antes de um perigo imediato atingir o Psíquico, sua mente recebe uma imagem do resultado mais provável.\nUma vez por cena, antes de realizar uma resistência ou teste para evitar diretamente um perigo contra si mesmo, poderá rolar duas vezes e utilizar o melhor resultado.\nA premonição não poderá alterar uma rolagem já resolvida, beneficiar outra criatura, prever decisões distantes nem modificar ações, golpes ou resultados de Pokémon em batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c8145abd6e134923eeb13" },
	{ "id": "psiquico:sintonia-psiquica-pokemon", "name": "Sintonia Psíquica Pokémon", "kind": "class", "classId": "psiquico", "prerequisite": "", "text": "O Psíquico aprende a harmonizar sua mente com um Pokémon disposto que possua o tipo Psíquico ou uma capacidade telepática natural.\nEnquanto o Pokémon estiver a até 18 metros e ambos mantiverem a sintonia, o Psíquico poderá escolher que sua Telepatia ou Percepção Extrassensorial tenha origem na posição do Pokémon. Ele continua sendo o usuário da capacidade e deverá manter a concentração normalmente.\nA sintonia não controla o Pokémon, não acessa seus sentidos sem Projeção Sensorial e termina imediatamente se ele deixar de cooperar. Durante uma batalha Pokémon, serve apenas para comunicação normal e não altera decisões, ações ou estatísticas.", "source": "https://app.notion.com/p/3e5508f8aa6c81ad9e5ff12fd50dc646" },
	{ "id": "psiquico:sonho-compartilhado", "name": "Sonho Compartilhado", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico e Elo Telepático.**", "text": "**Pré-requisitos: nível 5 de Psíquico e Elo Telepático.**\nAo tocar uma criatura consciente e disposta que esteja adormecendo, o Psíquico poderá estabelecer um espaço onírico compartilhado por até dez minutos enquanto mantiver concentração.\nDentro do sonho, ambos conversam e formam imagens simples a partir das próprias lembranças. Nenhum participante poderá acessar memórias que o outro não apresente voluntariamente, causar dano, implantar comandos ou alterar a personalidade do outro.\nO encontro não prejudica o descanso. Ao despertar, ambos recordam a conversa como recordariam um sonho vívido.", "source": "https://app.notion.com/p/3e5508f8aa6c81309e84fa77a2daec23" },
	{ "id": "psiquico:concentracao-inabalavel", "name": "Concentração Inabalável", "kind": "class", "classId": "psiquico", "prerequisite": "nível 5 de Psíquico.**", "text": "**Pré-requisito: nível 5 de Psíquico.**\nQuando sofrer dano, impacto, susto ou outra interrupção enquanto sustenta uma capacidade psíquica, o Psíquico realiza com vantagem o teste ou resistência exigido para manter sua concentração.\nA característica não permite concentrar-se sob uma condição que torne a concentração impossível, não sustenta dois efeitos ao mesmo tempo e não impede que o próprio Psíquico encerre um efeito ao iniciar outro.\nAumente também em 1 sua Constituição ou Sabedoria, respeitando o limite de atributos do sistema. Esta é a única melhoria de atributo disponível entre os talentos específicos do Psíquico.", "source": "https://app.notion.com/p/3e5508f8aa6c81549c08f854b70a4281" },
	{ "id": "psiquico:telecinese-soberana", "name": "Ápice — Telecinese Soberana", "kind": "apex", "classId": "psiquico", "prerequisite": "nível 10 de Psíquico e Telecinese Ampliada.**", "text": "**Pré-requisitos: nível 10 de Psíquico e Telecinese Ampliada.**\nA Telecinese Ampliada passa a alcançar 30 metros e poderá sustentar um objeto solto de até 250 quilogramas, movendo-o até 12 metros por rodada enquanto o Psíquico mantiver concentração.\nO Psíquico também poderá tentar conter ou mover uma pessoa dentro do alcance. O alvo realiza uma resistência de Fortitude contra a CD psíquica. Em caso de falha, poderá ser deslocado até 6 metros e ficará **Imobilizado** pela força telecinética. No fim de cada uma de suas ações, poderá repetir a resistência para se libertar.\nEnquanto mantiver alguém contido, o Psíquico não poderá manipular outro alvo com telecinese. A capacidade não esmaga, causa dano diretamente, afeta criaturas de tamanho incompatível com o limite de peso nem interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81bfad0afb817720c1b5" },
	{ "id": "psiquico:consciencia-coletiva", "name": "Ápice — Consciência Coletiva", "kind": "apex", "classId": "psiquico", "prerequisite": "nível 10 de Psíquico e Rede Telepática.**", "text": "**Pré-requisitos: nível 10 de Psíquico e Rede Telepática.**\nApós um minuto de preparação, o Psíquico poderá formar uma rede com até doze criaturas conscientes e dispostas que estejam na mesma região. A rede permanece por até uma hora enquanto ele mantiver concentração.\nCada participante poderá transmitir palavras, emoções e imagens simples aos demais. Um integrante poderá compartilhar voluntariamente sua visão ou audição; somente um conjunto de sentidos poderá ser compartilhado por vez, escolhido pelo Psíquico.\nA rede não revela pensamentos involuntários, não controla participantes e termina individualmente para quem ficar inconsciente ou retirar o consentimento. Durante batalhas Pokémon, continua limitada à comunicação normal e não concede coordenação mecânica, ações ou bônus.", "source": "https://app.notion.com/p/3e5508f8aa6c8170b097f22340601050" },
	{ "id": "psiquico:terceiro-olho", "name": "Ápice — Terceiro Olho", "kind": "apex", "classId": "psiquico", "prerequisite": "nível 10 de Psíquico.**", "text": "**Pré-requisito: nível 10 de Psíquico.**\nApós dez minutos de transe ininterrupto, o Psíquico poderá dirigir sua percepção para possibilidades próximas e formular uma pergunta:\n- Qual é o maior perigo provável nas próximas 24 horas?\n- Qual das rotas conhecidas oferece a passagem mais segura?\n- Em que direção se encontra uma criatura consciente conhecida que esteja na mesma região?\n- Qual é a consequência imediata mais provável de uma decisão que o grupo está prestes a tomar?\nO Mestre responde com uma visão verdadeira, porém simbólica e limitada ao futuro ou às circunstâncias mais prováveis naquele momento. A resposta não garante que o acontecimento ocorrerá, pois novas escolhas poderão alterar o resultado.\nApós utilizar Terceiro Olho, o Psíquico recebe um nível de **Exaustão**. Ele não poderá iniciar outro transe enquanto possuir qualquer nível de Exaustão.\nO ápice não revela estatísticas, resultados de rolagens, estratégias ocultas de uma batalha Pokémon ou certezas sobre eventos sujeitos a decisões ainda não tomadas.", "source": "https://app.notion.com/p/3e5508f8aa6c814095e0d50e2fa3532f" },
	{ "id": "tecnologo:especializacao-tecnica", "name": "Especialização Técnica", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Escolha uma área: **hardware, programação, redes, robótica, segurança digital, telecomunicações ou eletrônica**.\nQuando utilizar Tecnologia em uma tarefa diretamente relacionada à área escolhida, recebe:\n```plain text\n+2 em Tecnologia\n```\nO talento poderá ser escolhido novamente para uma área diferente. Os bônus não se acumulam quando mais de uma especialização se aplicar à mesma tarefa.", "source": "https://app.notion.com/p/3e5508f8aa6c81aabf25ef7aaf87aecf" },
	{ "id": "tecnologo:diagnostico-imediato", "name": "Diagnóstico Imediato", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo poderá utilizar Operador Universal após examinar um equipamento por uma ação, em vez de um minuto.\nAlém das informações normais, identifica se a falha aparente foi causada por desgaste, dano acidental, adulteração deliberada, alimentação inadequada ou programa incompatível.\nIsso não revela automaticamente o autor da adulteração, uma senha, o ponto exato de uma falha interna inacessível ou a solução completa.", "source": "https://app.notion.com/p/3e5508f8aa6c81c3828cccdb7044dca7" },
	{ "id": "tecnologo:engenharia-reversa", "name": "Engenharia Reversa", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Após estudar durante uma hora um dispositivo funcional ou seus projetos, o Tecnólogo poderá compreender um de seus mecanismos acessíveis.\nEm caso de sucesso em Tecnologia, poderá produzir documentação suficiente para:\n- Identificar componentes equivalentes.\n- Explicar a função do mecanismo.\n- Construir uma versão mundana da função estudada.\n- Integrar a função a uma máquina compatível.\nA cópia ainda exige ferramentas, materiais, tempo e licenças. Engenharia Reversa não replica Protótipos Tecnológicos de outro personagem, tecnologia alienígena incompreendida, propriedades de Pokémon nem mecanismos deliberadamente inacessíveis sem superar sua segurança.\nAumente também em 1 sua Inteligência, respeitando o limite de atributos do sistema.", "source": "https://app.notion.com/p/3e5508f8aa6c81f180c5fbb3b3b48304" },
	{ "id": "tecnologo:gambiarra-funcional", "name": "Gambiarra Funcional", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Com um Kit Tecnológico e dez minutos de trabalho, o Tecnólogo poderá restaurar provisoriamente um dispositivo mundano danificado que ainda possua seus componentes essenciais.\nO equipamento volta a executar uma função básica escolhida por até uma hora. Depois disso, para novamente e precisa de reparo verdadeiro. Se for submetido a esforço intenso ou utilizado fora da função escolhida, poderá falhar antes.\nA gambiarra não recupera cargas, munição, dados apagados ou peças ausentes e não reativa Protótipos Tecnológicos danificados.", "source": "https://app.notion.com/p/3e5508f8aa6c8193a53dec4c8ab92660" },
	{ "id": "tecnologo:recuperacao-forense", "name": "Recuperação Forense", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo poderá examinar durante dez minutos um computador, aparelho ou sistema de armazenamento ao qual tenha acesso físico.\nCom um teste de Tecnologia, poderá recuperar um dos seguintes elementos, caso ainda existam vestígios:\n- Último horário de utilização.\n- Dispositivos conectados recentemente.\n- Arquivo apagado de forma comum.\n- Trecho de registro de atividade.\n- Origem aproximada de uma alteração.\n- Indício de que dados foram adulterados.\nCriptografia, destruição física, sobrescrita segura ou limpeza especializada poderão impedir ou dificultar a recuperação. O talento não inventa dados inexistentes nem concede acesso automático a conteúdo ainda protegido.", "source": "https://app.notion.com/p/3e5508f8aa6c81febac2c74e634af3f8" },
	{ "id": "tecnologo:intrusao-digital", "name": "Intrusão Digital", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo poderá tentar superar uma proteção eletrônica, programa de autenticação ou fechadura digital utilizando Tecnologia, desde que possua acesso físico ou uma conexão válida ao sistema.\nEm caso de sucesso, escolhe um benefício compatível:\n- Abrir uma função protegida.\n- Criar um acesso temporário.\n- Suspender um alarme digital.\n- Consultar dados permitidos pelo nível alcançado.\n- Assumir o controle de um dispositivo simples conectado.\nO acesso dura somente durante a cena ou até o sistema ser reiniciado. Sistemas importantes poderão exigir várias etapas, credenciais, equipamento apropriado ou testes diferentes. Uma falha poderá gerar registros, bloqueio ou contramedidas. O talento não concede autoridade legal nem controle automático de redes inteiras.", "source": "https://app.notion.com/p/3e5508f8aa6c811ba695cf60d1099a42" },
	{ "id": "tecnologo:criptografia-adaptativa", "name": "Criptografia Adaptativa", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Após dez minutos de trabalho, o Tecnólogo poderá proteger um dispositivo, arquivo ou canal de comunicação próprio.\nTentativas de acessar ou alterar o conteúdo sem autorização deverão superar a CD de Tecnologia do Tecnólogo. Em caso de falha, o sistema registra horário, origem disponível e ação tentada.\nA proteção permanece até ser removida, o dispositivo ser restaurado ou alguém superá-la. Ela não impede destruição física, apreensão do equipamento ou acesso legítimo por credenciais que o Tecnólogo tenha autorizado.", "source": "https://app.notion.com/p/3e5508f8aa6c81359470c4c2c5891fd7" },
	{ "id": "tecnologo:rede-de-campo", "name": "Rede de Campo", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Com um Kit Tecnológico, uma carga e dez minutos de instalação, o Tecnólogo poderá interligar até seis dispositivos compatíveis dentro de um raio de 500 metros.\nA rede permite comunicação textual, transmissão de voz, compartilhamento de arquivos e localização relativa dos aparelhos conectados. Não depende de internet ou cobertura pública e permanece ativa por oito horas.\nBarreiras densas, interferência, dano aos transmissores ou distâncias maiores poderão interromper o sinal. A rede não fornece acesso a sistemas externos nem ignora a segurança de dispositivos conectados.", "source": "https://app.notion.com/p/3e5508f8aa6c81729335dd2f305c34e7" },
	{ "id": "tecnologo:automacao-de-rotina", "name": "Automação de Rotina", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Após programar durante dez minutos um dispositivo compatível, o Tecnólogo poderá fazê-lo repetir uma rotina simples por até oito horas.\nA rotina deverá possuir instruções objetivas do tipo:\n```plain text\nQuando X acontecer, execute Y.\nRepita Z a cada intervalo definido.\nInterrompa ao receber determinado sinal.\n```\nEla poderá acender luzes, registrar leituras, abrir uma porta autorizada, enviar alertas ou operar uma máquina em condições previsíveis.\nA automação não interpreta situações ambíguas, substitui uma pessoa em testes complexos, toma decisões morais, ataca criaturas ou interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c815fbaa4cf9de829e66b" },
	{ "id": "tecnologo:operador-de-drones", "name": "Operador de Drones", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Ao controlar um drone mundano ou um Protótipo Tecnológico em forma de drone, o Tecnólogo dobra a distância máxima de operação indicada pelo aparelho.\nAlém disso, poderá realizar manobras delicadas, atravessar passagens estreitas e pousar em superfícies difíceis utilizando Tecnologia no lugar da perícia normalmente exigida para pilotagem remota.\nO talento não aumenta velocidade, carga, autonomia, resistência ou capacidade ofensiva do drone e não permite utilizá-lo para interferir em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81e5ab60e5d7ede06a3f" },
	{ "id": "tecnologo:interface-remota", "name": "Interface Remota", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo poderá parear até seis dispositivos próprios ou autorizados. Enquanto estiverem a até 30 metros, poderá consultar seus estados e operar funções acessíveis sem tocá-los.\nA interface não concede funções que o aparelho não possui, não supera senhas, não atravessa interferência e não permite assumir o controle de equipamento alheio sem primeiro obter acesso válido.", "source": "https://app.notion.com/p/3e5508f8aa6c81a480abe9270408d036" },
	{ "id": "tecnologo:bloqueio-remoto", "name": "Bloqueio Remoto", "kind": "class", "classId": "tecnologo", "prerequisite": "Interface Remota.**", "text": "**Pré-requisito: Interface Remota.**\nO Tecnólogo poderá instalar em um dispositivo pareado um bloqueio de segurança. Enquanto houver comunicação, poderá desligá-lo, bloquear sua interface, apagar credenciais temporárias ou fazê-lo emitir um sinal de localização.\nO comando não destrói dados permanentes e poderá ser impedido por isolamento de sinal, remoção física do módulo ou uma intervenção que supere a CD de Tecnologia do criador.", "source": "https://app.notion.com/p/3e5508f8aa6c815ea8c7f0f0572b91b6" },
	{ "id": "tecnologo:compatibilidade-universal", "name": "Compatibilidade Universal", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Com um Kit Tecnológico, uma carga e dez minutos de trabalho, o Tecnólogo poderá montar um adaptador provisório entre dois dispositivos mundanos que utilizem conexões, tensões ou protocolos incompatíveis.\nO adaptador permite uma função de comunicação ou alimentação definida durante a construção e dura até oito horas.\nEle não cria energia, converte máquinas para finalidades novas, substitui peças essenciais nem conecta tecnologias cuja natureza o Tecnólogo ainda não compreenda.", "source": "https://app.notion.com/p/3e5508f8aa6c81efa472e68869031dd0" },
	{ "id": "tecnologo:economia-de-componentes", "name": "Economia de Componentes", "kind": "class", "classId": "tecnologo", "prerequisite": "nível 5 de Tecnólogo.**", "text": "**Pré-requisito: nível 5 de Tecnólogo.**\nAo construir um Protótipo Tecnológico que consuma duas ou mais cargas do Kit Tecnológico, o Tecnólogo reduz o custo em uma carga, até o mínimo de uma.\nA redução representa reaproveitamento de componentes e planejamento de circuito. Ela não reduz tempo, nível de kit, espaço, peso ou outros requisitos.", "source": "https://app.notion.com/p/3e5508f8aa6c819ca4bfc6ffc08c7454" },
	{ "id": "tecnologo:reprogramacao-rapida", "name": "Reprogramação Rápida", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo poderá desmontar a função especial de seu Protótipo Tecnológico ativo e construir outro protótipo inicial conhecido em dez minutos, em vez de uma hora.\nA reprogramação ainda consome uma carga do Kit Tecnológico e exige os componentes físicos compatíveis. O protótipo anterior torna-se mundano normalmente.\nProjetos Avançados continuam utilizando o próprio tempo de construção, salvo se outra capacidade disser o contrário.", "source": "https://app.notion.com/p/3e5508f8aa6c81089116f4132e2cbc78" },
	{ "id": "tecnologo:prototipos-paralelos", "name": "Protótipos Paralelos", "kind": "class", "classId": "tecnologo", "prerequisite": "nível 5 de Tecnólogo.**", "text": "**Pré-requisito: nível 5 de Tecnólogo.**\nO Tecnólogo aumenta em um a quantidade de Protótipos Tecnológicos que consegue manter ativos simultaneamente.\nCada protótipo continua sendo construído, abastecido e mantido separadamente. Criar um protótipo além do novo limite faz o Tecnólogo escolher qual programação anterior falha e se torna mundana.\nEste talento poderá ser escolhido duas vezes.", "source": "https://app.notion.com/p/3e5508f8aa6c81cba39aff9bfd2caa26" },
	{ "id": "tecnologo:oficina-improvisada", "name": "Oficina Improvisada", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "O Tecnólogo consegue organizar uma superfície estável como oficina temporária utilizando seu Kit Tecnológico.\nApós dez minutos de preparação, ignora penalidades causadas exclusivamente por iluminação ruim, espaço apertado, ausência de bancada ou organização precária durante até oito horas naquele local.\nA oficina não substitui energia, ferramentas especializadas, cargas, componentes, segurança ambiental ou instalações industriais exigidas pela tarefa.", "source": "https://app.notion.com/p/3e5508f8aa6c81b6b8c7caab8e4c8a82" },
	{ "id": "tecnologo:firewall-pessoal", "name": "Firewall Pessoal", "kind": "class", "classId": "tecnologo", "prerequisite": "", "text": "Os dispositivos pessoais, protótipos e canais criados pelo Tecnólogo recebem proteção ativa contra invasão.\nQuem tentar acessar, controlar ou adulterar remotamente esses sistemas realiza o teste com desvantagem. Quando uma tentativa falha, o Tecnólogo recebe um alerta e identifica o dispositivo atacado e a origem aproximada disponível na rede.\nO Firewall não impede acesso físico, credenciais legítimas ou destruição do equipamento.", "source": "https://app.notion.com/p/3e5508f8aa6c81e09178c2c3aae4e206" },
	{ "id": "tecnologo:projeto-avancado", "name": "Projeto Avançado", "kind": "class", "classId": "tecnologo", "prerequisite": "nível 5 de Tecnólogo.**", "text": "**Pré-requisito: nível 5 de Tecnólogo.**\nAo escolher este talento, o Tecnólogo aprende todos os Projetos Avançados descritos abaixo. Eles contam normalmente no limite de Protótipos Tecnológicos ativos.\nQualquer pessoa instruída poderá operar um Projeto Avançado, mas somente o Tecnólogo poderá construí-lo, programá-lo ou repará-lo. Cada projeto exige **Kit Tecnológico — Nível 2 ou superior**, quatro horas e as cargas indicadas.\n## Drone de Reconhecimento\n```plain text\nCusto: 4 cargas\nPeso: 1,2 kg\nEspaços: 2\n```\nVoa a até 300 metros do controle por até uma hora, transmitindo imagem e som. Possui luz, câmera e visão térmica simples. Não ataca, transporta itens, atravessa barreiras fechadas nem interfere em batalhas Pokémon.\n## Mapeador Tridimensional\n```plain text\nCusto: 3 cargas\nPeso: 1 kg\nEspaços: 1\n```\nAo ser transportado por uma área durante até uma hora, produz um mapa tridimensional do caminho, salas acessíveis, desníveis e obstáculos observados. Concede vantagem para refazer o percurso, mas não revela espaços que seus sensores não alcançaram.\n## Sonda de Resgate\n```plain text\nCusto: 4 cargas\nPeso: 1 kg\nEspaços: 1\n```\nDurante dez minutos, detecta respiração, movimento, calor e sinais vitais comuns em um raio de 18 metros. Indica quantidade e direção aproximada, mas não identifica espécie, condição clínica exata ou criaturas protegidas por barreiras densas.\n## Repetidor de Longo Alcance\n```plain text\nCusto: 3 cargas\nPeso: 0,8 kg\nEspaços: 1\n```\nDepois de instalado, amplia para 5 quilômetros o alcance de rádios e de uma Rede de Campo conectada. Relevo, blindagem e interferência poderão bloquear o sinal.\n## Camuflagem Óptica Estática\n```plain text\nCusto: 4 cargas\nPeso: 2 kg\nEspaços: 2\n```\nProjeta sobre uma pessoa ou objeto imóvel uma reprodução do ambiente. Enquanto permanecer parado, o usuário recebe +2 em Furtividade visual. Movimento encerra a camuflagem até que permaneça imóvel novamente por uma ação. Não concede invisibilidade nem funciona durante combate.\n## Exoesqueleto de Carga\n```plain text\nCusto: 4 cargas\nPeso: 4 kg equipado\nEspaços guardado: 3\n```\nQuando vestido, dobra a capacidade de carga do usuário e concede +2 em Atletismo para erguer, empurrar ou transportar peso. Não aumenta dano, velocidade ou aptidão para armas e não poderá ser vestido por Pokémon.\n## Decodificador de Protocolos\n```plain text\nCusto: 3 cargas\nPeso: 0,5 kg\nEspaços: 1\n```\nAnalisa durante dez minutos um protocolo eletrônico desconhecido e permite que o usuário realize Tecnologia para compreender comandos e formatos básicos. Não descobre senhas, decifra automaticamente conteúdo protegido nem traduz idiomas naturais.\n## Respirador Ambiental\n```plain text\nCusto: 4 cargas\nPeso: 2 kg\nEspaços guardado: 2\n```\nFornece ao usuário ar respirável por até uma hora e filtra fumaça, poeira, gases comuns e odores. Não protege a pele, não funciona debaixo d'água em grande profundidade e não bloqueia toxinas excepcionais sem um filtro específico.\n## Plataforma de Extração\n```plain text\nCusto: 4 cargas\nPeso: 3 kg\nEspaços guardada: 3\n```\nDispara e ancora um cabo em uma superfície apropriada a até 18 metros. O motor poderá erguer ou descer até 200 quilogramas em velocidade segura. Exige instalação estável, não funciona como arma e não poderá movimentar participantes de uma batalha Pokémon.\n## Limites dos Projetos Avançados\nEles não poderão criar energia ilimitada, inteligência artificial consciente, armas extraordinárias, efeitos psíquicos ou biológicos sem suporte apropriado, nem alterar Pokémon, seus golpes ou qualquer valor de combate. Outros projetos poderão ser descobertos durante a campanha se mantiverem potência, custo e limitações equivalentes.", "source": "https://app.notion.com/p/3e5508f8aa6c81fd818defa64f7e120b" },
	{ "id": "tecnologo:central-de-prototipos", "name": "Ápice — Central de Protótipos", "kind": "apex", "classId": "tecnologo", "prerequisite": "nível 10 de Tecnólogo e Protótipos Paralelos escolhido duas vezes.**", "text": "**Pré-requisitos: nível 10 de Tecnólogo e Protótipos Paralelos escolhido duas vezes.**\nO Tecnólogo poderá manter:\n```plain text\n5 Protótipos Tecnológicos ativos simultaneamente\n```\nAté dois deles poderão ser Projetos Avançados, se possuir esse talento.\nAlém disso, poderá monitorar energia, integridade e localização aproximada de todos os protótipos que estejam conectados à mesma Rede de Campo. Isso não permite operá-los sem Interface Remota nem remove seus limites individuais.\nCada protótipo continua exigindo construção, cargas, componentes e manutenção próprias.", "source": "https://app.notion.com/p/3e5508f8aa6c8174a63fee88b25040c8" },
	{ "id": "tecnologo:genio-tecnologico", "name": "Ápice — Gênio Tecnológico", "kind": "apex", "classId": "tecnologo", "prerequisite": "nível 10 de Tecnólogo.**", "text": "**Pré-requisito: nível 10 de Tecnólogo.**\nQuando realizar um teste de Tecnologia e o resultado natural do dado for inferior a 10, poderá tratá-lo como 10.\nAlém disso, ao examinar por uma ação uma máquina ou sistema acessível, poderá fazer ao Mestre uma pergunta técnica objetiva sobre seu funcionamento, falha, segurança ou forma de operação. A resposta será verdadeira dentro das informações que possam ser obtidas pelo equipamento e pelos conhecimentos existentes no cenário.\nO ápice não fornece senhas, componentes, autorização, dados que não estejam presentes nem compreensão automática de tecnologia inteiramente desconhecida.", "source": "https://app.notion.com/p/3e5508f8aa6c8155afc0e96c7e04fc2c" },
	{ "id": "tecnologo:obra-prima-modular", "name": "Ápice — Obra-Prima Modular", "kind": "apex", "classId": "tecnologo", "prerequisite": "nível 10 de Tecnólogo e Projeto Avançado.**", "text": "**Pré-requisitos: nível 10 de Tecnólogo e Projeto Avançado.**\nUtilizando um Kit Tecnológico — Nível 3, doze horas de trabalho e componentes adequados, o Tecnólogo poderá combinar dois Protótipos Tecnológicos conhecidos em uma única Obra-Prima Modular.\nA obra-prima:\n- Possui integralmente as duas funções escolhidas.\n- Conta como somente um Protótipo ativo.\n- Consome a soma das cargas dos projetos, mais duas cargas.\n- Possui o peso e os espaços somados dos dois dispositivos.\n- Exige que as funções sejam fisicamente compatíveis.\n- Somente poderá utilizar uma das funções por ação ou operação simultânea, salvo quando ambas forem passivas.\nO Tecnólogo poderá manter apenas uma Obra-Prima Modular por vez. Construir outra desativa a anterior normalmente.\nA combinação não remove limitações, não multiplica bônus, não transforma ferramentas em armas e não permite que uma função alimente ou amplifique a outra além do que cada projeto descreve.", "source": "https://app.notion.com/p/3e5508f8aa6c81758387f37e0d7361bd" },
	{ "id": "aprimoramento-de-atributo", "name": "Aprimoramento de Atributo", "kind": "general", "classId": null, "prerequisite": "", "text": "**Repetível:** até três vezes, escolhendo um atributo diferente em cada aquisição.\nAumente em 1 um dos seguintes atributos:\n- Força.\n- Destreza.\n- Constituição.\n- Inteligência.\n- Sabedoria.\n- Carisma.\nO novo valor deverá respeitar o limite de atributo definido para a campanha. Esse aumento modifica normalmente todas as estatísticas do treinador derivadas do atributo, mas nunca qualquer estatística de Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c8120bb1cc8f0762ea0ed" },
	{ "id": "resiliente", "name": "Resiliente", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha uma resistência na qual ainda não seja treinado: Fortitude, Reflexos ou Vontade.\nVocê se torna treinado na resistência escolhida.\n**Repetível:** poderá ser escolhido novamente para outra resistência. Nenhuma resistência poderá receber treinamento duas vezes por este talento.", "source": "https://app.notion.com/p/3e5508f8aa6c810cb13bc5f5b9d99c64" },
	{ "id": "robusto", "name": "Robusto", "kind": "general", "classId": null, "prerequisite": "", "text": "Seu máximo de PV aumenta em 1 para cada nível de treinador.\nO aumento é retroativo. Ao escolher este talento no nível 6, por exemplo, o máximo aumenta imediatamente em 6 PV e continuará aumentando em 1 a cada novo nível.\nEsse talento não altera dados de PV, recuperação, Defesa ou resistência.", "source": "https://app.notion.com/p/3e5508f8aa6c81f2854cd4df16fccf9a" },
	{ "id": "mente-firme", "name": "Mente Firme", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe vantagem em testes de Vontade feitos especificamente para resistir ou encerrar Amedrontado, Enfeitiçado, Fascinado, controle ou compulsão mental.\nO talento não concede imunidade e não se aplica a todo teste de Vontade indiscriminadamente.", "source": "https://app.notion.com/p/3e5508f8aa6c814a9d53e4095bf82501" },
	{ "id": "corpo-resistente", "name": "Corpo Resistente", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe vantagem em testes de Fortitude contra doenças, venenos, alimentos ou água contaminados e efeitos ambientais que provoquem náusea ou adoecimento.\nO talento não reduz dano nem concede imunidade.", "source": "https://app.notion.com/p/3e5508f8aa6c819a9a9efec719dbcc1a" },
	{ "id": "reflexo-de-sobrevivencia", "name": "Reflexo de Sobrevivência", "kind": "general", "classId": null, "prerequisite": "", "text": "Quando uma armadilha, queda de objeto, desabamento ou perigo ambiental permitir um teste de Reflexos, você recebe +2 nesse teste.\nO bônus não se aplica a ataques de Pokémon, golpes, precisão, efeitos de campo ou qualquer outra resolução de batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c811ea161c20d39124fb5" },
	{ "id": "treinamento-adicional", "name": "Treinamento Adicional", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha uma perícia na qual ainda não seja treinado. Você se torna treinado nela.\nSe a perícia possuir áreas, como Conhecimento, Ofício ou Pilotagem, escolha uma área específica.\n**Repetível:** poderá ser escolhido novamente para outra perícia ou área.", "source": "https://app.notion.com/p/3e5508f8aa6c81fe9301f178070f94bf" },
	{ "id": "foco-em-pericia", "name": "Foco em Perícia", "kind": "general", "classId": null, "prerequisite": "ser treinado na perícia escolhida.", "text": "**Pré-requisito:** ser treinado na perícia escolhida.\nEscolha uma perícia treinada. Você passa a possuir foco nela e utiliza as regras normais de foco do sistema.\nSe a perícia possuir áreas, o foco vale somente para a área escolhida.\n**Repetível:** poderá ser escolhido novamente para uma perícia ou área diferente.", "source": "https://app.notion.com/p/3e5508f8aa6c81a3a288c800fe561f4a" },
	{ "id": "conhecimento-diversificado", "name": "Conhecimento Diversificado", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha duas áreas diferentes de Conhecimento nas quais não seja treinado.\nAo realizar testes dessas áreas, você poderá adicionar metade do bônus de proficiência, arredondada para baixo.\nIsso não permite aplicações marcadas como **somente treinado** e não conta como treinamento para pré-requisitos.", "source": "https://app.notion.com/p/3e5508f8aa6c8153ad9ff0f2af55b89e" },
	{ "id": "ajuda-especializada", "name": "Ajuda Especializada", "kind": "general", "classId": null, "prerequisite": "ser treinado na perícia utilizada para ajudar.", "text": "**Pré-requisito:** ser treinado na perícia utilizada para ajudar.\nAo realizar uma ajuda válida com qualquer perícia em que seja treinado e obter sucesso, o bônus concedido ao aliado nunca será menor que +2.\nA qualidade da ajuda ainda poderá produzir bônus superior pelas regras normais. O atributo do ajudante poderá ser diferente quando a abordagem justificar.", "source": "https://app.notion.com/p/3e5508f8aa6c8161b1dccb4996ac957f" },
	{ "id": "aprendizado-por-observacao", "name": "Aprendizado por Observação", "kind": "general", "classId": null, "prerequisite": "", "text": "Depois de observar uma criatura treinada executar uma tarefa durante pelo menos dez minutos, você poderá repetir a mesma abordagem uma vez antes do próximo descanso longo.\nNesse teste, uma perícia não treinada poderá ser utilizada como se fosse treinada. Isso não concede foco, não satisfaz pré-requisitos e não reproduz características de classe, talentos ou poderes.", "source": "https://app.notion.com/p/3e5508f8aa6c81ffaabdca1a798cc838" },
	{ "id": "competencia-pratica", "name": "Competência Prática", "kind": "general", "classId": null, "prerequisite": "", "text": "Ao adquirir este talento, escolha uma perícia na qual você seja treinado e um atributo diferente do atributo normalmente usado por ela. Essa combinação fica registrada na ficha.\nAo fazer um teste da perícia escolhida, você pode usar o modificador do novo atributo no lugar do modificador habitual. O bônus de proficiência da perícia continua normal; os dois atributos não são somados.\n**Repetível:** você pode adquirir o talento novamente para outra perícia treinada, escolhendo o atributo alternativo dela.", "source": "https://app.notion.com/p/3e5508f8aa6c817aae64f9005e4c9ace" },
	{ "id": "corredor", "name": "Corredor", "kind": "general", "classId": null, "prerequisite": "", "text": "Seu deslocamento terrestre aumenta em 3 metros.\nEsse aumento vale somente para o treinador. Ele não aumenta a velocidade de Pokémon, montarias ou veículos e não concede ações adicionais.", "source": "https://app.notion.com/p/3e5508f8aa6c81d5b782d549dfd60c37" },
	{ "id": "escalador-treinado", "name": "Escalador Treinado", "kind": "general", "classId": null, "prerequisite": "treinamento em Atletismo.", "text": "**Pré-requisito:** treinamento em Atletismo.\nQuando possuir apoio, corda ou pontos de pegada adequados, escalar não custa deslocamento adicional.\nSuperfícies lisas, perigosas ou sem apoio continuam exigindo testes e poderão reduzir o deslocamento normalmente.", "source": "https://app.notion.com/p/3e5508f8aa6c81a9ad35f374d51139dc" },
	{ "id": "nadador-treinado", "name": "Nadador Treinado", "kind": "general", "classId": null, "prerequisite": "treinamento em Atletismo.", "text": "**Pré-requisito:** treinamento em Atletismo.\nNadar em água calma não custa deslocamento adicional. Você recebe +2 em Atletismo para resistir a correntezas, permanecer na superfície ou alcançar segurança.\nO talento não permite respirar debaixo d'água.", "source": "https://app.notion.com/p/3e5508f8aa6c81a2b81af69f7be67d13" },
	{ "id": "queda-controlada", "name": "Queda Controlada", "kind": "general", "classId": null, "prerequisite": "treinamento em Acrobacia.", "text": "**Pré-requisito:** treinamento em Acrobacia.\nAo cair conscientemente e possuir espaço para reagir, reduza em 3 metros a altura considerada no dano da queda.\nSe superar o teste de Acrobacia exigido pelo Mestre por 5 ou mais, reduza outros 3 metros. Não funciona inconsciente, imobilizado ou sem espaço para amortecer.", "source": "https://app.notion.com/p/3e5508f8aa6c8188a040dfd545e8f0c3" },
	{ "id": "carregador", "name": "Carregador", "kind": "general", "classId": null, "prerequisite": "", "text": "Sua capacidade máxima de peso aumenta em 50%.\nEsse aumento não cria espaços adicionais na Bag, não reduz espaços ocupados por itens volumosos e não altera a capacidade de veículos ou Pokémon de tração.", "source": "https://app.notion.com/p/3e5508f8aa6c813bac26ea24e6a771d2" },
	{ "id": "marcha-resistente", "name": "Marcha Resistente", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe vantagem no primeiro teste de Constituição ou Fortitude de cada jornada contra exaustão causada por marcha prolongada, falta de sono durante viagem ou esforço contínuo.\nNovos testes na mesma jornada são realizados normalmente. O talento não protege contra fome, sede ou clima extremo.", "source": "https://app.notion.com/p/3e5508f8aa6c813f9ccadfc6059b2ede" },
	{ "id": "iniciativa-aprimorada", "name": "Iniciativa Aprimorada", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe +3 em Iniciativa.\nEsse bônus determina somente a rapidez do treinador. Ele não altera a ordem, prioridade ou ações de Pokémon em batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c812ea85ee0a3f81714ba" },
	{ "id": "dominio-de-arma", "name": "Domínio de Arma", "kind": "general", "classId": null, "prerequisite": "para Ranged Exóticas:** possuir a licença exigida pela campanha.", "text": "Escolha um grupo de armas: Melee Comuns, Melee Exóticas, Ranged Antigas, Ranged Exóticas ou Não Letais.\nVocê adquire domínio no grupo escolhido.\n**Pré-requisito para Ranged Exóticas:** possuir a licença exigida pela campanha.\n**Repetível:** poderá ser escolhido novamente para outro grupo.", "source": "https://app.notion.com/p/3e5508f8aa6c81fd9751c35d0c337960" },
	{ "id": "dominio-de-escudos", "name": "Domínio de Escudos", "kind": "general", "classId": null, "prerequisite": "", "text": "Você adquire domínio de Escudos e poderá utilizá-los sem as penalidades de falta de domínio.\nO talento não fornece um escudo e não permite combinar mais melhorias de traje do que o limite normal.", "source": "https://app.notion.com/p/3e5508f8aa6c81ddbf3ac7bc6d4f8d31" },
	{ "id": "saque-rapido", "name": "Saque Rápido", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez em cada turno, você poderá sacar ou guardar um item pequeno acessível como parte da ação em que o utiliza.\nIsso não concede ação adicional, não permite trocar equipamento vestido instantaneamente e não altera as regras de arremesso ou captura com Poké Bolas.", "source": "https://app.notion.com/p/3e5508f8aa6c81688879f30c841b5733" },
	{ "id": "postura-defensiva", "name": "Postura Defensiva", "kind": "general", "classId": null, "prerequisite": "", "text": "Ao dedicar sua ação a se proteger, receba +2 de Defesa até o início do seu próximo turno.\nVocê deverá estar consciente e capaz de se mover. O bônus termina se realizar um ataque, correr ou abandonar voluntariamente a postura.", "source": "https://app.notion.com/p/3e5508f8aa6c8154a594ea5b882e6d73" },
	{ "id": "contencao-nao-letal", "name": "Contenção Não Letal", "kind": "general", "classId": null, "prerequisite": "", "text": "Ao declarar um ataque não letal contra uma pessoa antes da rolagem, você não sofre penalidade por conter a força.\nUma pessoa reduzida a 0 PV dessa forma fica inconsciente e estável, salvo se outro efeito já estiver causando risco de morte. O talento não funciona contra Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c819cb631d5eee63684a5" },
	{ "id": "campista", "name": "Campista", "kind": "general", "classId": null, "prerequisite": "treinamento em Sobrevivência.", "text": "**Pré-requisito:** treinamento em Sobrevivência.\nAo preparar um acampamento com equipamento apropriado e obter sucesso no teste, o abrigo protege o grupo contra penalidades comuns de sono causadas pelo terreno e pelo clima local.\nO talento não substitui roupas climáticas, alimento, água ou tratamento médico.", "source": "https://app.notion.com/p/3e5508f8aa6c8180b620d56e1295a8c6" },
	{ "id": "orientacao-natural", "name": "Orientação Natural", "kind": "general", "classId": null, "prerequisite": "", "text": "Você sempre consegue determinar os pontos cardeais quando houver referências naturais ou urbanas mínimas.\nAlém disso, recebe +2 em testes para evitar se perder, refazer um caminho percorrido ou interpretar mapas. Locais sobrenaturais ou deliberadamente mutáveis poderão anular a orientação automática.", "source": "https://app.notion.com/p/3e5508f8aa6c81ea8ff3d921db420aaf" },
	{ "id": "aclimatacao", "name": "Aclimatação", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha um ambiente: frio, calor, altitude, floresta úmida, deserto ou região costeira.\nVocê recebe vantagem em testes contra exaustão e desconforto provocados naturalmente por esse ambiente.\nEquipamento obrigatório continua necessário e o talento não reduz dano direto.\n**Repetível:** escolha outro ambiente.", "source": "https://app.notion.com/p/3e5508f8aa6c814ca4f9f9c3eb772b5d" },
	{ "id": "vigia-experiente", "name": "Vigia Experiente", "kind": "general", "classId": null, "prerequisite": "", "text": "Durante uma vigília, você recebe +2 em Percepção para notar aproximações, ruídos ou alterações no acampamento.\nSe estiver dormindo e ocorrer um sinal evidente de perigo, poderá despertar sem perder a primeira reação possível. Isso não impede emboscadas bem-sucedidas nem remove a necessidade de vigias.", "source": "https://app.notion.com/p/3e5508f8aa6c8159bafbd06471efe40c" },
	{ "id": "condutor-versatil", "name": "Condutor Versátil", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha uma categoria de Pilotagem em que você já seja treinado. Você recebe +2 nos testes de Pilotagem dessa categoria.\n**Repetível:** poderá ser escolhido para outra categoria treinada.", "source": "https://app.notion.com/p/3e5508f8aa6c81c9a1a5e726644847c6" },
	{ "id": "abridor-de-caminhos", "name": "Abridor de Caminhos", "kind": "general", "classId": null, "prerequisite": "treinamento em Sobrevivência.", "text": "**Pré-requisito:** treinamento em Sobrevivência.\nQuando lidera um grupo e obtém sucesso no teste de navegação, terreno difícil natural reduz o deslocamento de viagem do grupo pela metade do valor normal.\nO efeito não funciona durante combate, perseguições imediatas ou em obstáculos que exijam ferramentas especiais.", "source": "https://app.notion.com/p/3e5508f8aa6c81aba3c3d520e5ec861e" },
	{ "id": "poliglota", "name": "Poliglota", "kind": "general", "classId": null, "prerequisite": "", "text": "Você aprende dois idiomas adicionais disponíveis na campanha.\nTambém poderá criar ou decifrar cifras simples com um teste de Inteligência apropriado. Isso não permite compreender códigos especializados, idiomas desconhecidos ou escrita perdida sem evidências suficientes.", "source": "https://app.notion.com/p/3e5508f8aa6c812bb26fede6d60f6835" },
	{ "id": "etiqueta", "name": "Etiqueta", "kind": "general", "classId": null, "prerequisite": "", "text": "Após observar uma cerimônia, instituição ou ambiente formal por pelo menos dez minutos, você recebe +2 no primeiro teste de Persuasão ou Atuação feito para respeitar seus protocolos durante a cena.\nO bônus não muda a disposição de pessoas hostis nem concede acesso reservado por si só.", "source": "https://app.notion.com/p/3e5508f8aa6c81d4b0dbc43746732bc8" },
	{ "id": "rede-de-contatos", "name": "Rede de Contatos", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha uma região ou meio social, como comércio, universidade, esporte, transporte ou imprensa.\nAo chegar a uma comunidade onde esse meio exista, você poderá localizar um contato comum capaz de oferecer informação pública, indicação ou serviço regular.\nO contato não assume riscos, não fornece segredos nem trabalha gratuitamente.\n**Repetível:** escolha outra região ou meio.", "source": "https://app.notion.com/p/3e5508f8aa6c81d6b4ede58af42957c7" },
	{ "id": "apaziguador", "name": "Apaziguador", "kind": "general", "classId": null, "prerequisite": "", "text": "Quando um conflito entre pessoas ainda não começou, você recebe +2 em Persuasão para pedir uma pausa, estabelecer condições de conversa ou impedir uma escalada imediata.\nUma criatura já atacando, completamente hostil ou incapaz de compreender não será detida automaticamente. O talento não interfere em batalhas Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c815296c1f950207e17d2" },
	{ "id": "negociador-pratico", "name": "Negociador Prático", "kind": "general", "classId": null, "prerequisite": "treinamento em Persuasão.", "text": "**Pré-requisito:** treinamento em Persuasão.\nEm uma negociação direta com uma pessoa disposta a barganhar, um sucesso poderá melhorar em até 5% o preço de uma única compra ou venda.\nNão funciona em preços fixados pelo sistema, licenças, itens controlados, leilões, serviços públicos ou junto de outro efeito de alteração de preço.", "source": "https://app.notion.com/p/3e5508f8aa6c815e97abeef58ff658ec" },
	{ "id": "presenca-encorajadora", "name": "Presença Encorajadora", "kind": "general", "classId": null, "prerequisite": "", "text": "Após falar com aliados por pelo menos um minuto antes de uma situação perigosa, escolha até o seu bônus de proficiência em ouvintes.\nCada escolhido recebe +2 no primeiro teste de Vontade contra medo realizado durante a cena.\nA mesma pessoa somente poderá receber esse benefício uma vez por cena. O efeito não se aplica a Pokémon em batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c81339acae021111cf88b" },
	{ "id": "afinidade-pokemon", "name": "Afinidade Pokémon", "kind": "general", "classId": null, "prerequisite": "treinamento em Empatia Pokémon.", "text": "**Pré-requisito:** treinamento em Empatia Pokémon.\nVocê recebe +2 em Empatia Pokémon para acalmar, aproximar-se ou interpretar o comportamento de um Pokémon que não esteja hostil e não tenha entrado em confronto com você.\nO talento não melhora automaticamente a relação, não substitui alimento ou cuidado e não funciona durante batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c81e7b279d04d1c31aa24" },
	{ "id": "arremesso-treinado", "name": "Arremesso Treinado", "kind": "general", "classId": null, "prerequisite": "treinamento em Captura.", "text": "**Pré-requisito:** treinamento em Captura.\nVocê recebe +1 no teste de Captura realizado para acertar o arremesso de uma Poké Bola.\nO bônus atua somente no arremesso. Ele não modifica a probabilidade posterior de captura, não ignora Refletir e não recupera uma Poké Bola perdida.", "source": "https://app.notion.com/p/3e5508f8aa6c81db8066da2cc9a0fcae" },
	{ "id": "retirada-planejada", "name": "Retirada Planejada", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe +2 nas ações próprias do treinador feitas para organizar ou executar uma tentativa de fuga.\nO talento não garante sucesso, não existe em torneios e não altera Velocidade, ações, golpes ou qualquer estatística dos Pokémon envolvidos.", "source": "https://app.notion.com/p/3e5508f8aa6c81fa8e08e748f05b6d17" },
	{ "id": "linguagem-de-equipe", "name": "Linguagem de Equipe", "kind": "general", "classId": null, "prerequisite": "", "text": "Após praticar por dez minutos com um Pokémon disposto, escolha até seis sinais simples, como parar, aproximar-se, aguardar, apontar, buscar ou recuar.\nO Pokémon reconhecerá esses sinais enquanto puder percebê-los e compreender a tarefa.\nIsso não concede ações, prioridade, precisão ou ordens adicionais em batalha Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81be80dfe1b953a89e12" },
	{ "id": "cuidados-de-campo", "name": "Cuidados de Campo", "kind": "general", "classId": null, "prerequisite": "treinamento em Medicina Pokémon e domínio do Kit de Medicina Pokémon.", "text": "**Pré-requisitos:** treinamento em Medicina Pokémon e domínio do Kit de Medicina Pokémon.\nVocê recebe +2 em testes realizados fora de batalha para diagnosticar uma condição, estabilizar um Pokémon ou aplicar corretamente um tratamento já disponível.\nO talento não recupera PV por si só e não substitui Centro Pokémon, medicamentos ou tempo de recuperação.", "source": "https://app.notion.com/p/3e5508f8aa6c81f682cdd6159be36275" },
	{ "id": "observador-de-especies", "name": "Observador de Espécies", "kind": "general", "classId": null, "prerequisite": "", "text": "Depois de observar um Pokémon por pelo menos dez minutos fora de combate, receba +2 no teste de Conhecimento apropriado para identificar espécie, hábitos, alimentação, habitat ou sinais visíveis de saúde.\nO talento não revela golpes, IVs, EVs, habilidade, natureza, estatísticas ocultas ou informações que não possam ser observadas.", "source": "https://app.notion.com/p/3e5508f8aa6c815083b8cd656df938c1" },
	{ "id": "dominio-de-kit", "name": "Domínio de Kit", "kind": "general", "classId": null, "prerequisite": "", "text": "Escolha um kit cujo requisito de perícia você cumpra. Você adquire domínio desse kit.\nKits sem requisito poderão ser escolhidos normalmente. O talento não concede o próprio kit, treinamento na perícia nem cargas.\n**Repetível:** poderá ser escolhido novamente para outro kit.", "source": "https://app.notion.com/p/3e5508f8aa6c81c8be73e53f7cbfdb85" },
	{ "id": "uso-cuidadoso", "name": "Uso Cuidadoso", "kind": "general", "classId": null, "prerequisite": "domínio do kit utilizado.", "text": "**Pré-requisito:** domínio do kit utilizado.\nUma vez por cena, quando falhar por até 2 pontos em um teste com kit que normalmente consumiria uma carga, a carga não será consumida.\nA ação continua falhando e qualquer tempo empregado é perdido. Falhas graves e materiais consumidos independentemente do resultado não são preservados.", "source": "https://app.notion.com/p/3e5508f8aa6c816dac32df5fc56e1123" },
	{ "id": "manutencao-preventiva", "name": "Manutenção Preventiva", "kind": "general", "classId": null, "prerequisite": "", "text": "Durante um descanso curto, você poderá revisar um equipamento mundano que possua as ferramentas apropriadas para manter.\nAté o próximo descanso longo, a primeira falha comum causada por desgaste desse equipamento será ignorada. O teste da ação ainda poderá falhar por outros motivos.\nNão funciona em protótipos, registros, itens consumíveis ou equipamentos destruídos.", "source": "https://app.notion.com/p/3e5508f8aa6c81b49293f5605eb03a31" },
	{ "id": "inventario-organizado", "name": "Inventário Organizado", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por turno, você poderá retirar da Bag um item pequeno e acessível como parte da ação em que o utiliza.\nIsso não cria espaços, não reduz peso, não permite vestir equipamentos instantaneamente e não modifica as regras de uso de Poké Bolas durante batalha.", "source": "https://app.notion.com/p/3e5508f8aa6c81699910ddefc0d2eb67" },
	{ "id": "distribuicao-de-carga", "name": "Distribuição de Carga", "kind": "general", "classId": null, "prerequisite": "", "text": "O peso dos itens que estiverem corretamente vestidos ou presos ao corpo conta como 25% menor para sua capacidade pessoal de carga.\nOs espaços ocupados não mudam. Itens dentro da Bag, carregados nas mãos, volumosos ou transportados para outra pessoa mantêm o peso normal.", "source": "https://app.notion.com/p/3e5508f8aa6c812f9836cd2cfcfee16f" },
	{ "id": "documentacao-em-ordem", "name": "Documentação em Ordem", "kind": "general", "classId": null, "prerequisite": "", "text": "Você recebe +2 em testes para solicitar, renovar ou comprovar licenças de itens e atividades legalmente disponíveis.\nO talento não reduz taxas, não elimina prazos, não garante aprovação e não permite obter licença proibida ao personagem ou à região.", "source": "https://app.notion.com/p/3e5508f8aa6c81218655db3c4f4b5a05" },
	{ "id": "sortudo", "name": "Sortudo", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por descanso longo, depois de ver o resultado de um teste próprio de d20, você poderá repetir a rolagem.\nVocê deverá aceitar o segundo resultado. O talento não poderá repetir tabelas aleatórias, rolagens do Mestre ou rolagens realizadas por Pokémon.", "source": "https://app.notion.com/p/3e5508f8aa6c81c08d9fe7ff82970716" },
	{ "id": "determinado", "name": "Determinado", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por descanso longo, ao falhar em um teste de Fortitude, Reflexos ou Vontade, você poderá repetir o teste.\nO segundo resultado deverá ser aceito. Escolha usar o talento antes que as consequências da falha sejam resolvidas.", "source": "https://app.notion.com/p/3e5508f8aa6c81889547c7716b6d43db" },
	{ "id": "esforco-heroico", "name": "Esforço Heroico", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por descanso longo, após falhar em um teste próprio de perícia, você poderá transformar a falha em um sucesso comum sem fazer outra rolagem. Ao usar o talento, recebe imediatamente um nível de Exaustão.\nVocê não pode usá-lo se já estiver no penúltimo ou último nível de Exaustão.", "source": "https://app.notion.com/p/3e5508f8aa6c81638d72f7afaac85e10" },
	{ "id": "improviso-decisivo", "name": "Improviso Decisivo", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por descanso longo, você poderá realizar como treinado um teste de perícia em que não possua treinamento.\nIsso permite a tentativa de uma aplicação **somente treinado**, desde que não exija domínio de kit, licença, poder psíquico, característica de classe ou conhecimento impossível de improvisar.", "source": "https://app.notion.com/p/3e5508f8aa6c81a39f08e00b9bbc6f33" },
	{ "id": "segundo-folego", "name": "Segundo Fôlego", "kind": "general", "classId": null, "prerequisite": "", "text": "Uma vez por descanso longo, utilizando uma ação e estando consciente, você recupera:\n```javascript\n1d6 + modificador de Constituição em PV\n```\nO valor mínimo recuperado é 1. Esse efeito atua somente no treinador e não remove condições, ferimentos graves ou Exaustão.", "source": "https://app.notion.com/p/3e5508f8aa6c81f19fb0cac6c320a9a6" },
	{ "id": "sobrevivente", "name": "Sobrevivente", "kind": "general", "classId": null, "prerequisite": "nível 6.", "text": "**Pré-requisito:** nível 6.\nUma vez por descanso longo, quando um dano reduziria você a 0 PV sem causar morte imediata, permaneça com 1 PV.\nO talento não funciona contra execução, dano massivo suficiente para morte instantânea ou quando já estiver a 0 PV.", "source": "https://app.notion.com/p/3e5508f8aa6c811197cacf05e53f47d3" },
];
